Code_Content:
// the overridden signatures need to be assignment compatible, but
// due to how tuple types work[0] it's not possible to be assignment
// compatible anymore. This hack fixes it with a unique symbol that
// won't ever show up in parameter help etc.
//
// Unfortunately, this has the result of giving a poor error message when
// you mix up types.
// 0: https://github.com/Microsoft/TypeScript/issues/26013)
declare const assignmentCompatibilityHack: unique symbol;

// Returns any keys of TRecord with the type of TMatch
export type MatchingKeys<
  TRecord,
  TMatch,
  K extends keyof TRecord = keyof TRecord
> = K extends (TRecord[K] extends TMatch ? K : never) ? K : never;

// Returns any property keys of Record with a void type
export type VoidKeys<Record> = MatchingKeys<Record, void>;

// TODO: Stash under a symbol key once TS compiler bug is fixed
export interface TypeRecord<T, U, V> {
  ' _emitterType'?: T;
  ' _eventsType'?: U;
  ' _emitType'?: V;
}

export type ReturnTypeOfMethod<T> = T extends (...args: any[]) => any
  ? ReturnType<T>
  : void;

export type ReturnTypeOfMethodIfExists<T, S extends string> = S extends keyof T
  ? ReturnTypeOfMethod<T[S]>
  : void;

export type InnerEEMethodReturnType<T, TValue, FValue> = T extends (
  ...args: any[]
) => any
  ? ReturnType<T> extends void | undefined ? FValue : TValue
  : FValue;

export type EEMethodReturnType<
  T,
  S extends string,
  TValue,
  FValue = void
> = S extends keyof T ? InnerEEMethodReturnType<T[S], TValue, FValue> : FValue;

export type ListenerType<T> = [T] extends [(...args: infer U) => any]
  ? U
  : [T] extends [void] ? [] : [T];

// EventEmitter method overrides
export type OverriddenMethods<
  TEmitter,
  TEventRecord,
  TEmitRecord = TEventRecord
> = {
  on<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'on', T>;
  on(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  addListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'addListener', T>;
  addListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  addEventListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'addEventListener', T>;
  addEventListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  removeListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: any[]) => any
  ): EEMethodReturnType<TEmitter, 'removeListener', T>;
  removeListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  removeEventListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: any[]) => any
  ): EEMethodReturnType<TEmitter, 'removeEventListener', T>;
  removeEventListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  once<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'once', T>;
  once(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  emit<P extends keyof TEmitRecord, T>(
    this: T,
    event: P,
    ...args: ListenerType<TEmitRecord[P]>
  ): EEMethodReturnType<TEmitter, 'emit', T>;
  emit(event: typeof assignmentCompatibilityHack, ...args: any[]): void;
};

export type OverriddenKeys = keyof OverriddenMethods<any, any, any>;

export type StrictEventEmitter<
  TEmitterType,
  TEventRecord,
  TEmitRecord = TEventRecord,
  UnneededMethods extends Exclude<OverriddenKeys, keyof TEmitterType> = Exclude<
    OverriddenKeys,
    keyof TEmitterType
  >,
  NeededMethods extends Exclude<OverriddenKeys, UnneededMethods> = Exclude<
    OverriddenKeys,
    UnneededMethods
  >
> =
  // Store the type parameters we've instantiated with so we can refer to them later
  TypeRecord<TEmitterType, TEventRecord, TEmitRecord> &
    // Pick all the methods on the original type we aren't going to override
    Pick<TEmitterType, Exclude<keyof TEmitterType, OverriddenKeys>> &
    // Finally, pick the needed overrides (taking care not to add an override for a method
    // that doesn't exist)
    Pick<
      OverriddenMethods<TEmitterType, TEventRecord, TEmitRecord>,
      NeededMethods
    >;

export default StrictEventEmitter;

export type NoUndefined<T> = T extends undefined ? never : T;

export type StrictBroadcast<
  TEmitter extends TypeRecord<any, any, any>,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >,
  VK extends VoidKeys<TEmitRecord> = VoidKeys<TEmitRecord>,
  NVK extends Exclude<keyof TEmitRecord, VK> = Exclude<keyof TEmitRecord, VK>
> = {
  <E extends NVK>(event: E, request: TEmitRecord[E]): any;
  <E extends VK>(event: E): any;
};

export type EventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEmitRecord | keyof TEventRecord;

export type OnEventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEventRecord;

export type EmitEventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEmitRecord;

// This is free and unencumbered software released into the public domain

import shuffleSeed from "./shuffle_seed.ts";

const NORM_2D = 1.0 / 47.0;
const SQUISH_2D = (Math.sqrt(2 + 1) - 1) / 2;
const STRETCH_2D = (1 / Math.sqrt(2 + 1) - 1) / 2;

export type Noise2D = (x: number, y: number) => number;

interface Contribution2D {
  dx: number;
  dy: number;
  next?: Contribution2D;
  xsb: number;
  ysb: number;
}

function contribution2D(
  multiplier: number,
  xsb: number,
  ysb: number,
): Contribution2D {
  return {
    dx: -xsb - multiplier * SQUISH_2D,
    dy: -ysb - multiplier * SQUISH_2D,
    xsb,
    ysb,
  };
}

export function makeNoise2D(clientSeed: number): Noise2D {
  const contributions: Contribution2D[] = [];
  for (let i = 0; i < p2D.length; i += 4) {
    const baseSet = base2D[p2D[i]];
    let previous: Contribution2D | null = null;
    let current: Contribution2D | null = null;
    for (let k = 0; k < baseSet.length; k += 3) {
      current = contribution2D(baseSet[k], baseSet[k + 1], baseSet[k + 2]);
      if (previous === null) contributions[i / 4] = current;
      else previous.next = current;
      previous = current;
    }
    current!.next = contribution2D(p2D[i + 1], p2D[i + 2], p2D[i + 3]);
  }
  const lookup: Contribution2D[] = [];
  for (let i = 0; i < lookupPairs2D.length; i += 2) {
    lookup[lookupPairs2D[i]] = contributions[lookupPairs2D[i + 1]];
  }

  const perm = new Uint8Array(256);
  const perm2D = new Uint8Array(256);
  const source = new Uint8Array(256);
  for (let i = 0; i < 256; i++) source[i] = i;
  let seed = new Uint32Array(1);
  seed[0] = clientSeed;
  seed = shuffleSeed(shuffleSeed(shuffleSeed(seed)));
  for (let i = 255; i >= 0; i--) {
    seed = shuffleSeed(seed);
    const r = new Uint32Array(1);
    r[0] = (seed[0] + 31) % (i + 1);
    if (r[0] < 0) r[0] += i + 1;
    perm[i] = source[r[0]];
    perm2D[i] = perm[i] & 0x0e;
    source[r[0]] = source[i];
  }

  return (x: number, y: number): number => {
    const stretchOffset = (x + y) * STRETCH_2D;

    const xs = x + stretchOffset;
    const ys = y + stretchOffset;

    const xsb = Math.floor(xs);
    const ysb = Math.floor(ys);

    const squishOffset = (xsb + ysb) * SQUISH_2D;

    const dx0 = x - (xsb + squishOffset);
    const dy0 = y - (ysb + squishOffset);

    const xins = xs - xsb;
    const yins = ys - ysb;

    const inSum = xins + yins;
    const hash = (xins - yins + 1) |
      (inSum << 1) |
      ((inSum + yins) << 2) |
      ((inSum + xins) << 4);

    let value = 0;

    for (
      let c: Contribution2D | undefined = lookup[hash];
      c !== undefined;
      c = c.next
    ) {
      const dx = dx0 + c.dx;
      const dy = dy0 + c.dy;

      const attn = 2 - dx * dx - dy * dy;
      if (attn > 0) {
        const px = xsb + c.xsb;
        const py = ysb + c.ysb;

        const indexPartA = perm[px & 0xff];
        const index = perm2D[(indexPartA + py) & 0xff];

        const valuePart = gradients2D[index] * dx + gradients2D[index + 1] * dy;

        value += attn * attn * attn * attn * valuePart;
      }
    }

    return value * NORM_2D;
  };
}

const base2D = [
  [1, 1, 0, 1, 0, 1, 0, 0, 0],
  [1, 1, 0, 1, 0, 1, 2, 1, 1],
];

const gradients2D = [
  5,
  2,
  2,
  5,
  -5,
  2,
  -2,
  5,
  5,
  -2,
  2,
  -5,
  -5,
  -2,
  -2,
  -5,
];

const lookupPairs2D = [
  0,
  1,
  1,
  0,
  4,
  1,
  17,
  0,
  20,
  2,
  21,
  2,
  22,
  5,
  23,
  5,
  26,
  4,
  39,
  3,
  42,
  4,
  43,
  3,
];

const p2D = [
  0,
  0,
  1,
  -1,
  0,
  0,
  -1,
  1,
  0,
  2,
  1,
  1,
  1,
  2,
  2,
  0,
  1,
  2,
  0,
  2,
  1,
  0,
  0,
  0,
];

import initHelpButton from './initHelpButton';
import initSongSelector from './initSongSelector';
import initWaveformSelector from './initWaveformSelector';
import './style.css'

type ValidFFTSizeStringType = '2048' | '1024' | '512';

const audioElement = document.querySelector('audio');
const html = document.querySelector('html');
const canvas = document.querySelector('canvas');
const overlayControls = document.querySelector('.overlay-controls');
const canvasContext = canvas?.getContext('2d');
const FFT_SIZE_TO_RADIUS_MAP = {
  '2048': Math.floor(((2048 / 2) / Math.PI) - 80),
  '1024': Math.floor(((1024 / 2) / Math.PI) - 80),
  '512': Math.floor(((512 / 2) / Math.PI) - 80)
};
const FFT_SIZE_TO_WAVE_HEIGHT_MAP = {
  '2048': 0.5,
  '1024': 0.4,
  '512': 0.3
}
const MIN_FFT_SIZE = 512;

let WIDTH = 1280;
let HEIGHT = 320;
let FFT_SIZE = 2048;
let isNotAPlayPauseTouch = false;
let currentAudioURL = '';
let currentWaveform = 'sinewave'
let previousTouch: (undefined | Touch);
let audioContext: (undefined | null | AudioContext),
  gainNode: (undefined | GainNode),
  mediaElementNode: (undefined | MediaElementAudioSourceNode),
  analyserNode: (undefined | AnalyserNode),
  animationCancelId: (undefined | number);

if (audioElement) {
  audioElement.src = currentAudioURL;
}

/* SETUP */
const setupAudioContext = () => {

  if (!audioElement) {
    return null;
  }

  audioContext = new AudioContext();
  mediaElementNode = audioContext.createMediaElementSource(audioElement);
  gainNode = audioContext.createGain();
  analyserNode = audioContext.createAnalyser();

  gainNode.gain.value = 1;

  if (audioContext.state === 'suspended') {
    audioContext.resume();
  }

  // Do not forget to connect the node to a destination
  mediaElementNode.connect(analyserNode);
  analyserNode.connect(gainNode);
  gainNode.connect(audioContext.destination);
};

/* ANIMATION OPERATIONS */

const drawSineWave = () => {
  if (!analyserNode || !canvas || !canvasContext) {
    return;
  }

  animationCancelId = requestAnimationFrame(drawSineWave);

  analyserNode.fftSize = FFT_SIZE;
  const byteTimeDomainData = new Uint8Array(analyserNode.fftSize);
  analyserNode.getByteTimeDomainData(byteTimeDomainData);

  canvasContext.fillStyle = 'black';
  canvasContext.fillRect(0, 0, WIDTH, HEIGHT);
  canvasContext.strokeStyle = 'white';

  const xAxisSeparation = WIDTH / (analyserNode.fftSize);
  const START_Y = HEIGHT / 2 + 128;

  canvasContext.beginPath();
  // canvasContext.moveTo(0, START_Y);

  byteTimeDomainData.forEach((value, index) => {
    const x = index * xAxisSeparation;
    const y = START_Y - value;

    canvasContext.lineTo(x, y);
  });

  canvasContext.stroke();
};

// Parts of this code are Adapted from standard coding samples
// Specifically the logic to calculate the angle inside the for loop
// was AI generated. I was trying to use the Mid point circle algorithm
// but the AI used trigonometric method (this is supposed to be slower
// but I was blocked in my approach).
const drawCircle = () => {
  if (!canvas || !canvasContext || !analyserNode) {
    return;
  }

  animationCancelId = requestAnimationFrame(drawCircle);

  const numPoints = FFT_SIZE;
  const centerX = canvas.width / 2;
  const centerY = canvas.height / 2;
  const radius = FFT_SIZE_TO_RADIUS_MAP[('' + numPoints) as ValidFFTSizeStringType];
  const points = [];

  // Clear the screen for the current animation frame
  canvasContext.fillStyle = 'black';
  canvasContext.fillRect(0, 0, canvas.width, canvas.height);

  // Set the stroke style
  canvasContext.strokeStyle = 'white';

  analyserNode.fftSize = FFT_SIZE;
  const byteTimeDomainData = new Uint8Array(analyserNode.fftSize);
  analyserNode.getByteTimeDomainData(byteTimeDomainData);

  for (let i = 0; i < numPoints; i++) {
    // Calculating the angle of a given point by using formula:
    // (index/total) * 360
    // When index/total is 1 i.e index === total, then angle will be
    // 360 degrees.
    let angle = (i / numPoints) * 2 * Math.PI;

    // x = r * cos(theta)
    // Adding byteTimeDomainData[i] to r because we want the point to
    // represent the amplitude of the wave.
    let x = centerX + (radius + byteTimeDomainData[i]) * Math.cos(angle);
    // y = r * sin(theta)
    let y = centerY + (radius + byteTimeDomainData[i]) * Math.sin(angle);

    // Store the points in an array for later access
    points.push({x: x, y: y});
  }

  canvasContext.beginPath();
  for (let i = 0; i < points.length; i++) {
    canvasContext.lineTo(points[i].x, points[i].y);
  }
  canvasContext.stroke();
}

/* AUDIO OPERATIONS */

const playPauseAudio = () => {
  if (!audioElement) {
    return;
  }

  if (!audioContext) {
    setupAudioContext();
  }

  if (audioElement.paused) {
    audioElement.play();
    currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();
  }
  else {
    audioElement.pause();
    animationCancelId !== undefined && cancelAnimationFrame(animationCancelId);
  }
}

const increaseVolume = (delta = 0.1) => {
  const gain = gainNode?.gain;

  if (gain === undefined) {
    return;
  }

  const newValue = gain.value + delta;
  (newValue < 2) && (gain.value = newValue);
}

const decreaseVolume = (delta = 0.1) => {
  const gain = gainNode?.gain;

  if (gain === undefined) {
    return;
  }

  const newValue = gain.value - delta;
  (newValue > 0) && (gain.value = newValue);
}

/* RESIZE HANDLER */
const resizeObserver = new ResizeObserver((entries) => {
  for (let entry of entries) {
    if (entry.borderBoxSize) {
      WIDTH = entry.borderBoxSize[0].inlineSize;
      HEIGHT = entry.borderBoxSize[0].blockSize;

      if (canvas && canvasContext) {
        canvas.width = WIDTH;
        canvas.height = HEIGHT;

        canvasContext.fillStyle = "black";
        canvasContext.fillRect(0, 0, canvas.width, canvas.height);
      }

      const bestFFTSizeBasedOnWidth = Object.entries(FFT_SIZE_TO_RADIUS_MAP).sort((a, b) => b[1] - a[1]).find(([key, value]) => {
        // @ts-ignore
        return 2 * (value + FFT_SIZE_TO_WAVE_HEIGHT_MAP[key] * 500) < WIDTH
      });

      console.log(bestFFTSizeBasedOnWidth)
      FFT_SIZE = bestFFTSizeBasedOnWidth ? Number.parseInt(bestFFTSizeBasedOnWidth[0]) : MIN_FFT_SIZE;

      currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();

      return;
    }
  }
});


/* EVENT HANDLERS */
const handleKeyDown = (e: KeyboardEvent) => {
  const { key } = e;

  if (!audioContext && !(e.metaKey || e.altKey || e.ctrlKey)) {
    setupAudioContext();
  }

  switch (key) {
    case ' ': {
      playPauseAudio();
      break;
    }

    case 'ArrowUp': {
      increaseVolume();
      break;
    }

    case 'ArrowDown': {
      decreaseVolume();
      break;
    }
  }
}

const handleTouchEnd = () => {
  if (isNotAPlayPauseTouch) {

    // Cleanup
    isNotAPlayPauseTouch = false;
    previousTouch = undefined;
    return;
  }

  playPauseAudio();
}

const handleTouchMove = (e: TouchEvent) => {
  // This is a touch move and not just a touch.
  // i.e. the user wants to increase or decrease their volume.
  // Setting isNotAPlayPauseTouch will ensure that the music does not
  // stop/start playing.
  isNotAPlayPauseTouch = true;

  // There was no previous touch
  // The user has not indicated whether they want to increase or decrease
  // volume. So, we retun.
  if (!previousTouch) {
    return;
  }

  const currentTouch = e.changedTouches[0];

  if (currentTouch.clientY > previousTouch.clientY) {
    decreaseVolume();
  }
  else {
    increaseVolume();
  }

  previousTouch = currentTouch;
}

const handleTouchStart = (e: TouchEvent) => {
  previousTouch = e.changedTouches[0];
}

const songSelectorCallback = (url: string) => {
  if (!audioElement) {
    return;
  }

  audioElement.src = url;
  playPauseAudio();
}

const waveformSelectorCallback = (option: string) => {
  if (!audioElement) {
    return;
  }

  currentWaveform = option;

  typeof animationCancelId === 'number'  && cancelAnimationFrame(animationCancelId);

  currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();
}

/* INITIALIZE OTHER UI ELEMENTS */
initSongSelector(songSelectorCallback);
initWaveformSelector(waveformSelectorCallback);
initHelpButton();

/* REGISTER EVENT LISTENERS */
window.addEventListener('keydown', handleKeyDown);
window.addEventListener('touchstart', handleTouchStart);
window.addEventListener('touchend', handleTouchEnd);
window.addEventListener('touchmove', handleTouchMove);
overlayControls && overlayControls.addEventListener('touchend', (e) => { e.stopPropagation(); });
overlayControls && overlayControls.addEventListener('touchmove', (e) => { e.stopPropagation(); });
resizeObserver.observe(html as HTMLHtmlElement);

