import { ApiPromise, WsProvider } from '@polkadot/api';
import { getSpecTypes } from '@polkadot/types-known';
import { BlockNumber, Hash } from '@polkadot/types/interfaces';
import { logger } from '@polkadot/util';

import { prisma } from './generated/prisma-client';
import { nomidotTasks } from './tasks';
import { Cached } from './tasks/types';

const ARCHIVE_NODE_ENDPOINT =
  process.env.ARCHIVE_NODE_ENDPOINT || 'wss://kusama-rpc.polkadot.io/';
const MAX_LAG = process.env.MAX_LAG || 0;

const l = logger('node-watcher');

function waitFinalized(
  api: ApiPromise,
  lastKnownBestFinalized: number
): Promise<{ unsub: () => void; bestFinalizedBlock: number }> {
  return new Promise(resolve => {
    async function wait(): Promise<void> {
      const unsub = await api.derive.chain.bestNumberFinalized(best => {
        if (best.toNumber() > lastKnownBestFinalized) {
          resolve({ unsub, bestFinalizedBlock: best.toNumber() });
        }
      });
    }

    wait();
  });
}

function reachedLimitLag(
  blockIndex: number,
  lastKnownBestBlock: number
): boolean {
  return MAX_LAG ? lastKnownBestBlock - blockIndex > parseInt(MAX_LAG) : false;
}

function waitLagLimit(
  api: ApiPromise,
  blockIndex: number
): Promise<{ unsub: () => void; bestBlock: number }> {
  return new Promise(resolve => {
    async function wait(): Promise<void> {
      const unsub = await api.derive.chain.bestNumber(bestBlock => {
        if (reachedLimitLag(blockIndex, bestBlock.toNumber())) {
          resolve({ unsub, bestBlock: bestBlock.toNumber() });
        }
      });
    }

    wait();
  });
}

export async function nodeWatcher(): Promise<unknown> {
  return new Promise((_, reject) => {
    let keepLooping = true;
    const provider = new WsProvider(ARCHIVE_NODE_ENDPOINT);

    ApiPromise.create({ provider })
      .then(async api => {
        api.once('error', e => {
          keepLooping = false;
          api.disconnect();
          reject(new Error(`Api error: ${e}`));
        });

        api.once('disconnected', e => {
          keepLooping = false;
          api.disconnect();
          reject(new Error(`Api disconnected: ${e}`));
        });

        const blockIdentifier = process.env.BLOCK_IDENTIFIER || 'IDENTIFIER';
        let blockIndexId = '';
        let blockIndex = parseInt(process.env.START_FROM || '0');
        let currentSpecVersion = api.createType('u32', -1);
        const lastKnownBestFinalized = (
          await api.derive.chain.bestNumberFinalized()
        ).toNumber();
        let lastKnownBestBlock = (
          await api.derive.chain.bestNumber()
        ).toNumber();

        const existingBlockIndex = await prisma.blockIndexes({
          where: {
            identifier: blockIdentifier,
          },
        });

        if (existingBlockIndex.length === 0) {
          const result = await prisma.createBlockIndex({
            identifier: blockIdentifier,
            startFrom: blockIndex,
            index: blockIndex,
          });

          blockIndexId = result.id;
        } else {
          blockIndexId = existingBlockIndex[0].id;
          blockIndex = existingBlockIndex[0].index;
        }

        /*eslint no-constant-condition: ["error", { "checkLoops": false }]*/
        while (keepLooping) {
          if (MAX_LAG) {
            // if we reached the last finalized block
            // MAX_LAG is set but we haven't reached the lag limit yet, we need to wait
            if (
              blockIndex > lastKnownBestFinalized &&
              !reachedLimitLag(blockIndex, lastKnownBestBlock)
            ) {
              l.warn(
                `Waiting for finalization or a max lag of ${MAX_LAG} blocks.`
              );
              const { unsub, bestBlock } = await waitLagLimit(api, blockIndex);
              unsub && unsub();
              lastKnownBestBlock = bestBlock;
              continue;
            }
          } else {
            // MAX_LAG isn't set, only the finalization matters
            if (blockIndex > lastKnownBestFinalized) {
              l.warn('Waiting for finalization.');
              const { unsub, bestFinalizedBlock } = await waitFinalized(
                api,
                lastKnownBestFinalized
              );
              unsub && unsub();
              lastKnownBestBlock = bestFinalizedBlock;
              continue;
            }
          }

          l.warn(`blockIndex: ${blockIndex}`);
          l.warn(`lastKnownBestBlock: ${lastKnownBestBlock}`);
          l.warn(`lastKnownBestFinalized: ${lastKnownBestFinalized}`);

          const blockNumber: BlockNumber = api.createType(
            'BlockNumber',
            blockIndex
          );
          l.warn(`block: ${blockNumber}`);

          const blockHash: Hash = await api.rpc.chain.getBlockHash(blockNumber);
          l.warn(`hash: ${blockHash}`);

          // check spec version
          const runtimeVersion = await api.rpc.state.getRuntimeVersion(
            blockHash
          );
          const newSpecVersion = runtimeVersion.specVersion;

          // if spec version was bumped, update metadata in api registry
          if (newSpecVersion.gt(currentSpecVersion)) {
            l.warn(
              `bumped spec version to ${newSpecVersion}, fetching new metadata`
            );
            const rpcMeta = await api.rpc.state.getMetadata(blockHash);
            currentSpecVersion = newSpecVersion;

            // based on the node spec & chain, inject specific type overrides
            const chain = await api.rpc.system.chain();
            api.registry.register(
              getSpecTypes(
                api.registry,
                chain,
                runtimeVersion.specName,
                runtimeVersion.specVersion
              )
            );
            api.registry.setMetadata(rpcMeta);
          }

          const [events, sessionIndex] = await Promise.all([
            await api.query.system.events.at(blockHash),
            await api.query.session.currentIndex.at(blockHash),
          ]);

          const cached: Cached = {
            events,
            sessionIndex,
          };

          // execute watcher tasks
          for await (const task of nomidotTasks) {
            l.warn(`Task --- ${task.name}`);

            const result = await task.read(blockHash, cached, api);

            try {
              l.warn(`Writing: ${JSON.stringify(result)}`);
              await task.write(blockNumber, result);
            } catch (e) {
              // Write task might throw errors such as unique constraints violated,
              // we ignore those.
              l.error(e);
            }
          }

          blockIndex += 1;

          await prisma.updateBlockIndex({
            data: {
              index: blockIndex,
            },
            where: {
              id: blockIndexId,
            },
          });
        }
      })
      .catch(e => {
        keepLooping = false;
        reject(new Error(`Connection error: ${e}`));
      });
  });
}

/**
 * Storing ABIs in Human-Readable ABI format.
 * https://blog.ricmoo.com/human-readable-contract-abis-in-ethers-js-141902f4d917
 */

export const TokenAbi = "tuple(address address, string name, string symbol, uint256 decimals)";
export const TokenPriceAbi = "tuple(address address, uint256 priceUsdc)";
export const TokenBalanceAbi = `tuple(
  address address, 
  uint256 priceUsdc, 
  uint256 balance,
  uint256 balanceUsdc
)`;
export const AllowanceAbi = "tuple(address owner, address spender, uint256 amount, address token)";

export const AssetStaticAbi = `tuple(
  address address,
  string typeId,
  address token,
  string name,
  string version,
  string symbol,
  uint8 decimals,
)`;

export const AssetDynamicAbi = (Metadata: string): string => `tuple(
  address address, 
  string typeId,
  address tokenId,
  tuple(uint256 amount, uint256 amountUsdc) underlyingTokenBalance,
  ${Metadata} metadata
)`;

export const PositionAbi =
  "tuple(address assetAddress, address tokenAddress, string typeId, uint256 balance," +
  "tuple(uint256 amount, uint256 amountUsdc) underlyingTokenBalance," +
  "tuple(address owner, address spender, uint256 amount)[] tokenAllowances," +
  "tuple(address owner, address spender, uint256 amount)[] assetAllowances)";

export const AdapterAbi = (Metadata: string): string[] => [
  `function assetsStatic() public view returns (${AssetStaticAbi}[] memory)`,
  `function assetsStatic(address[] memory) public view returns (${AssetStaticAbi}[] memory)`,
  `function assetsDynamic() public view returns (${AssetDynamicAbi(Metadata)}[] memory)`,
  `function assetsDynamic(address[] memory) public view returns (${AssetDynamicAbi(Metadata)}[] memory)`,
  `function assetsPositionsOf(address) public view returns (${PositionAbi}[] memory)`,
  `function assetsPositionsOf(address, address[] memory) public view returns (${PositionAbi}[] memory)`,
  `function assetsTokensAddresses() public view returns (address[] memory)`,
];

export const AddressMetadataAbi = `tuple(string addrId, address addr)`;

import { Comparator } from '../comparator';

describe('comparator', () => {
  it('single field', () => {
    const c = new Comparator(['id']);

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
    )).toBeTruthy();

    expect(c.equal(
      {uuId: false, name: 'A'},
      {uuId: false, name: 'B'},
      ['uuId']
    )).toBeTruthy();

    expect(c.equal(
      {uuId: null, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: {}, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: [], name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: undefined, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: undefined, name: 'A'},
      {uuId: undefined, name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {name: 'A'},
      {name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {path: 'body/div', name: 'A'},
      {path: 'body/div', name: 'B'},
      ['path']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
      [['id']]
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
      ['id', 'name']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {name: 'A'},
      ['id', 'name']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 1, name: 'A'},
      ['id', 'name']
    )).toBeFalsy();
  });

  it('multiple fields', () => {
    const c = new Comparator([['id', 'status']]);

    expect(c.equal(
      {id: 0, name: 'A', status: 'N'},
      {id: 0, name: 'B', status: 'N'},
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A', status: 'N'},
      {id: 1, name: 'B', status: 'N'},
    )).toBeFalsy();

    expect(c.equal(
      {id: false, name: 'B', status: 'N'},
      {id: false, name: 'B', status: 'M'},
      [['id', 'name']]
    )).toBeTruthy();

    expect(c.equal(
      {id: false, name: 'B', status: 'N'},
      {id: false, name: 'B', status: 'M'},
      [['id', 'status'], ['name']]
    )).toBeTruthy();

  });

});

describe('Test Supported via standard programming aids', () => {
  let comparator: Comparator;

  beforeEach(() => {
    comparator = new Comparator();
  });

  describe('equal()', () => {
    it('should return true for two identical objects', () => {
      const obj1 = {uuId: '123', id: '456'};
      const obj2 = {uuId: '123', id: '456'};
      expect(comparator.equal(obj1, obj2)).toBe(true);
    });

    it('should return true for two objects with the same values for the specified fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '123', id: '456', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id'])).toBe(true);
    });

    it('should return false for two objects with different values for the specified fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '789', id: '987', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id'])).toBe(false);
    });

    it('should return false for two objects with different values for the default fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '789', id: '987', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2)).toBe(false);
    });

    it('should return false for two objects with different types', () => {
      const obj1 = {uuId: '123', id: '456'};
      const obj2 = ['123', '456'];
      expect(comparator.equal(obj1, obj2)).toBe(false);
    });

    it('should return false for two objects with different values for nested fields', () => {
      const obj1 = {uuId: '123', id: '456', data: {name: 'Jane Doe'}};
      const obj2 = {uuId: '789', id: '987', data: {name: 'John Doe'}};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id', 'data.name'])).toBe(false);
    });

    it('should return true for two objects with same values for nested fields', () => {
      const obj1 = {uuId: '123', id: '456', data: {name: 'Jane Doe'}};
      const obj2 = {uuId: '789', id: '987', data: {name: 'Jane Doe'}};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id', 'data.name'])).toBe(false);
    });

  });
});

