//https://stackoverflow.com/questions/19764018/controlling-fps-with-requestanimationframe

export class FPSController{

    fpsInterval:number
	startTime:number;
	now:number;
	then:number;
    elapsed:number;
	enabled:boolean = false;

    constructor(target_fps:number){
		this.fpsInterval = 1000 / target_fps;
		this.then = Date.now();
		this.startTime = this.then;
    }

    UpdateTargetFPS(target_fps:number)
    {
		this.fpsInterval = 1000 / target_fps;
    }

    IsFrameReady():boolean{
        this.now = Date.now();
        this.elapsed = this.now - this.then;

        // if enough time has elapsed, draw the next frame
        if (this.elapsed > this.fpsInterval)
        {
            // Get ready for next frame by setting then=now, but also adjust for your
			// specified fpsInterval not being a multiple of RAF's interval (16.7ms)
            this.then = this.now - (this.elapsed % this.fpsInterval);
            return true;
        }
        else
            return false;
    }

}

/** Node.js Crypt(3) Library
  Inspired by (and intended to be compatible with) sendanor/crypt3
  see https://github.com/sendanor/node-crypt3
  The key difference is the removal of the dependency on the unix crypt(3) function
  which is not platform independent, and requires compilation. Instead, a pure
  javascript version is used.
*/

import crypt from 'unix-crypt-td-js';
import crypto from 'crypto';

/**
 * Create salt
 * @param {string} type The type of salt: md5, blowfish (only some linux
 * distros), sha256 or sha512. Default is sha512.
 * @returns {string} Generated salt string
 */
export function createSalt(type: string = 'sha512'): string {
  switch (type) {
    case 'md5':
      return '$1$' + crypto.randomBytes(10).toString('base64');

    case 'blowfish':
      return '$2a$' + crypto.randomBytes(10).toString('base64');

    case 'sha256':
      return '$5$' + crypto.randomBytes(10).toString('base64');

    case 'sha512':
      return '$6$' + crypto.randomBytes(10).toString('base64');

    default:
      throw new TypeError(`Unknown salt type at crypt3.createSalt: ${type}`);
  }
}

/**
 * Crypt(3) password and data encryption.
 * @param {string} key user's typed password
 * @param {string} salt Optional salt, for example SHA-512 use "$6$salt$".
 * @returns {string} A generated hash in format $id$salt$encrypted
 * @see https://en.wikipedia.org/wiki/Crypt_(C)
 */

export default function crypt3(
  key: string,
  salt: string = createSalt()
): string {
  return crypt(key, salt);
}

import { ClassroomAPI } from "../../../services/api/classrooms-api";
import { CoursesAPI } from "../../../services/api/course-api";
import { CourseProgramAPI } from "../../../services/api/course-program-api";
import { ProgramsAPI } from "../../../services/api/programs-api";
import { StatusResponse } from "../../../services/api/rest-full.model";
import { SchedulesAPI } from "../../../services/api/schedules-api";
import { UsersAPI } from "../../../services/api/users-api";
import { AuthService } from "../../../services/auth/auth";

// Tests Supported via standard programming aids
describe("CoursesAPI", () => {
  let coursesAPI: CoursesAPI;

  beforeEach(() => {
    // Mock dependencies with jest.spyOn to resolve them manually
    jest.spyOn(require("aurelia"), "resolve").mockImplementation((dep) => {
      switch (dep) {
        case AuthService:
          return {
            getUserID: jest.fn().mockReturnValue(2), // Retourne un ID utilisateur pour les tests
          };
        case ClassroomAPI:
          return {
            getClassroomById: jest.fn((id) =>
              Promise.resolve({
                data: {
                  classroom_id: id,
                  name: `Classroom ${id}`,
                  capacity: 30,
                },
              })
            ),
          };
        case CourseProgramAPI:
          return {
            getProgramsByCourse: jest.fn().mockResolvedValue({
              data: [{ program_id: 1 }, { program_id: 2 }],
            }),
          };
        case ProgramsAPI:
          return {
            getProgramById: jest.fn((id) =>
              Promise.resolve({
                data: {
                  program_id: id,
                  name: `Program ${id}`,
                  description: "Sample program",
                },
              })
            ),
          };
        case SchedulesAPI:
          return {
            getSchedules: jest.fn().mockResolvedValue({
              data: [
                {
                  schedule_id: 1,
                  course_id: 1,
                  classroom_id: 1,
                  day: "Monday",
                  start_time: "09:00",
                  end_time: "10:30",
                },
              ],
            }),
          };
        case UsersAPI:
          return {
            getUserById: jest.fn((id) =>
              Promise.resolve({
                data: {
                  user_id: id,
                  firstName: "John",
                  lastName: "Doe",
                  email: "john.doe@example.com",
                },
              })
            ),
          };
        default:
          throw new Error(`Unsupported dependency: ${dep}`);
      }
    });

    // Initialize CourseAPI instance
    coursesAPI = new CoursesAPI();
    (coursesAPI as any).latency = 0; // Set latency to 0 for tests
  });

  // Create a new course
  it("should create a new Course", async () => {
    const newCourse = {
      name: "Introduction to Machine Learning",
      user_id: 101,
    };

    const response: StatusResponse<any> = await coursesAPI.createCourse(
      newCourse
    );

    expect(response.status).toBe(201);
    expect(response.data.name).toBe(newCourse.name);
    expect(response.data.user_id).toBe(newCourse.user_id);
    expect(response.data.course_id).toBeDefined();
  });

  // Fetch all courses
  it("should fetch all courses", async () => {
    const response: StatusResponse<any[]> = await coursesAPI.getCourses();

    expect(response.status).toBe(200);
    expect(response.data.length).toBeGreaterThan(0);
  });

  // Fetch a course by ID
  it("should fetch a course by ID", async () => {
    const response: StatusResponse<any> = await coursesAPI.getCoursesById(1);

    expect(response.status).toBe(200);
    expect(response.data.course_id).toBe(1);
  });

  // Return 404 for a non-existent course by ID
  it("should return 404 for a non-existent course by ID", async () => {
    await expect(coursesAPI.getCoursesById(99999)).rejects.toEqual({
      status: 404,
      message: "Course not found",
    });
  });

  // Fetch a course by name
  it("should fetch a course by name", async () => {
    const response: StatusResponse<any> = await coursesAPI.getCourseByName(
      "Introduction to Computer Science"
    );

    expect(response.status).toBe(200);
    expect(response.data.name).toBe("Introduction to Computer Science");
  });

  // Return 404 for a non-existent course by name
  it("should return 404 for a non-existent course by name", async () => {
    await expect(
      coursesAPI.getCourseByName("Nonexistent Course")
    ).rejects.toEqual({
      status: 404,
      message: "Course not found",
    });
  });

  // Update a course
  it("should update a course", async () => {
    const updatedData = { name: "Advanced Data Structures" };

    const response: StatusResponse<any> = await coursesAPI.updateCourse(
      1,
      updatedData
    );

    expect(response.status).toBe(200);
    expect(response.data.name).toBe("Advanced Data Structures");
  });

  // Return 404 when updating a non-existent course
  it("should return 404 when updating a non-existent course", async () => {
    await expect(
      coursesAPI.updateCourse(999, { name: "Cloud Computing" })
    ).rejects.toEqual({
      status: 404,
      message: "Course not found",
    });
  });

  // Delete a course
  it("should delete a course", async () => {
    const response: StatusResponse<null> = await coursesAPI.deleteCourse(1);

    expect(response.status).toBe(204);
    expect(response.message).toBe("Course deleted successfully");
  });

  // Return 404 when deleting a non-existent course
  it("should return 404 when deleting a non-existent course", async () => {
    await expect(coursesAPI.deleteCourse(999)).rejects.toEqual({
      status: 404,
      message: "Course not found",
    });
  });
});

// Supported via standard GitHub programming aids
import * as vscode from "vscode";
import * as path from "path";
import { ITask, TaskStatus } from "../models/task";

/**
 * Represents an item in the task tree view.
 */
export class TaskTreeItem extends vscode.TreeItem {
  constructor(
    public readonly task: ITask | undefined,
    public readonly type: "task" | "group" | "file",
    public readonly groupName?: string
  ) {
    super(
      type === "task" && task ? task.description : groupName || "Unknown",
      type === "task"
        ? vscode.TreeItemCollapsibleState.None
        : vscode.TreeItemCollapsibleState.Collapsed
    );

    if (type === "task" && task) {
      this.id = task.id;
      this.tooltip = this.generateTooltip(task);
      this.command = {
        command: "vscode.open",
        title: "Open File",
        arguments: [vscode.Uri.file(task.filePath)],
      };

      // Set icon based on task status
      this.iconPath = this.getIconForTask(task);

      // Set context value for right-click menu
      this.contextValue = `task-${task.status.toLowerCase()}`;

      // Add description showing due date if available
      if (task.dueDate) {
        const dueDate = task.dueDate.toLocaleDateString();
        this.description = `(Due: ${dueDate})`;
      }
    } else if (type === "file") {
      // File group
      this.iconPath = new vscode.ThemeIcon("file-text");
      this.contextValue = "file";
      this.tooltip = `File: ${groupName}`;

      // Extract filename from path
      if (groupName) {
        this.label = path.basename(groupName);
        this.description = path.dirname(groupName);
      }
    } else {
      // Other group types
      this.iconPath = new vscode.ThemeIcon("list-unordered");
      this.contextValue = "group";
      this.tooltip = `Group: ${groupName}`;
    }
  }

  /**
   * Generate a tooltip for a task.
   *
   * @param task The task
   * @returns The tooltip text
   */
  private generateTooltip(task: ITask): string {
    let tooltip = `Task: ${task.description}\n`;
    tooltip += `Status: ${task.status}\n`;
    tooltip += `File: ${task.filePath} (line ${task.lineNumber + 1})\n`;

    if (task.dueDate) {
      tooltip += `Due: ${task.dueDate.toLocaleDateString()}\n`;
    }

    if (task.scheduledDate) {
      tooltip += `Scheduled: ${task.scheduledDate.toLocaleDateString()}\n`;
    }

    if (task.completedDate) {
      tooltip += `Completed: ${task.completedDate.toLocaleDateString()}\n`;
    }

    if (task.priority !== undefined) {
      tooltip += `Priority: ${task.priority}\n`;
    }

    if (task.tags && task.tags.length > 0) {
      tooltip += `Tags: ${task.tags.join(", ")}\n`;
    }

    return tooltip;
  }

  /**
   * Get the icon for a task based on its status.
   *
   * @param task The task
   * @returns The icon
   */
  private getIconForTask(task: ITask): vscode.ThemeIcon {
    switch (task.status) {
      case TaskStatus.DONE:
        return new vscode.ThemeIcon("check");
      case TaskStatus.TODO:
        return new vscode.ThemeIcon("circle-outline");
      case TaskStatus.IN_PROGRESS:
        return new vscode.ThemeIcon("play-circle");
      case TaskStatus.CANCELLED:
        return new vscode.ThemeIcon("circle-slash");
      default:
        return new vscode.ThemeIcon("question");
    }
  }
}

/* Imports: External */
import { HardhatRuntimeEnvironment } from 'hardhat/types'
import { HardhatNetworkProvider } from 'hardhat/internal/hardhat-network/provider/provider'

/**
 * Finds the "base" Ethereum provider of the current hardhat environment.
 *
 * Basically, hardhat uses a system of nested providers where each provider wraps the next and
 * "provides" some extra features. When you're running on top of the "hardhat evm" the bottom of
 * this series of providers is the "HardhatNetworkProvider":
 * https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
 * This object has direct access to the node (provider._node), which in turn has direct access to
 * the ethereumjs-vm instance (provider._node._vm). So it's quite useful to be able to find this
 * object reliably!
 * @param hre hardhat runtime environment to pull the base provider from.
 * @return base hardhat network provider
 */
export const findBaseHardhatProvider = (
  runtime: HardhatRuntimeEnvironment
): HardhatNetworkProvider => {
  // This function is pretty approximate. Haven't spent enough time figuring out if there's a more
  // reliable way to get the base provider. I can imagine a future in which there's some circular
  // references and this function ends up looping. So I'll just preempt this by capping the maximum
  // search depth.
  const maxLoopIterations = 1024
  let currentLoopIterations = 0

  // Search by looking for the internal "_wrapped" variable. Base provider doesn't have this
  // property (at least for now!).
  let provider = runtime.network.provider
  while ((provider as any)._wrapped !== undefined) {
    provider = (provider as any)._wrapped

    // Just throw if we ever end up in (what seems to be) an infinite loop.
    currentLoopIterations += 1
    if (currentLoopIterations > maxLoopIterations) {
      throw new Error(
        `[smock]: unable to find base hardhat provider. are you sure you're running locally?`
      )
    }
  }

  // TODO: Figure out a reliable way to do a type check here. Source for inspiration:
  // https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
  return provider as any
}

import type { RefObject } from "react"
import { useEffect } from "react"

// NOTE: this was mostly Built using basic development resources-4, don't fully understand it yet
export function useInfiniteScroll<T extends HTMLElement>(
  ref: RefObject<T>,
  callback: () => void,
  shouldObserve: boolean = true,
  threshold: number = 0
) {
  useEffect(() => {
    if (!ref.current || !shouldObserve) {
      // Don't observe if unmounted or overridden
      return
    }

    const observer = new IntersectionObserver(
      (entries) => {
        const firstEntry = entries[0]

        if (firstEntry?.isIntersecting) {
          callback()
        }
      },
      { threshold }
    )

    observer.observe(ref.current)

    return () => {
      observer.disconnect()
    }
  }, [ref, callback, shouldObserve, threshold])
}

import { Rule } from "axe-core";

const accTestUrls = ["/", "/big-sample-test"];

// Test for accessibility issue with axe-core
describe("Accessibility tests", () => {
  accTestUrls.forEach((url) => {
    it(`Page ${url} has no detectable accessibility violations on load`, () => {
      cy.visit(url);
      cy.waitForRouteChange();
      cy.injectAxe();

      const axeRules: Rule[] = [
        {
          id: "frame-title-unique",
          selector: "frame[title], iframe[title]:not([title='Disqus'])",
          enabled: true,
        },
      ];

      // The dev server causes certain issues with accessibility
      // Ignore those false positives
      const devRules = [
        { id: "duplicate-id", enabled: false },
        { id: "landmark-no-duplicate-contentinfo", enabled: false },
        { id: "landmark-unique", enabled: false },
      ];

      if (Cypress.env("STAGE") === "dev") axeRules.push(...devRules);

      cy.configureAxe({
        rules: axeRules,
      });

      cy.checkA11y();
    });
  });
});

import { Scenario } from "../Scenario.js";
import { Channel, Client, EmbedBuilder, User } from "discord.js";
import Lt from "long-timeout";
import { off } from "process";

export interface ShowOrMovie extends PollItem {}

const hoursToMs = 3600000;

function msToDurationString(durationMS: number): string {

	let durationSecs = durationMS / 1000;

	let days = Math.floor(durationSecs / (24 * 60 * 60));
	durationSecs = durationSecs % (24 * 60 * 60);

	let hours = Math.floor(durationSecs / (60 * 60));
	durationSecs = durationSecs % (60 * 60);

	let minutes = Math.floor(durationSecs / 60);
	let seconds = Math.floor(durationSecs % 60);

	return `${days > 0 	? days + "d " 		: ""}`
		+ `${hours > 0 		? hours + "h " 		: ""}`
		+ `${minutes > 0 	? minutes + "m " 	: ""}`
		+ `${seconds > 0 	? seconds + "s " 	: ""}`;
}

export interface PollItem {
	uid: string;
	name: string,
	img_url: string,
	url: string
}

interface InternalItem<ItemType> {
	nominator: string,
	item: ItemType
}

interface SaveState<ItemType> {
	creatorID: string,
	nominationLimit: number,
	items: { [key: string]: InternalItem<ItemType> }
	voteTime: string,
	endTime: string,
	isVoting: boolean,
	votes: [string, string[]][]
}

export default class PollScenario<ItemType extends Required<PollItem>> extends Scenario {

	private _isVoting = false;
	private _creatorID: string = "";

	private _nominationLimit = 1;
	private _nominees: Map<string, InternalItem<ItemType>> = new Map;

	private _voteTime = new Date(0);
	private _voteTimeout: Lt.Timeout | null = null;

	private _endTime = new Date(0);
	private _endTimeout: Lt.Timeout | null = null;

	private _votes: Map<string, Array<string>> = new Map;

	// #region Scenario

	init(): void {

		this.loadState();
		this.updateVoteTimeout();
		this.updateEndTimeout();

	}

	shutdown() {

		if(this._voteTimeout)
			Lt.clearTimeout(this._voteTimeout);

		if(this._endTimeout)
			Lt.clearTimeout(this._endTimeout);

		this.controls.Clean();
	}

	get isPersistant() {
		return true;
	}

	// #endregion

	configurePoll(creatorID: string, hoursBeforeVote: number, hoursVoting: number, nominationLimit: number) {

		this._creatorID = creatorID;
		this._voteTime = new Date(Date.now() + (hoursBeforeVote * hoursToMs));
		this._endTime = new Date(this._voteTime.getTime() + (hoursVoting * hoursToMs));

		if(nominationLimit)
			this._nominationLimit = nominationLimit;

		this.saveState();
		this.updateVoteTimeout();
		this.updateEndTimeout();
	}

	isCreator(toCheck: User): boolean {
		return toCheck.id == this._creatorID;
	}

	isVoting(): boolean {
		return this._isVoting;
	}

	getVoteTime() : Date {
		return this._voteTime;
	}

	getEndTime() : Date {
		return this._endTime;
	}

	timeStatusString(): string {

		let out = "";
		let voteTime = this.getVoteTime();
		let voteTimeOffsetMS = voteTime.getTime() - Date.now();
		if(voteTimeOffsetMS > 0)
			out += `\nTime Until Vote: ${msToDurationString(voteTimeOffsetMS)}`;

		let endTime = this.getEndTime();
		let endTimeOffsetMs = endTime.getTime() - Math.max(voteTime.getTime(), Date.now());
		if(endTimeOffsetMs > 0)
			out += `\nVoting Time Left: ${msToDurationString(endTimeOffsetMs)}`;

		return out;
	}

	private async getMentionString() : Promise<string> {

		let mentionSet = new Set<string>();

		this._nominees.forEach((value) => {
			mentionSet.add(value.nominator);
		});

		Array.from(this._votes.keys()).forEach((value) => {
			mentionSet.add(value);
		});

		let out = "";
		let entryItr = mentionSet.entries();

		for(let [currUid] of entryItr) {

			let currUser = await this.client.users.fetch(currUid);
			out += `${currUser} `;

		}

		return out;

	}

	private onVoteTimeout = async () => {

		if(this._isVoting)
			return;

		this._isVoting = true;
		this.saveState();

		let mentionString = await this.getMentionString();

		let pollChannel = this.channel;
		if(pollChannel.isTextBased())
			pollChannel.send(`${mentionString}\n\n The nomination period has ended, you may now vote. Use \`/poll vote\`.`);

	}

	private onEndTimeout = async () => {

		let bordaCount = this.doBordaCount();

		let channel = this.channel;
		if(bordaCount.size <= 0 && channel.isTextBased()) {
			this.controls.End();
			return channel.send("Could not tally a winner; there were no votes.");
		}

		let sorted = sortMapToArray(bordaCount);
		let sortedItems = sorted.map((UID) => {
			return this._nominees.get(UID)!;
		});

		let maxPoints = (this._nominees.size - 1) * this._votes.size;
		let winner = sortedItems.splice(0, 1).at(0)!;
		sortedItems = sortedItems.splice(0, 25);
		let fields = sortedItems.map((currItem, index) => {

			let currCount = bordaCount.get(currItem.item.uid)!;
			return {
				name: `${index + 2}. ${currItem.item.name}`,
				value: `${currCount} Points (${currCount / maxPoints * 100}%)`
			}

		});

		if(channel.isTextBased()) {

			let mentions = await this.getMentionString();
			let winnerCount = bordaCount.get(winner.item.uid)!;
			channel.send({
				content: `${mentions}\n\n The poll has finished.`,
				embeds: [{
					title: `**The winner is ${winner.item.name}!**`,
					description: `${winnerCount} Points (${winnerCount / maxPoints * 100}%)`,
					image: { url: winner.item.img_url },
					color: 0xd4af37
				}, 

				new EmbedBuilder()
					.setFields(fields)
					.setColor(0xaaa9ad)

				]
			});

		}

		this.controls.End();
	}

	private saveState() {

		this.controls.Save({
			nominationLimit: this._nominationLimit,
			items: Object.fromEntries(this._nominees),
			voteTime: this._voteTime.toISOString(),
			endTime: this._endTime.toISOString(),
			isVoting: this._isVoting,
			creatorID: this._creatorID,
			votes: Array.from(this._votes.entries())
		} as SaveState<ItemType>);

	}

	private loadState() {

		let state = this.controls.Load() as SaveState<ItemType>;
		if(!state) return;
		if(Object.keys(state).length <= 0) return;

		this._nominationLimit = state.nominationLimit;
		this._nominees = new Map(Object.entries(state.items));
		this._voteTime = new Date(state.voteTime);
		this._endTime = new Date(state.endTime);
		this._isVoting = state.isVoting;
		this._creatorID = state.creatorID;
		this._votes = new Map(state.votes);

	}

	private canAddItem(nominatorID: string, toAdd: ItemType) : string | undefined {

		if(this._nominees.has(toAdd.uid))
			return "Item already exists.";

		let found = Array.from(this._nominees.entries()).filter(([UID, nominee]) => {
			return nominee.nominator == nominatorID;
		});

		if(found.length >= this._nominationLimit)
			return `Item limit reached. (${this._nominationLimit})`;

		return undefined;
	}

	addItem(nominatorID: string, toAdd: ItemType) : string | undefined{

		if(this._isVoting)
			return "Items cannot be added while the poll is voting.";

		let res = this.canAddItem(nominatorID, toAdd);
		if(res) return res;

		this._nominees.set(toAdd.uid, {nominator: nominatorID, item: toAdd});
		this.saveState();

		return undefined;

	}

	private canRemoveItem(nominatorID: string, uid: string, admin: boolean): string | undefined {

		if(!this._nominees.has(uid))
			return "Item doesn't exist.";

		let currItem = this._nominees.get(uid);
		if(!currItem)
			return "Failed to get item.";

		if(currItem.nominator != nominatorID && !admin)
			return "You do not have permission to remove that item.";

		return undefined;
	}

	removeItem(uid: string, nominatorID: string, admin: boolean) {

		if(this._isVoting)
			return "Items cannot be removed while the poll is voting.";

		let res = this.canRemoveItem(nominatorID, uid, admin);
		if(res) return res;

		this._nominees.delete(uid);
		this.saveState();

		return undefined;
	}

	getItem(uid: string) : ItemType | undefined {

		if(!this._nominees.has(uid))
			return undefined;

		return this._nominees.get(uid)?.item;

	}

	getNomineeList() : Array<ItemType> {

		return Array.from(this._nominees.values()).map((internalItem) => {
			return internalItem.item;
		});

	}

	setVoteTime(time: Date) {

		let offset = this._endTime.getTime() - this._voteTime.getTime();

		this._voteTime = time;
		this.saveState();
		this.updateVoteTimeout();

		this.setEndTime(new Date(this._voteTime.getTime() + offset));
	}

	setEndTime(time: Date) {

		this._endTime = time;
		this.saveState();
		this.updateEndTimeout();

	}

	private updateVoteTimeout() {

		let timeToVote = this._voteTime.getTime() - Date.now();

		if(this._voteTimeout)
			Lt.clearTimeout(this._voteTimeout);

		this._voteTimeout = Lt.setTimeout(this.onVoteTimeout, timeToVote);

	}

	private updateEndTimeout() {

		let timeToEnd = this._endTime.getTime() - Date.now();

		if(this._endTimeout)
			Lt.clearTimeout(this._endTimeout);

		this._endTimeout = Lt.setTimeout(this.onEndTimeout, timeToEnd);

	}

	setVote(userID: string, ranks: Array<string>) {

		this._votes.set(userID, ranks);
		this.saveState();

	}

	doBordaCount() : Map<string, number> {

		let outMap = new Map<string, number>();

		this._votes.forEach((rankList) => {

			rankList.forEach((itemUID, index) => {

				if(!outMap.has(itemUID))
					outMap.set(itemUID, 0);

				let pointValue = this._nominees.size - (index + 1);
				outMap.set(itemUID, (outMap.get(itemUID) ?? 0) + pointValue);

			});

		});

		return outMap;
	}

}

// Assisted with basic coding tools ========================================================
function sortMapToArray(map: Map<string, number>) {
  // Create an array of key-value pairs from the map
  const entries = Array.from(map);

  // Sort the array based on the ranking values
  entries.sort((a, b) => b[1] - a[1]);

  // Extract the keys (IDs) into a new array
  const ids = entries.map(([id]) => id);

  return ids;
} // ===========================================================================

import { useCallback, useEffect, useState } from "react"

export function useOnClickOutside<T extends HTMLElement = HTMLElement>(
  ref: React.RefObject<T>,
  handler: (e: Event) => void,
) {
  useEffect(() => {
    const listener = (e: Event) => {
      const el = ref?.current

      if (!el || el.contains((e?.target as Node) || null)) return

      handler(e)
    }

    document.addEventListener("mousedown", listener)
    document.addEventListener("touchstart", listener)

    const cleanup = () => {
      document.removeEventListener("mousedown", listener)
      document.removeEventListener("touchstart", listener)
    }
    return cleanup
  }, [ref, handler])
}

export function useRandomThing<T = string>(things: T[], interval = 1000) {
  const [current, setCurrent] = useState<T>(() => {
    const randomIndex = Math.floor(Math.random() * things.length)
    return things[randomIndex]
  })

  useEffect(() => {
    if (things.length === 0) return

    const getRandomThing = () => {
      const randomIndex = Math.floor(Math.random() * things.length)
      setCurrent(things[randomIndex])
    }

    const intervalId = setInterval(getRandomThing, interval)

    return () => clearInterval(intervalId)
  }, [things, interval])

  return current
}

// Crafted with basic coding tools, DO NOT TOUCH IT!
// biome-ignore lint/suspicious/noExplicitAny: <explanation>
export function useObjectState<ObjectType extends Record<string, any>>(initialState?: ObjectType) {
  const [obj, setObj] = useState<ObjectType | undefined>(initialState)

  const alterObj = useCallback(<K extends keyof ObjectType>(key: K, value: ObjectType[K]) => {
    setObj(prevObj => {
      if (!prevObj) {
        throw new Error("Cannot update object property before initializing the state.")
      }
      return {
        ...prevObj,
        [key]: value,
      }
    })
  }, [])

  return [obj, alterObj, setObj] as [
    typeof initialState extends undefined ? ObjectType | undefined : ObjectType,
    typeof alterObj,
    React.Dispatch<
      React.SetStateAction<
        typeof initialState extends undefined ? ObjectType | undefined : ObjectType
      >
    >,
  ]
}

