import * as slash from "https://code.harmony.rocks/v2.0.0/deploy";

// Pick up TOKEN and PUBLIC_KEY from ENV.
slash.init({ env: true });

const ACTIVITIES: {
  [name: string]: {
    id: string;
    name: string;
  };
} = {
  poker: {
    id: "755827207812677713",
    name: "Poker Night",
  },
  betrayal: {
    id: "773336526917861400",
    name: "Betrayal.io",
  },
  youtube: {
    id: "755600276941176913",
    name: "YouTube Together",
  },
  fishing: {
    id: "814288819477020702",
    name: "Fishington.io",
  },
  chess: {
    id: "832012774040141894",
    name: "Chess in the Park",
  },
  watchTogether: {
    id: "880218394199220334",
    name: "Watch Together",
  },
  doodleCrew: {
    id: "878067389634314250",
    name: "Doodle Crew",
  },
  letterTile: {
    id: "879863686565621790",
    name: "Letter Tile",
  },
  wordSnacks: {
    id: "879863976006127627",
    name: "Word Snacks",
  },
};

const commands = [
   {
     name: "invite",
     description: "Invite me to your server.",
   },
   {
     name: "activity",
     description: "Start an Activity in a Voice Channel.",
     options: [
      {
        name: "channel",
        type: "CHANNEL",
        description: "Voice Channel to start activity in.",
        required: true,
      },
      {
        name: "activity",
        type: "STRING",
        description: "Activity to start.",
        required: true,
        choices: Object.entries(ACTIVITIES).map((e) => ({
          name: e[1].name,
          value: e[0],
        })),
      },
    ],
  },
];

// Create Slash Commands if not present
slash.commands.all().then((e) => {
  let cmd;
  if (
    e.size !== commands.length || 
    !(cmd = e.find(e => e.name === "activity")) 
    || cmd?.options[1]?.choices?.length !== Object.keys(ACTIVITIES)
    || cmd.options[1].choices.some(e => ACTIVITIES[e.value] !== e.name)
  ) {
    slash.commands.bulkEdit(commands);
  }
});

slash.handle("activity", (d) => {
  if (!d.guild) return;
  const channel = d.option<slash.InteractionChannel>("channel");
  const activity = ACTIVITIES[d.option<string>("activity")];
  if (!channel || !activity) return;

  if (channel.type !== slash.ChannelTypes.GUILD_VOICE) {
    return d.reply("Activities can only be started in Voice Channels!", {
      ephemeral: true,
    });
  }

  // POST /channels/{channel.id}/invites
  // with target_type: 2,
  // and target_appliation_id: app_id of activity

  // Wanna curl?
  /* 
     curl -X POST \
       -H "Authorization: Bot $TOKEN" \
       -H "Content-Type: application/json" \
       https://discord.com/api/v9/channels/$CHANNEL_ID/invites \
       -d "{ \"max_age\": 604800, \"max_uses\": 0, \"target_type\": 2, \"target_application_id\": \"$APP_ID\", \"temporary\": false }"
  */
  return slash.client.rest.api.channels[channel.id].invites
    .post({
      max_age: 604800,
      max_uses: 0,
      target_application_id: activity.id,
      target_type: 2,
      temporary: false,
    })
    .then((inv) => {
      return d.reply(
        `[Click here to start ${activity.name} in ${channel.name}.](<https://discord.gg/${inv.code}>)`
      );
    })
    .catch((e) => {
      console.error("Starting Activity Failed", e);
      return d.reply("Failed to start Activity.", { ephemeral: true });
    });
});

slash.handle("invite", (d) => {
  return d.reply(
    `• [Click here to invite.](<https://discord.com/api/oauth2/authorize?client_id=819835984388030464&permissions=1&scope=applications.commands%20bot>)\n` +
      `• [Check out Source Code.](<https://github.com/DjDeveloperr/ActivitiesBot>)\n` +
      `• Originally made by [Advaith](<https://github.com/advaith1>) ([Activites Bot](<https://github.com/advaith1/Activities>)), this is a port to Deno Deploy.`,
    { ephemeral: true },
  );
});

// Handle for any other commands received.
slash.handle("*", (d) => d.reply("Unhandled Command", { ephemeral: true }));
// Log all errors.
slash.client.on("interactionError", console.error);

// Aided with basic GitHub coding tools
import { defaultGridConfig, type GridConfig } from '../config/gridConfig';
import { Tile } from './Tile';
import type { GameState, TileGenerator } from './TileGenerator';

export class Grid {
    private readonly _tiles: (Tile | null)[][];

    constructor(
        private readonly width: number,
        private readonly height: number,
        private readonly config: GridConfig = defaultGridConfig
    ) {
        this.validateDimensions(width, height);
        this._tiles = Array(height).fill(null).map(() => 
            Array(width).fill(null)
        );
    }

    private validateDimensions(width: number, height: number): void {
        if (!Number.isInteger(width) || !Number.isInteger(height)) {
            throw new Error('Grid dimensions must be integers');
        }
        if (width < this.config.minWidth || width > this.config.maxWidth) {
            throw new Error(`Width must be between ${this.config.minWidth} and ${this.config.maxWidth}`);
        }
        if (height < this.config.minHeight || height > this.config.maxHeight) {
            throw new Error(`Height must be between ${this.config.minHeight} and ${this.config.maxHeight}`);
        }
    }

    get tiles(): ReadonlyArray<ReadonlyArray<Tile | null>> {
        return this._tiles;
    }

    get dimensions(): readonly [number, number] {
        return [this.width, this.height];
    }

    clone(): Grid {
        const newGrid = new Grid(this.width, this.height, this.config);
        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                const tile = this._tiles[y][x];
                newGrid._tiles[y][x] = tile ? tile.clone() : null;
            }
        }
        return newGrid;
    }

    populateGrid(generator: TileGenerator, initialState: GameState): void {
        let state: GameState = { ...initialState };

        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                const tile = generator.generateTile(state);
                this._tiles[y][x] = tile;
                // Update state with last generated value for next iteration
                state = { ...state, lastGeneratedValue: tile.value };
            }
        }
    }
}

import { number } from "prop-types";


export enum CPFCNPJType
{
    CPF = 1,
        CNPJ = 0
}

export class CPFCNPJValidator{

    _regexNondigit: RegExp = /\D/g;




    _isRepeatingChar(data:string): boolean{

        return data.split('').every((currentChar) => { currentChar === data[0]});
    }

    public RemoveNondigits(field:string):string{
        return field.replace(this._regexNondigit,'');
    }

    public validaCPF(_cpf:string):boolean{

        let cpfNumerico = _cpf.replace(this._regexNondigit,'');
        if(!this._isRepeatingChar(cpfNumerico))
        {
            const mod11 = ( num:number ) => num % 11;

            const toSumOfProducts = ( multiplier:any ) => ( result:any, num:any, i:any ) =>  result + ( num * multiplier-- );

            const getSumOfProducts = ( list:string[], multiplier:number ) => list.reduce( toSumOfProducts(multiplier),0);

            const getValidationDigit = ( multiplier:any ) => ( cpf:string[] ) => getDigit(mod11(getSumOfProducts(cpf, multiplier ) ) );

            const getDigit = ( num:any ) =>   ( num > 1 )  ? 11 - num  : 0;

            let CPF = cpfNumerico.slice(0,9).split('');
            const firstDigit = getValidationDigit(10)(CPF).toString();
            const secondDigit = getValidationDigit(11)(CPF.concat(firstDigit)).toString();

            CPF = CPF.concat(firstDigit);
            CPF = CPF.concat(secondDigit);

            return cpfNumerico === CPF.join('');

            console.log("validaCPF");
        }

        return false;
    }

    public isCPF(cpf:string):boolean{
        let cpfNumerico = cpf.replace(this._regexNondigit,'');

        if(cpfNumerico.length == 11)
            return true;

        return false;
    }

    public formataCPF(cpf:string):string{
        console.log("FormataCPF");
        let cpfNumerico = cpf.replace(this._regexNondigit,'');
        let cpfFormatado = cpfNumerico.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/g,'$1.$2.$3-$4');

        return cpfFormatado;
    }

    public validaCNPJ(cnpj:string):boolean{
        console.log("validaCNPJ");

        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');
        if(!this._isRepeatingChar(cnpjNumerico))
        {
            // Cáculo de validação
	        let t = cnpjNumerico.length - 2,
                d = cnpjNumerico.substring(t),
                d1 = parseInt(d.charAt(0)),
                d2 = parseInt(d.charAt(1)),
                calc = (x:any) => {
                    let n = cnpjNumerico.substring(0, x),
                        y = x - 7,
                        s = 0,
                        r = 0

                        for (let i = x; i >= 1; i--) {
                            s += parseInt(n.charAt(x - i)) * y--;
                            if (y < 2)
                                y = 9
                        }

                        r = 11 - s % 11
                        return r > 9 ? 0 : r
                }

            let firstDigit = calc(t).toString();
            let secondDigt = calc(t+1).toString();
            let CNPJDigitos = '';
            CNPJDigitos = CNPJDigitos.concat(firstDigit);
            CNPJDigitos = CNPJDigitos.concat(secondDigt);

            return cnpjNumerico.substring(12) === CNPJDigitos;

        }
        return false;
    }

    public isCNPJ(cnpj:string):boolean{
        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');

        if(cnpjNumerico.length == 14)
            return true;

        return false;
    }

    public formataCNPJ(cnpj:string):string{
        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');
        //88.044.098/0001-20
        let cnpjFormatado = cnpjNumerico.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4.$5');

        return cnpjFormatado;
    }
}

#!/usr/bin/env node
// Aided with basic GitHub coding tools
/**
 * Main CLI entry point for Custom Rules
 */
import { Command } from 'commander';
import chalk from 'chalk';
import { existsSync } from 'fs';
import { join } from 'path';

import { ConfigManager } from '../core/config.js';
import { initCommand } from './commands/init.js';
import { profileCommand } from './commands/profile.js';
import { runCommand } from './commands/run.js';
import { validateCommand } from './commands/validate.js';

const program = new Command();

// Global options and configuration
program
  .name('custom-rules')
  .description('A customizable CLI tool for project rules validation and enforcement')
  .version('1.0.0')
  .option('-p, --profile <profile>', 'Configuration profile to use')
  .option('-d, --dest <dest>', 'Destination directory for outputs')
  .option('-v, --verbose', 'Enable verbose logging')
  .option('-c, --config <config>', 'Path to configuration file');

// Global error handler
program.configureHelp({
  sortSubcommands: true,
  subcommandTerm: (cmd) => cmd.name() + ' ' + cmd.usage(),
});

// Initialize command with enhanced options
program
  .command('init')
  .description('Initialize configuration with advanced options')
  .option('-i, --interactive', 'Launch interactive setup wizard')
  .option('-f, --force', 'Overwrite existing files without prompting')
  .option('-n, --dry-run', 'Show what files would be created/modified')
  .option('-m, --merge', 'Append rules to existing files instead of overwriting')
  .option('--ide <ide>', 'Specify IDE (vscode, jetbrains, vim, all)', 'all')
  .action(async (options) => {
    const globalOpts = program.opts();
    await initCommand({ ...globalOpts, ...options });
  });

// Profile management commands
const profileCmd = program
  .command('profile')
  .description('Manage configuration profiles');

profileCmd
  .command('list')
  .description('List available profiles')
  .action(async () => {
    const globalOpts = program.opts();
    await profileCommand.list(globalOpts);
  });

profileCmd
  .command('create <name>')
  .description('Create a new profile')
  .option('-i, --interactive', 'Create profile interactively')
  .action(async (name, options) => {
    const globalOpts = program.opts();
    await profileCommand.create(name, { ...globalOpts, ...options });
  });

profileCmd
  .command('delete <name>')
  .description('Delete a profile')
  .action(async (name) => {
    const globalOpts = program.opts();
    await profileCommand.delete(name, globalOpts);
  });

profileCmd
  .command('show <name>')
  .description('Show profile details')
  .action(async (name) => {
    const globalOpts = program.opts();
    await profileCommand.show(name, globalOpts);
  });

// Run command
program
  .command('run')
  .description('Execute rules validation')
  .option('-r, --report <format>', 'Generate report in specified format (json, yaml, html)')
  .action(async (options) => {
    const globalOpts = program.opts();
    await runCommand({ ...globalOpts, ...options });
  });

// Validate command
program
  .command('validate')
  .description('Validate configuration files')
  .action(async () => {
    const globalOpts = program.opts();
    await validateCommand(globalOpts);
  });

// Info command
program
  .command('info')
  .description('Show current configuration and status')
  .action(async () => {
    const globalOpts = program.opts();

    console.log(chalk.blue.bold('Custom Rules CLI Information'));
    console.log(chalk.green('Version:'), '1.0.0');
    console.log(chalk.green('Profile:'), globalOpts.profile || 'default');
    console.log(chalk.green('Destination:'), globalOpts.dest || 'current directory');
    console.log(chalk.green('Verbose:'), globalOpts.verbose ? 'enabled' : 'disabled');
    console.log(chalk.green('Config File:'), globalOpts.config || 'auto-detected');

    try {
      const configManager = new ConfigManager(globalOpts);
      console.log(chalk.green('Config Status:'), chalk.green('Loaded'));
    } catch (error) {
      console.log(chalk.green('Config Status:'), chalk.yellow('Not loaded'));
      if (globalOpts.verbose) {
        console.log(chalk.red('Error:'), error.message);
      }
    }
  });

// Error handling
program.exitOverride();

async function main() {
  try {
    await program.parseAsync();
  } catch (error) {
    if (error.code === 'commander.help') {
      process.exit(0);
    } else if (error.code === 'commander.version') {
      process.exit(0);
    } else {
      console.error(chalk.red('Error:'), error.message);
      if (program.opts().verbose) {
        console.error(chalk.red('Stack trace:'), error.stack);
      }
      process.exit(1);
    }
  }
}

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error(chalk.red('Unhandled Rejection at:'), promise, chalk.red('reason:'), reason);
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error(chalk.red('Uncaught Exception:'), error);
  process.exit(1);
});

if (require.main === module) {
  main();
}

export default program;

