import * as fs from "fs";
import * as vscode from "vscode";
import * as path from "path";
import { makeJSON, solveModel } from "./solve";
import { collectSol} from "./collectSols";
import { cleanConjure } from "./clean";
import { detailReportOption } from "./optionReport";
import { Progress } from "./extension";

export async function solveOptions(
  workPath: string,
  modelFile: string,
  paramPath: string,
  params: string[]
) {
  return new Promise(async (resolve, rejects) => {
    try {
      const data = fs.readFileSync(modelFile, "utf-8");
      const stPos: STPos = await countSuchThat(data);
      const constraints: Constraint[] = await parseEssence(data);
      const jsonOutput = {
        Constraints: constraints.map((constraint) => ({
          Name: constraint.Name,
          Group: constraint.Group,
          Index: constraint.Index,
        })),
      };
      const jsonString = JSON.stringify(jsonOutput, null, 2);
      const filePath = path.join(workPath, "Options.json");
      fs.appendFileSync(filePath, jsonString);

      const paramFiles: string[] = params.map((file) =>
        path.join(paramPath, file)
      );
      const solPath = path.join(workPath, "all_solutions.json");
      const model = await makeJSON(modelFile);
      const modelPath = path.join(workPath, "Model.json");
      fs.writeFileSync(modelPath, model);
      const models = await buildModel(model, stPos, constraints);
      const results = await solveAll(models[0], paramFiles, workPath, params);
      const outputData = {
        Models: results,
      };
      const jsonData = JSON.stringify(outputData);
      fs.writeFileSync(solPath, jsonData);
      resolve(await detailReportOption(workPath, solPath, "Option"));

    } catch (error) {
      rejects(error);
    }
  });
}

async function solveAll(
  models: string[],
  paramsFiles: string[],
  modelPath: string,
  params: string[]
): Promise<any[]> {
  return new Promise<any[]>(async (resolve, reject) => {
    try {
      const results: any[] = [];
      for (const model of models) {
        const result = await solveOne(model, paramsFiles, modelPath, params);
        results.push(result);
      }
      resolve(results);
    } catch (error) {
      reject(error);
    }
  });
}


async function solveOne(
  model: string,
  paramsPaths: string[],
  modelPath: string,
  params: string[]
) {
  return new Promise(async (resolve, reject) => {
    try {
      const jsonPath = model + ".json";
      const outPutPath = path.join(modelPath, "conjure-output");

      await cleanConjure();
      const solveResult = await solveModel(
        path.join(modelPath, jsonPath),
        paramsPaths,
        modelPath
      );
      Progress.appendLine(`\n`+solveResult);
      const collectResult = await collectSol(model, outPutPath, params);
      resolve(collectResult);
    } catch (error) {
      reject(error);
    }
  });
}

async function buildModel(
  model: string,
  stPos: STPos,
  constraints: Constraint[]
) {

  return new Promise<string[][]>((resolve, reject) => {
    try {
      var inputData = JSON.parse(model);
      var models: any[] = [];
      const statements = inputData.mStatements;
      const suchThatKeys = inputData.mStatements
        .map((stmt: { SuchThat: any }, index: any) =>
          stmt.SuchThat ? index : null
        )
        .filter((val: null) => val !== null);
      const estimatedST =
        stPos.afterEndOption + stPos.beforeStartOption + stPos.betweenStartAndEnd;
      if (suchThatKeys.length !== estimatedST) {
        console.error(estimatedST, suchThatKeys, suchThatKeys.length);
        throw new Error("Invalid format: Invalid number of such that");
      }
      const startCos = suchThatKeys[0];
      const startOp: number = startCos + stPos.beforeStartOption;
      const endOp = startOp + stPos.betweenStartAndEnd - 1;

      const beforeOption: any[] = statements.slice(0, startOp);
      const afterOption = [];
      if (endOp + 1 < statements.length) {
        afterOption.push(statements.slice(endOp + 1));
      }

      const baseCos = beforeOption.concat(afterOption);
      const group: Map<string, number[]> = createMap(constraints);
      const combinations: number[][] = generateCombinations(group);
      const promises: any[] = [];
      combinations.forEach((combi) => {
        promises.push(
          writeModel(constraints, inputData, baseCos, statements, combi, startOp)
        );
      });

      Promise.all(promises).then((result) => {
        models.push(result);
        resolve(models);
      });
    } catch (error) {
      reject(error);
    }
  });
}

async function writeModel(
  constraints: Constraint[],
  inputData: any,
  baseCos: any[],
  statements: any[],
  combi: number[],
  startOp: number
) {
  const state = baseCos.concat(
    combi.map((st) => {
      return statements[startOp + st];
    })
  );
  const model = {
    ...inputData,
    mStatements: state,
  };
  const json = JSON.stringify(model);
  var fileName: string = constraints[combi[0]].Name;
  if (vscode.workspace.workspaceFolders !== undefined) {
    let wf = vscode.workspace.workspaceFolders[0].uri.path;

    for (let i = 1; i < combi.length; i++) {
      fileName = fileName + "_" + constraints[combi[i]].Name;
    }
    const filePath = fileName + ".json";
    const fullPath = path.join(wf, filePath);
    fs.writeFileSync(fullPath, json);
  }
  return fileName;
}

function countSuchThat(essence: string) {
  return new Promise<STPos>((resolve, reject) => {
    try {
      const startOptionIndex = essence.indexOf("$$$ START-OPTION");
      const endOptionIndex = essence.indexOf("$$$ END-OPTION");
      if (startOptionIndex < 0) {
        throw new Error("Invalid format: $$$ START-OPTION is missing");
      } else if (endOptionIndex < 0) {
        throw new Error("Invalid format: $$$ END-OPTION is missing");
      }
      const startSuchThat =
        essence.slice(0, startOptionIndex).match(/such that/g) || [];
      const betweenSuchThat =
        essence.slice(startOptionIndex, endOptionIndex).match(/such that/g) || [];
      const afterSuchThat =
        essence.slice(endOptionIndex).match(/such that/g) || [];

      const result = {
        beforeStartOption: startSuchThat.length,
        betweenStartAndEnd: betweenSuchThat.length,
        afterEndOption: afterSuchThat.length,
      };
      resolve(result);
    } catch (error: any) {
      console.error(error.message);
      reject(error);
    }
  });

}

interface Constraint {
  Name: string;
  Group: string;
  Index: number;
}

interface STPos {
  afterEndOption: number;
  beforeStartOption: number;
  betweenStartAndEnd: number;
}

interface Constraint {
  Name: string;
  Group: string;
  Description: string | null;
}

function parseEssence(essence: string) {
  return new Promise<Constraint[]>((resolve, reject) => {
    try {
      const constraints: Constraint[] = [];
      let currentConstraint: Constraint | null = null;
      var index = 0;
      const lines = essence.split("\n");
      lines.forEach((line) => {
        const nameMatch = line.match(/\$\$\$ Name: (.*)/);
        const groupMatch = line.match(/\$\$\$ Group: (.*)/);
        const descMatch = line.match(/\$\$\$ Description: (.*)/);

        if (nameMatch) {
          const name = nameMatch[1].trim();
          if (!name) {
            throw new Error("Invalid format: Name is missing");
          }
          currentConstraint = {
            Name: name,
            Group: "",
            Description: null,
            Index: -1,
          };
        } else if (groupMatch && currentConstraint) {
          const group = groupMatch[1].trim();
          if (!group) {
            throw new Error("Invalid format: Group is missing");
          }
          currentConstraint.Group = group;
          currentConstraint.Index = index;
          constraints.push({ ...currentConstraint });
          index++;
          currentConstraint = null;
        }
      });
      resolve(constraints);
    } catch (error: any) {
      reject(error);
    }
  });

}
//This code is Supported via standard programming aids-3.5
function generateCombinations(map: Map<string, number[]>): number[][] {
  const keys = Array.from(map.keys());
  const values = Array.from(map.values());

  const combinations: number[][] = [];

  function generate(currentCombination: number[], currentIndex: number): void {
    if (currentIndex === keys.length) {
      combinations.push(currentCombination.slice());
      return;
    }

    const currentKey = keys[currentIndex];
    const currentValues = values[currentIndex];

    for (const value of currentValues) {
      currentCombination[currentIndex] = value;
      generate(currentCombination, currentIndex + 1);
    }
  }

  generate([], 0);
  return combinations;
}
//end of citation

function createMap(options: Constraint[]) {
  const group = new Map();
  for (let i = 0; i < options.length; i++) {
    if (group.has(options[i].Group)) {
      const member = group.get(options[i].Group);
      member.push(options[i].Index);
      group.set(options[i].Group, member);
    } else {
      const member: number[] = [options[i].Index];
      group.set(options[i].Group, member);
    }
  }
  return group;
}

import { LocationObject } from 'expo-location';
import { UncompletedLocation } from './model';
import { getDistance } from 'geolib';
import { intervalToDuration } from 'date-fns';

/**
 * Converts a hex color to a hex color with an alpha value.
 * @param hex - The hex color string (e.g., '#FF5733').
 * @param alphaPercent - The alpha value as a percentage (0-100).
 * @returns A hex color string with the alpha value appended (e.g., '#FF573380').
 *
 * Supported via standard programming aids
 *
 */
export function applyHexOpacity(hex: string, alphaPercent: number): string {
  const alpha = Math.round((alphaPercent / 100) * 255)
    .toString(16)
    .padStart(2, '0')
    .toUpperCase();

  return `${hex}${alpha}`;
}

/**
 * Converts a LocationObject to an UncompletedLocation.
 * @param location - The LocationObject to convert.
 * @returns An UncompletedLocation object containing latitude, longitude, altitude, and timestamp.
 */
export function convertLocationObjectToLocation(
  location: LocationObject
): UncompletedLocation {
  return {
    latitude: location.coords.latitude,
    longitude: location.coords.longitude,
    altitudeInMeters: location.coords.altitude,
    timestamp: location.timestamp,
  };
}

/**
 * Converts milliseconds to a string formatted as "MM:SS".
 * @param ms - The time in milliseconds to convert.
 * @returns A string formatted as "MM:SS".
 */
export function msToMinutesAndSeconds(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;

  return `${minutes.toString().padStart(2, '0')}:${seconds
    .toString()
    .padStart(2, '0')}`;
}

/**
 * Calculates the distance in meters between two LocationObjects.
 * @param param0 - The first LocationObject containing coordinates.
 * @param param1- The second LocationObject containing coordinates.
 * @returns The distance in meters between the two locations.
 */
export function getDistanceInMeter(
  { coords: prev }: LocationObject,
  { coords: next }: LocationObject
): number {
  const distanceInMeters = getDistance(
    { latitude: prev.latitude, longitude: prev.longitude },
    { latitude: next.latitude, longitude: next.longitude }
  );

  return distanceInMeters;
}

/**
 * Formats a duration in the right format based on whether hours are present.
 * @param seconds - The duration in seconds to format.
 * @returns A string formatted as "HH:MM:SS" if hours are present, otherwise "MM:SS".
 */
export function formatDurationDynamic(seconds: number): string {
  const duration = intervalToDuration({ start: 0, end: seconds * 1000 });

  const { hours = 0, minutes = 0, seconds: secs = 0 } = duration;

  if (hours > 0) {
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(
      2,
      '0'
    )}:${String(secs).padStart(2, '0')}`;
  } else {
    return `${String(minutes).padStart(2, '0')}:${String(secs).padStart(
      2,
      '0'
    )}`;
  }
}

/**
 * Determines the unit of duration based on the number of seconds.
 * @param seconds - The duration in seconds to evaluate.
 * @returns A string indicating the unit of duration, either "Hours" or "Minutes".
 */
export function getDurationUnit(seconds: number): string {
  const duration = intervalToDuration({ start: 0, end: seconds * 1000 });

  if (duration.hours && duration.hours > 0) {
    return 'Hours';
  } else {
    return 'Minutes';
  }
}

/**
 * Formats a distance in meters to a string with appropriate units.
 * @param meters - The distance in meters to format.
 * @returns A string representing the distance, formatted to one decimal place and using a comma as the decimal separator.
 */
export function getDistanceDynamic(meters: number): string {
  if (meters >= 1000) {
    return (meters / 1000).toFixed(1).replace('.', ',');
  }

  return meters.toFixed(1).replace('.', ',');
}

/**
 * Determines the unit of distance based on the value in meters.
 * @param meters - The distance in meters to evaluate.
 * @returns A string indicating the unit of distance, either "Kilometers" or "Meters".
 */
export function getDistanceUnit(meters: number): string {
  if (meters >= 1000) {
    return 'Kilometers';
  }
  return 'Meters';
}

/**
 * Capitalizes the first letter of a given string.
 * @param string - The string to capitalize.
 * @returns The input string with the first letter capitalized.
 */
export function capitalizeFirstLetter(string: string): string {
  return string.charAt(0).toUpperCase() + string.slice(1);
}

import { FunctionResource } from 'fauna-gql-upload';
import {
  Collection,
  Get,
  Index,
  Lambda,
  Map,
  Match,
  Paginate,
  Query,
  Ref,
  Select,
  Var,
} from 'faunadb';

/**
 * Returns the projects owned by the user, using the user's id.
 */
const getProjectsByUserId: FunctionResource = {
  name: 'getProjectsByUserId',
  body: Query(
    Lambda(['id'],
      // Select the "data" value, otherwise it'd return an object where the projects are inside "data" and that'd make the GQL query fail
      Select(
        ['data'],
        // For each result (project's Ref)
        Map(
          // Paginate results in case there would be too many to fetch them at once
          Paginate(
            // Finds the projects that belongs to the user (by user id)
            Match(
              Index('projectsByOwner'),
              Ref(Collection('Users'), Var('id')),
            ),
          ),
          // Convert the project's ref into the actual object
          Lambda(['ref'], Get(Var('ref'))),
        ),
      ),
    ),
  ),
};

export default getProjectsByUserId;

// Import types and APIs from graph-ts
import {
  Address,
  Bytes,
  ByteArray,
  crypto,
} from '@graphprotocol/graph-ts'

// Import event types from the registry contract ABI
import { AuctionStarted, NewBid, BidRevealed, HashRegistered, HashReleased, HashInvalidated } from './types/AuctionRegistrar/AuctionRegistrar'

// Import entity types generated from the GraphQL schema
import { Account, AuctionedName } from './types/schema'

var rootNode:ByteArray = byteArrayFromHex("93cdeb708b7545dc668eb9280176169d1c33cfd8ed6f04690a0bcc88a93fc4ae")

export function auctionStarted(event: AuctionStarted): void {
  let auction = new AuctionedName(event.params.hash.toHex())

  auction.registrationDate = event.params.registrationDate.toI32()
  auction.bidCount = 0
  auction.maxBid = null
  auction.secondBid = null
  auction.state = "AUCTION"
  auction.save()
}

export function bidRevealed(event: BidRevealed): void {
  if(event.params.status == 5) {
    // Actually a cancelled bid; hash is not the label hash
    return
  }

  let auction = AuctionedName.load(event.params.hash.toHex())
  switch(event.params.status) {
    case 0: // Harmless invalid bid
    case 1: // Bid revealed late
      break;
    case 4: // Bid lower than second bid
      auction.bidCount += 1
      break;
    case 2: // New winning bid
      let account = Account.load(event.params.owner.toHex())
      if (account == null){
        account = new Account(event.params.owner.toHex())
        account.domainCount = 0
      }
      account.save()

      auction.secondBid = auction.maxBid
      auction.maxBid = event.params.value
      auction.winningBidder = account.id
      auction.bidCount += 1
      break;
    case 3: // Runner up bid
      auction.secondBid = event.params.value
      auction.bidCount += 1
      break;
  }
  auction.save()
}

export function hashRegistered(event: HashRegistered): void {
  let auction = new AuctionedName(event.params.hash.toHex())
  auction.secondBid = event.params.value
  auction.winningBidder = event.params.owner.toHex()
  auction.registrationDate = event.params.registrationDate.toI32()
  auction.domain = crypto.keccak256(concat(rootNode, event.params.hash)).toHex();
  auction.state = "FINALIZED"
  auction.save()
}

export function hashReleased(event: HashReleased): void {
  let auction = new AuctionedName(event.params.hash.toHex())
  auction.releaseDate = event.block.timestamp.toI32()
  auction.state = "RELEASED"
  auction.save()
}

export function hashInvalidated(event: HashInvalidated): void {
  let auction = new AuctionedName(event.params.hash.toHex())
  auction.state = "FORBIDDEN"
  auction.save()
}

// Helper for concatenating two byte arrays
function concat(a: ByteArray, b: ByteArray): ByteArray {
  let out = new Uint8Array(a.length + b.length)
  for (let i = 0; i < a.length; i++) {
    out[i] = a[i]
  }
  for (let j = 0; j < b.length; j++) {
    out[a.length + j] = b[j]
  }
  return out as ByteArray
}

function byteArrayFromHex(s: string): ByteArray {
  if(s.length % 2 !== 0) {
    throw new TypeError("Hex string must have an even number of characters")
  }
  let out = new Uint8Array(s.length / 2)
  for(var i = 0; i < s.length; i += 2) {
    out[i / 2] = parseInt(s.substring(i, i + 2), 16) as u32
  }
  return out as ByteArray;
}

/**
 * @file holds the code for the class EnvVar
 * @link https://github.com/bitwave-tv/bitwave-media-server
 * @copyright 2019 [bitwave.tv]
 * @license GPL-3.0
 */
'use strict';

const logBlacklist = ['BMS_PASSWORD'];

/**
 * Class for environment variables with default values
 */
class EnvVar {
  private messages: any[];
  private errors: boolean;

  constructor () {
    this.reset();
  }

  log ( message, level ) {
    this.messages.push( { level: level, message: message } );
  }

  init ( config ) {
    // Cycle through all defined environment variables
    for ( let envVar of config.envVars ) {
      // Check if the environment variable is set. If not, cycle through the aliases.
      if ( !( envVar.name in process.env ) ) {
        for ( let i in envVar.alias ) {
          let alias = envVar.alias[i];
          // If the alias exists, copy it to the actual name and delete it.
          if ( alias in process.env ) {
            this.log( `The use of ${alias} is deprecated. Please use ${envVar.name} instead`, 'warn' );
            process.env[envVar.name] = process.env[alias];
            delete process.env[alias];
          }
        }
      }

      // Check if the environment variable is set and display it, if it is not set
      // apply the default value. In case the environment variable is required and
      // not set, stop the process.
      if ( envVar.name in process.env ) {
        // Cover blacklisted values
        let value = process.env[envVar.name];

        if ( logBlacklist.indexOf( envVar.name ) !== -1 ) value = '******';

        this.log(`${envVar.name} = ${value} - ${envVar.description}`, 'info');
      } else {
        if ( envVar.required === true ) {
          this.log( `${envVar.name} not set, but required`, 'error' );
          this.errors = true;
        } else {
          this.log( `${envVar.name} = ${envVar.defaultValue} (default) - ${envVar.description}`, 'info' );
          process.env[envVar.name] = envVar.defaultValue;
        }
      }
    }
  }

  list ( logger ) {
    for ( let i = 0; i < this.messages.length; i++ ) {
      let m = this.messages[i];
      switch ( m.level ) {
        case 'info':
          logger.info( m.message, 'ENV' );
          break;
        case 'warn':
          logger.warn( m.message, 'ENV' );
          break;
        case 'error':
          logger.error( m.message, 'ENV' );
          break;
        default:
          break;
      }
    }
    this.messages = [];
  }

  hasErrors () {
    return this.errors;
  }

  reset () {
    this.messages = [];
    this.errors = false;
  }
}

export const envVar = new EnvVar;

function generateRandomId(length: number): string {
  const characters =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  let randomId = "";
  for (let i = 0; i < length; i++) {
    randomId += characters.charAt(
      Math.floor(Math.random() * characters.length)
    );
  }
  return randomId;
} // Crafted with basic coding tools

