		code:
			'function sayHi() {\n  console.log(name);\n  console.log(age);\n  var name = "Lydia";\n  let age = 21;\n}\n\nsayHi();',
		options: [
			{
				correct: false,
				text: "`Lydia` and `undefined`"
			},
			{
				correct: false,
				text: "`Lydia` and `ReferenceError`"
			},
