import { Vector } from '../math/vector';
import { minus } from '../math/minus';

const check = (threshold: number, startI: number, endI: number, paths: number[]) => {
	let max = 0;
	let maxI = 0;
	// 拿到基础向量
	const baseVector = new Vector(minus(paths[endI], paths[startI]), minus(paths[endI + 1], paths[startI + 1]));
	for (let i = startI + 2; i < endI; i += 2) {
		// 获取每个点基于起始和结束位置的向量
		const vectorToStart = new Vector(minus(paths[i], paths[startI]), minus(paths[i + 1], paths[startI + 1]));
		const vectorToEnd = new Vector(minus(paths[i], paths[endI]), minus(paths[i + 1], paths[endI + 1]));
		let distance = 0;
		// 与起始或结束点重合的点直接跳过
		if (!vectorToStart.isZero && !vectorToEnd.isZero) {
			// 边界情况：投影分量的模大于基础向量，说明途径点在起始点或结束点之外，不能单纯靠垂直分量来抽稀
			const prjToStart = Vector.projected(vectorToStart, baseVector);
			const prjToEnd = Vector.projected(vectorToEnd, baseVector);
			if (prjToStart.modulo > baseVector.modulo) {
				distance = prjToStart.modulo;
			} else if (prjToEnd.modulo > baseVector.modulo) {
				distance = prjToEnd.modulo;
			} else {
				distance = Vector.plumb(vectorToStart, baseVector).modulo;
			}
			if (distance > max) {
				max = distance;
				maxI = i;
			}
		}
	}
	if (max <= threshold) {
		paths.splice(startI + 2, endI - startI - 2);
	} else {
		if (maxI < endI - 2) {
			check(threshold, maxI, endI, paths);
		}
		if (maxI > startI + 2) {
			check(threshold, startI, maxI, paths);
		}
	}
};

export const douglasPeucker = (threshold: number, pathArr: number[]) => {
	const pathCopy = pathArr.slice();
	check(threshold, 0, pathCopy.length - 2, pathCopy);
	return pathCopy;
};

import { vec3 } from 'gl-matrix';

type Intersectable = { // intersectable rectangle
	position: vec3; // top left corner
    topSide: vec3; // top right corner
    leftSide: vec3; // bottom left corner
    callback?: (type?: string) => void
};

type Ray = {
	position: vec3;
	direction: vec3;
};

type Intersection = {
    key: string,
    distance: number,
}

// for now we're dealing with a very small number of intersectables,
// so it doesn't make sense to optimize this to something better (e.g. quadtree)
const intersectables = new Map<string, Intersectable>();

export const register = (key: string, intersectable: Intersectable) => {
    intersectables.set(key, intersectable);
};

export const unRegister = (key: string) => {
    intersectables.delete(key);
};

const projectOnto = (onto: vec3, vector: vec3): vec3 | null => {
    const ontolen = vec3.len(onto);
    const scale = vec3.dot(onto, vector) / ontolen;
    if (scale < 0) return null; // we don't want to use the projection if the angle between the two is obtuse
    return vec3.scale(vec3.create(), onto, scale / ontolen);
}

// console.log(projectOnto(
//     vec3.fromValues(1, 0, 0),
//     vec3.fromValues(-1, 1, 0)
// ))

const getRectangleRayIntersection = (
    () => {
        // create a bunch of empty vec3s to reuse
        const P0MinusR0 = vec3.create();
        const N = vec3.create();
        const P = vec3.create();
        const P0P = vec3.create();
        const PP = vec3.create();
        return (ray: Ray, intersectable: Intersectable): number => {
            vec3.subtract(P0MinusR0, intersectable.position, ray.position);
            vec3.cross(N, intersectable.topSide, intersectable.leftSide);
            const DDotN = vec3.dot(ray.direction, N);

            const P0MinusR0DotN = vec3.dot(P0MinusR0, N);

            const t = P0MinusR0DotN / DDotN;

            vec3.add(P, ray.position, vec3.scale(PP, ray.direction, t));
            vec3.sub(P0P, P, intersectable.position);

            const Q1 = projectOnto(intersectable.leftSide, P0P);
            const Q2 = projectOnto(intersectable.topSide, P0P);

            if (!Q1 || !Q2) return -1;

            const Q1Length = vec3.length(Q1);
            const Q2Length = vec3.length(Q2);
            const leftSideLength = vec3.length(intersectable.leftSide);
            const topSideLength = vec3.length(intersectable.topSide);

            if (Q1Length >= 0 && Q1Length <= leftSideLength
                && Q2Length >= 0 && Q2Length <= topSideLength) {
                return t;
            }

            return -1;
        };
    }
)();

// console.log(getRectangleRayIntersection(
//     {
//         position: vec3.fromValues(1, -1, 0),
//         direction: vec3.fromValues(0, 0, 1)
//     },
//     {
//         position: vec3.fromValues(0, 0, 1),
//         topSide: vec3.fromValues(2, 0, 0),
//         leftSide: vec3.fromValues(0, 2, 0)
//     }
// ));

// expect no intersection

export const getRectangleRayIntersections = (ray: Ray, type?: string) => {
    const intersections = Array<Intersection>();
	intersectables.forEach((intersectable, key) => {
		const intersection = getRectangleRayIntersection(ray, intersectable);
		if (intersection > 0) {
            // TODO: instead of sorting later, push items in the right spot
            intersections.push({
                distance: intersection,
                key,
            });
		}
    });
    intersections.sort((a, b) => a.distance < b.distance ? -1 : 1);
    if (intersections.length) {
        const first = intersectables.get(intersections[0].key);
        if (first && first.callback) {
            first.callback(type);
        }
    }
	return intersections;
};

// - Supported via standard GitHub programming aids
import { EventEmitter } from 'events';

// We'll dynamically mock dependencies before importing the module under test.
describe('CockroachDaemon (init / setup / startup / monitor)', () => {

    let execCalls: string[];
    let spawnMock: jest.Mock;

    // Helper to reset modules and set mocks, then import the class
    async function loadWithMocks(readdirReturn: string[] = []) {
        jest.resetModules();
        execCalls = [];

        // Mock fs/promises
        const fsPromisesMock = {
            readdir: jest.fn(async () => readdirReturn.slice()),
            rm: jest.fn(async () => undefined),
            mkdir: jest.fn(async () => undefined),
        };
        jest.doMock('fs/promises', () => fsPromisesMock);

        // Capture exec commands via promisify(exec)(cmd)
        jest.doMock('util', () => ({
            promisify: jest.fn(() => (cmd: string) => {
                execCalls.push(cmd);
                return Promise.resolve('');
            })
        }));

        // Mock child_process.spawn to return a fake child process with EventEmitters
        spawnMock = jest.fn(() => {
            const stdout = new EventEmitter();
            const stderr = new EventEmitter();
            // Provide .on for compatibility (EventEmitter already has it)
            return { stdout, stderr, pid: 12345 } as any;
        });
        jest.doMock('child_process', () => ({
            spawn: spawnMock,
            exec: jest.fn()
        }));

        // Mock Environment used by the module under test
        const envPath = require.resolve('../src/Enviroment');
        jest.doMock(envPath, () => ({
            Environment: {
                COCKROACH_VERSION: '25.3.0',
                COCKROACH_DOWNLOAD: 'https://example.test/cockroach.tgz'
            }
        }));

        // Mock Daemon and its eventBus (export a class so it can be extended)
        const eventBus = { emit: jest.fn() };
        class MockDaemon {
            static eventBus = eventBus;
        }
        // Determine absolute path to src/Deamon so module id matches imports inside the tested module
        const path = require('path');
        const daemonPath = require.resolve(path.join(process.cwd(), 'src', 'Deamon'));
        jest.doMock(daemonPath, () => ({ Daemon: MockDaemon }));

        // Mock global.fetch for monitor tests (will override in individual tests)
        // Provide a default that rejects to simulate down state
        // @ts-ignore
        global.fetch = jest.fn(async () => { throw new Error('fetch not mocked in test'); });

        // Intercept setInterval so we can capture callbacks without creating real timers
        const createdTimers: any[] = [];
        jest.spyOn(global, 'setInterval').mockImplementation((fn: any, ms?: number, ...args: any[]) => {
            createdTimers.push(fn);
            // return a fake id typed as NodeJS.Timeout to satisfy TypeScript
            const fakeId = {} as NodeJS.Timeout;
            return fakeId;
        });

        const mod = require('../src/modules/CockroachDeamon');
        return {
            CockroachDaemon: mod.CockroachDaemon,
            mocks: {
                fsPromisesMock,
                execCalls,
                spawnMock,
                eventBus,
                createdTimers,
            }
        };
    }

    afterEach(() => {
        jest.useRealTimers();
        // Clear global fetch mock
        // @ts-ignore
        if (global.fetch && (global.fetch as jest.Mock).mockClear) (global.fetch as jest.Mock).mockClear();
        // Clear any intervals created during tests
        try {
            // Access createdTimers if present from last loadWithMocks
            // @ts-ignore
            const lastModule = require.cache[require.resolve('../src/modules/CockroachDeamon')];
            if (lastModule && lastModule.exports && lastModule.exports.CockroachDaemon && lastModule.exports.CockroachDaemon.createdTimers) {
                const timers = lastModule.exports.CockroachDaemon.createdTimers as any[];
                timers.forEach(t => clearInterval(t));
            }
        }
        catch (e) {
            // ignore
        }
        jest.resetAllMocks();
        jest.resetModules();
    });

    test('init returns singleton and calls setup + startup only once', async () => {
        const { CockroachDaemon } = await loadWithMocks(['cockroach-25.3.0']);

        // Spy on prototype.setup and startup
        const setupSpy = jest.spyOn((CockroachDaemon as any).prototype, 'setup').mockResolvedValue(undefined);
        const startupSpy = jest.spyOn((CockroachDaemon as any).prototype, 'startup').mockImplementation(() => {});

        const a = await (CockroachDaemon as any).init('single');
        const b = await (CockroachDaemon as any).init('single');

        expect(a).toBe(b);
        expect(setupSpy).toHaveBeenCalledTimes(1);
        expect(startupSpy).toHaveBeenCalledTimes(1);

        // clear singleton to avoid leaking to other tests
        (CockroachDaemon as any).singleton = undefined;
    });

    test('setup: binary exists and is up to date -> no download/extract/chmod', async () => {
        const { CockroachDaemon, mocks } = await loadWithMocks(['cockroach-25.3.0']);

        // Prevent startup side-effects
        jest.spyOn((CockroachDaemon as any).prototype, 'startup').mockImplementation(() => {});

        await (CockroachDaemon as any).init('single');

        expect(mocks.fsPromisesMock.readdir).toHaveBeenCalledWith('bin/');
        expect(mocks.execCalls.length).toBe(0);

        (CockroachDaemon as any).singleton = undefined;
    });

    test('setup: binary outdated -> remove old, download, extract, chmod', async () => {
        const { CockroachDaemon, mocks } = await loadWithMocks(['cockroach-25.2.0']);

        // Prevent startup side-effects
        jest.spyOn((CockroachDaemon as any).prototype, 'startup').mockImplementation(() => {});

        await (CockroachDaemon as any).init('single');

        // removed old binary folder
        expect(mocks.fsPromisesMock.rm).toHaveBeenCalledWith('bin/cockroach-25.2.0', { recursive: true });

        // commands captured
        expect(mocks.execCalls.some(c => c.includes('wget'))).toBeTruthy();
        expect(mocks.execCalls.some(c => c.includes('tar -xzf'))).toBeTruthy();
        expect(mocks.execCalls.some(c => c.includes('chmod +x'))).toBeTruthy();

        (CockroachDaemon as any).singleton = undefined;
    });

    test('setup: binary missing -> download, extract, chmod and mkdir', async () => {
        const { CockroachDaemon, mocks } = await loadWithMocks([]);

        // Prevent startup side-effects
        jest.spyOn((CockroachDaemon as any).prototype, 'startup').mockImplementation(() => {});

        await (CockroachDaemon as any).init('single');

        expect(mocks.fsPromisesMock.mkdir).toHaveBeenCalledWith('bin/cockroach-25.3.0');
        expect(mocks.execCalls.some(c => c.includes('wget'))).toBeTruthy();
        expect(mocks.execCalls.some(c => c.includes('tar -xzf'))).toBeTruthy();
        expect(mocks.execCalls.some(c => c.includes('chmod +x'))).toBeTruthy();

        (CockroachDaemon as any).singleton = undefined;
    });

    test('startup: spawn called with correct binary and args; stdout/stderr forwarded', async () => {
        const { CockroachDaemon, mocks } = await loadWithMocks(['cockroach-25.3.0']);

        // Spy on info/error to capture forwarded messages
        const infoSpy = jest.spyOn((CockroachDaemon as any).prototype, 'info').mockImplementation(() => {});
        const errorSpy = jest.spyOn((CockroachDaemon as any).prototype, 'error').mockImplementation(() => {});

        // Let init run full flow (setup + startup)
        const instance = await (CockroachDaemon as any).init('single');

        expect(mocks.spawnMock).toHaveBeenCalled();
        const spawnArgs = mocks.spawnMock.mock.calls[0];
        const exe = spawnArgs[0];
        const args = spawnArgs[1];

        expect((exe as string)).toContain('bin/cockroach-25.3.0/cockroach');
        expect(args).toEqual(expect.arrayContaining([
            'start-single-node',
            '--certs-dir=data/cockroach-certs',
            '--store=data/cockroach-single',
            '--listen-addr=localhost'
        ]));

        // Grab the fake process and emit data on stdout/stderr
        const fakeProc = mocks.spawnMock.mock.results[0].value;
        fakeProc.stdout.emit('data', Buffer.from('hello\n'));
        fakeProc.stderr.emit('data', Buffer.from('boom\n'));

        expect(infoSpy).toHaveBeenCalled();
        expect(errorSpy).toHaveBeenCalled();

        (CockroachDaemon as any).singleton = undefined;
    });

    test('monitor: emits running when health endpoint is reachable and stopped when not', async () => {
        const { CockroachDaemon, mocks } = await loadWithMocks(['cockroach-25.3.0']);

        // Prevent startup side-effects
        jest.spyOn((CockroachDaemon as any).prototype, 'startup').mockImplementation(() => {});

    // First, fetch resolves -> running
    // @ts-ignore
    global.fetch = jest.fn(async () => ({}));

    const instance = await (CockroachDaemon as any).init('single');

    // The constructor captured the monitor callback in createdTimers; call it directly
    expect(mocks.createdTimers.length).toBeGreaterThan(0);
    // invoke the monitor callback and wait for it
    await mocks.createdTimers[0]();

    expect(mocks.eventBus.emit).toHaveBeenCalledWith('cockroach:running');

    // Now make fetch reject -> stopped
    // @ts-ignore
    global.fetch = jest.fn(async () => { throw new Error('down'); });

    await mocks.createdTimers[0]();

    expect(mocks.eventBus.emit).toHaveBeenCalledWith('cockroach:stopped');

        (CockroachDaemon as any).singleton = undefined;
    });

});

import {
  CodeModel,
  Schema,
  ObjectSchema,
  isObjectSchema,
  SchemaType,
  Property,
  ParameterLocation,
  Operation,
  Parameter,
  VirtualParameter,
  getAllProperties,
  ImplementationLocation,
  DictionarySchema,
} from "@azure-tools/codemodel";
import { Session } from "@azure-tools/autorest-extension-base";
import { values, items, length, Dictionary, refCount, clone } from "@azure-tools/linq";
import { ModelerFourOptions } from "../modeler/modelerfour-options";

export class Checker {
  codeModel: CodeModel;
  options: ModelerFourOptions = {};

  constructor(protected session: Session<CodeModel>) {
    this.codeModel = session.model; // shadow(session.model, filename);
  }

  async init() {
    // get our configuration for this run.
    this.options = await this.session.getValue("modelerfour", {});
    return this;
  }

  checkOperationGroups() {
    for (const dupe of values(this.codeModel.operationGroups)
      .select((each) => each.language.default.name)
      .duplicates()) {
      this.session.error(`Duplicate Operation group '${dupe}' detected .`, []);
    }
  }

  checkOperations() {
    for (const group of this.codeModel.operationGroups) {
      for (const dupe of values(group.operations)
        .select((each) => each.language.default.name)
        .duplicates()) {
        this.session.error(`Duplicate Operation '${dupe}' detected.`, []);
      }
    }
  }

  checkSchemas() {
    const allSchemas = values(<Dictionary<Array<Schema>>>(<any>this.codeModel.schemas))
      .selectMany((schemas) => (Array.isArray(schemas) ? values(schemas) : []))
      .toArray();

    for (const each of values(allSchemas).where((each) => !each.language.default.name)) {
      this.session.warning(`Schema Missing Name '${JSON.stringify(each)}'.`, []);
    }

    const types = values(<Array<Schema>>this.codeModel.schemas.objects)
      .concat(values(this.codeModel.schemas.groups))
      .concat(values(this.codeModel.schemas.choices))
      .concat(values(this.codeModel.schemas.sealedChoices))
      .toArray();
    for (const dupe of values(types).duplicates((each) => each.language.default.name)) {
      this.session.error(`Duplicate object schemas with '${dupe.language.default.name}' name  detected.`, []);
    }

    /* for (const dupe of values(this.codeModel.schemas.numbers).select(each => each.type).duplicates()) {
      this.session.error(`Duplicate '${dupe}' detected.`, []);
    }; */
  }

  process() {
    if (this.options["additional-checks"] !== false) {
      this.checkOperationGroups();

      this.checkOperations();

      this.checkSchemas();
    }
    return this.codeModel;
  }
}

