const syllablesNum = (str: string) => str.split(/[aiouy]+e*|e(?!d$|ly).|[td]ed|le$/).length;

export default [

	// delicious => more delicious
	{
		test: (str: string) => syllablesNum(str) > 3 && !(syllablesNum(str) < 5 && /y$/.test(str)),
		comp: (str: string) => "more " + str,
		supr: (str: string) => "most " + str
	},

	// boring => more boring
	{
		test: (str: string) => syllablesNum(str) > 2 && /ing$/.test(str),
		comp: (str: string) => "more " + str,
		supr: (str: string) => "most " + str
	},

	// crowded => more crowded
	{
		test: (str: string) => syllablesNum(str) > 2 && /ed$/.test(str),
		comp: (str: string) => "more " + str,
		supr: (str: string) => "most " + str
	},

	// big => bigger
	{
		test: (str: string) => /[^aeiouy][aeiouy][^rwaeiouy]$/.test(str),
		comp: (str: string) => str.replace(/([^aeiouy])$/, "$1$1er"),
		supr: (str: string) => str.replace(/([^aeiouy])$/, "$1$1est"),
	},

	// heavy => heavier
	{
		test: (str: string) => /y$/.test(str),
		comp: (str: string) => str.replace(/y$/, "ier"),
		supr: (str: string) => str.replace(/y$/, "iest"),
	},

	// handsome => handsomer
	{
		test: (str: string) => /e$/.test(str),
		comp: (str: string) => str.replace(/e$/, "er"),
		supr: (str: string) => str.replace(/e$/, "est"),
	},

	// all other cases
	{
		test: (str: string) => true,
		comp: (str: string) => str + "er",
		supr: (str: string) => str + "est",
	}
];

import {UserWithId} from "@/app/login/page";
import {BACKENDURL} from "@/app/statics";
import {CategoryWithApi, Passwords, VaultEntry} from "@/app/vault/vaultEntry";
import Router from 'next/router';

/*
import {Category} from "@/app/vault/category";
*/

export async function getPasswordForUser(page: number): Promise<{
    vault: Promise<VaultEntry>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}passwords?page=${page}`, {
        method: "GET",
        headers: {
            "Content-Type": "application/json",
        },
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    if (resp.status === 200)
        return {vault: resp.json(), status: resp.status}

    let vault: VaultEntry = {page: 0, passwords: [], total: 0}
    return {vault: Promise.resolve(vault), status: resp.status}

}

export async function getAllPasswordForUser(): Promise<{
    passwords: Promise<Passwords[]>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}passwords`, {
        method: "GET",
        headers: {
            "Content-Type": "application/json",
        },
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    if (resp.status === 200)
        return {passwords: resp.json(), status: resp.status}

    let vault: Passwords = {
        id: "",
        description: "",
        password: "",
        title: "",
        url: "",
        userid: "",
        username: "",
        category: {
            id: "",
            name: "",
            userid: ""
        }
    } 
    return {passwords: Promise.resolve([vault]), status: resp.status}

}

export async function createNewEntry(entry: Passwords): Promise<{
    vault: Promise<VaultEntry>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}passwords/`, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify({
            title: entry.title,
            description: entry.description,
            url: entry.url,
            username: entry.username,
            password: entry.password,
            category: entry.category
        }),
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    if (resp.status === 200)
        return {vault: resp.json(), status: 200}
    let vault: VaultEntry = {page: 0, passwords: [], total: 0}

    return {
        vault: Promise.resolve(vault), status: resp.status
    }

}

export async function deletePassword(id: string): Promise<number> {
    const resp = await fetch(`${BACKENDURL}passwords/${id}`, {
        method: "DELETE",
        headers: {
            "Content-Type": "application/json",
        },
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    return resp.status
}

// most this code snippet was Aided using common development resources
export async function editEntryAPI(id: string, entry: Passwords): Promise<VaultEntry> {
    // Stelle sicher, dass die ID korrekt in die URL integriert wird
    const url = `${BACKENDURL}passwords/${id}`;

    console.log("Attempting to update entry at URL:", url); // Zum Debuggen der URL

    try {
        const resp = await fetch(url, {
            method: "PUT",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify(entry),
            credentials: "include",
            mode: "cors",
        });

        if (resp.status === 403 || resp.status === 401) {
            Router.push("/login");
            throw new Error('Unauthorized or Forbidden access - redirected to login');
        }

        if (!resp.ok) {
            const errorText = await resp.text(); // Für detaillierte Fehlermeldungen
            throw new Error(`Failed to update the password entry: ${errorText}`);
        }

        return await resp.json();
    } catch (error) {
        console.error("Error in editEntryAPI:", error);
        throw error;
    }
}

export async function changeMasterPassword(user: UserWithId): Promise<{
    user: Promise<UserWithId>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}users/${user.id}`, {
        method: "PUT",
        headers: {
            "Content-Type": "application/json",
        },
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
        body: JSON.stringify({
            email: user.email,
            password: user.password,
            id: user.id
        })
    })

    if (resp.status === 200)
        return {user: resp.json(), status: resp.status}
    return {user: Promise.resolve({id: "", email: "", password: ""}), status: resp.status}

}


export async function createNewCategory(entry: string): Promise<{
    category: Promise<CategoryWithApi>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}categories/`, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify({
            name: entry,
        }),
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    if (resp.status === 200)
        return {category: resp.json(), status: 200}

    return {
        category: Promise.resolve({
            id: "",
            name: "",
            userid: ""
        }), status: resp.status
    }

}

import { useState, useEffect, useCallback } from 'react';

/*
 * This code was Aided using common development resources 4.0
 */

type UseVocalRangeHook = {
  frequency: number | null;
  vocalRange: string | null;
  error: string | null;
  start: () => void;
  stop: () => void;
};

export const useVocalRange = (): UseVocalRangeHook => {
  const [frequency, setFrequency] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [audioContext, setAudioContext] = useState<AudioContext | null>(null);

  const getVocalRange = (frequency: number | null): string | null => {
    if (!frequency) return null;
    if (frequency >= 82.41 && frequency <= 329.63) return 'Bass';
    if (frequency >= 110 && frequency <= 440) return 'Baritone';
    if (frequency >= 130.81 && frequency <= 523.25) return 'Tenor';
    if (frequency >= 174.61 && frequency <= 698.46) return 'Alto';
    if (frequency >= 220.00 && frequency <= 880.00) return 'Mezzo-Soprano';
    if (frequency >= 261.63 && frequency <= 1046.5) return 'Soprano';
    return 'Out of range';
  };

  const vocalRange = getVocalRange(frequency);

  const start = useCallback(() => {
    const context = new window.AudioContext();
    setAudioContext(context);
  }, []);

  const stop = useCallback(() => {
    if (audioContext && audioContext.state !== 'closed') {
      audioContext.close();
      setAudioContext(null);
    }
  }, [audioContext]);

  useEffect(() => {
    if (!audioContext) return;

    const analyser = audioContext.createAnalyser();

    navigator.mediaDevices
      .getUserMedia({ audio: true, video: false })
      .then((stream) => {
        const source = audioContext.createMediaStreamSource(stream);
        source.connect(analyser);

        const frequencyData = new Uint8Array(analyser.frequencyBinCount);
        const updateFrequency = () => {
          requestAnimationFrame(updateFrequency);
          analyser.getByteFrequencyData(frequencyData);

          const maxIndex = frequencyData.reduce(
            (iMax, x, i, arr) => (x > arr[iMax] ? i : iMax),
            0
          );
          const frequency =
            (maxIndex * audioContext.sampleRate) / (2 * analyser.fftSize);

          setFrequency(frequency);
        };

        updateFrequency();
      })
      .catch((err) => {
        setError(err.message);
      });

    return () => {
      stop();
    };
  }, [audioContext, stop]);

  return { frequency, vocalRange, error, start, stop };
};

