    // [::1] is the IPv6 localhost address.
    window.location.hostname === '[::1]' ||
    // 127.0.0.0/8 are considered localhost for IPv4.
    window.location.hostname.match(
      /^127(?:\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/
    )
);

type Config = {
  onSuccess?: (registration: ServiceWorkerRegistration) => void;
  onUpdate?: (registration: ServiceWorkerRegistration) => void;
};

export function register(config?: Config) {
  if (process.env.NODE_ENV === 'production' && 'serviceWorker' in navigator) {
    // The URL constructor is available in all browsers that support SW.
    const publicUrl = new URL(
      process.env.PUBLIC_URL,
      window.location.href
    );
    if (publicUrl.origin !== window.location.origin) {
      // Our service worker won't work if PUBLIC_URL is on a different origin
      // from what our page is served on. This might happen if a CDN is used to
      // serve assets; see https://github.com/facebook/create-react-app/issues/2374
      return;
    }

    window.addEventListener('load', () => {
      const swUrl = `${process.env.PUBLIC_URL}/service-worker.js`;

      if (isLocalhost) {
        // This is running on localhost. Let's check if a service worker still exists or not.
        checkValidServiceWorker(swUrl, config);

        // Add some additional logging to localhost, pointing developers to the
        // service worker/PWA documentation.
        navigator.serviceWorker.ready.then(() => {
          console.log(
            'This web app is being served cache-first by a service ' +
              'worker. To learn more, visit https://bit.ly/CRA-PWA'
          );
        });
      } else {
        // Is not localhost. Just register service worker
        registerValidSW(swUrl, config);
      }
    });
  }
}

function registerValidSW(swUrl: string, config?: Config) {
  navigator.serviceWorker
    .register(swUrl)
    .then(registration => {
      registration.onupdatefound = () => {
        const installingWorker = registration.installing;
        if (installingWorker == null) {
          return;
        }
        installingWorker.onstatechange = () => {
          if (installingWorker.state === 'installed') {
            if (navigator.serviceWorker.controller) {
              // At this point, the updated precached content has been fetched,
              // but the previous service worker will still serve the older
              // content until all client tabs are closed.
              console.log(
                'New content is available and will be used when all ' +
                  'tabs for this page are closed. See https://bit.ly/CRA-PWA.'
              );

              // Execute callback
              if (config && config.onUpdate) {
                config.onUpdate(registration);
              }
            } else {
              // At this point, everything has been precached.
              // It's the perfect time to display a
              // "Content is cached for offline use." message.
              console.log('Content is cached for offline use.');

              // Execute callback
              if (config && config.onSuccess) {
                config.onSuccess(registration);
              }
            }
          }
        };
      };
    })
    .catch(error => {
      console.error('Error during service worker registration:', error);
    });
}

function checkValidServiceWorker(swUrl: string, config?: Config) {
  // Check if the service worker can be found. If it can't reload the page.
  fetch(swUrl, {
    headers: { 'Service-Worker': 'script' }
  })
    .then(response => {
      // Ensure service worker exists, and that we really are getting a JS file.
      const contentType = response.headers.get('content-type');
      if (
        response.status === 404 ||
        (contentType != null && contentType.indexOf('javascript') === -1)
      ) {
        // No service worker found. Probably a different app. Reload the page.
        navigator.serviceWorker.ready.then(registration => {
          registration.unregister().then(() => {
            window.location.reload();
          });
        });
      } else {
        // Service worker found. Proceed as normal.
        registerValidSW(swUrl, config);
      }
    })
    .catch(() => {
      console.log(
        'No internet connection found. App is running in offline mode.'
      );
    });
}

export function unregister() {
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.ready
      .then(registration => {
        registration.unregister();
      })
      .catch(error => {
        console.error(error.message);
      });
  }
}

import { Keys } from "./types/keys";
import { Settings } from "./types/settings";
import { onEventListenerStatusChange } from "./utils/eventHandling.utils";
import { getArrayBuffer } from "./utils/file.utils";

let audioCtx: AudioContext | undefined;
let panner: PannerNode | undefined;

// MeSpeak
const meSpeak = require("mespeak");
meSpeak.loadConfig(require("../public/mespeak-config.json"));
meSpeak.loadVoice(require("mespeak/voices/en/en-us.json"));

// Scroll Indicator
const beepFileURL = require("../public/beep.mp3");
let beepArrayBuffer: ArrayBuffer;
let beepAudioBuffer: AudioBuffer;

getArrayBuffer(beepFileURL).then((buffer) => {
  beepArrayBuffer = buffer;
});

let pitchConst = 350;

/** Sets the position of the PannerNode. */
export function setPannerPosition(x: number = 0, y: number = 0, z: number = 5): void {
  if (!panner) {
    console.error(
      "Panner has not been initialized; make sure to only call setPannerPosition() once you're the audioContext has been initialized!"
    );
    return;
  }

  panner.positionX.value = Math.min(Math.max(x, leftStereoCutoff), rightStereoCutoff) * 20;
  panner.positionY.value = y;
  panner.positionZ.value = z;
}

let lastSoundSource: { sourceNode: AudioBufferSourceNode; id: number } | undefined;
let soundPromiseRejectMethods: Map<number, Function> = new Map();
let soundsPlayed = 0;
let sources: AudioBufferSourceNode[] = [];

let leftStereoCutoff = -1;
let rightStereoCutoff = 1;

let voiceSpeed = 175;

let spatializeAudio = true;
chrome.storage.sync.get(["spatializeAudio", "leftStereoCutoff", "rightStereoCutoff", "voiceSpeed"], (items) => {
  const loadedSettings = items as Partial<Settings>;

  spatializeAudio = loadedSettings.spatializeAudio ?? true;
  leftStereoCutoff = loadedSettings.leftStereoCutoff ?? -1;
  rightStereoCutoff = loadedSettings.rightStereoCutoff ?? 1;
  voiceSpeed = loadedSettings.voiceSpeed ?? 175;
});

interface PlaySoundProps {
  bias: { x: number; y: number };
  text?: string;
  scrollBeep?: boolean;
}

export async function playSound({ bias, text, scrollBeep = false }: PlaySoundProps): Promise<void> {
  if (text === "") return;

  return new Promise(async (resolve, reject) => {
    if (!spatializeAudio) bias = { x: 0, y: 0 };

    if (!audioCtx) {
      audioCtx = new AudioContext();
      panner = audioCtx.createPanner();

      beepAudioBuffer = await audioCtx.decodeAudioData(beepArrayBuffer);
    }

    await audioCtx.resume();

    const id = soundsPlayed++;

    soundPromiseRejectMethods.set(id, reject);

    // Prevent multiple sounds from playing at the same time
    stopAllSounds();

    let source = audioCtx.createBufferSource();
    lastSoundSource = { sourceNode: source, id: id };
    sources.push(source);

    if (!scrollBeep) {
      // TTS using MeSpeak
      const audioData = meSpeak.speak(text, { speed: voiceSpeed, rawdata: true });
      source.buffer = await audioCtx.decodeAudioData(audioData);
    } else {
      // Royalty free beep: https://samplefocus.com/samples/short-beep
      if (!beepArrayBuffer) {
        console.error("There was an error in loading the beep sound file.");
        reject();
        return;
      }

      source.buffer = beepAudioBuffer;
    }

    source.onended = () => {
      lastSoundSource = undefined;
      resolve();
    };

    // Modifies pitch based on provided y-value
    setPannerPosition(bias.x, bias.y);

    source.detune.value = pitchConst * panner!.positionY.value;

    // Balancing volume levels
    const gainNode = audioCtx.createGain();
    gainNode.gain.value = logarithmicIncrease(Math.abs(bias.x)); // Gain increases as distance from center increases to help balance out volume levels

    console.log(`%cGain amount: ${gainNode.gain.value}; Bias: x: ${bias.x}, y: ${bias.y}`, "color: lightblue");

    source.connect(gainNode).connect(panner!).connect(audioCtx.destination);

    source.start(0);
  });
}

export function stopAllSounds() {
  try {
    if (lastSoundSource !== undefined) {
      lastSoundSource.sourceNode.stop();

      //Reject last sound's promise
      soundPromiseRejectMethods.get(lastSoundSource.id)!(lastSoundSource.id);
      soundPromiseRejectMethods.delete(lastSoundSource.id);

      lastSoundSource = undefined;
    }

    for (let i = 0; i < sources.length; i++) {
      const source = sources[i];

      if (source) {
        source.stop();
      }
    }
  } catch {
    // Possible error: InvalidStateNode (DOMException) Thrown if the node has not been started by calling start(). (https://developer.mozilla.org/en-US/docs/Web/API/AudioScheduledSourceNode/stop)
    // This error isn't important. A try/catch block is used to help keep the console neater until a better method of solving this issue is found.
  }
}

const cancelSoundsCallback = (e: KeyboardEvent) => {
  if (e.key.toLowerCase() === Keys.Esc) stopAllSounds();
};
const addCancelSoundsHandler = () => document.addEventListener("keydown", cancelSoundsCallback);
const clearCancelSoundsHandler = () => document.removeEventListener("keydown", cancelSoundsCallback);

// Supported via standard programming aids
function logarithmicIncrease(x: number) {
  const maxOutput = 10; // Set the maximum output value
  const minInput = 0.25; // Set the input value where the curve peaks
  const k = Math.log(maxOutput + 1) / Math.log(1 + maxOutput * (1 - minInput)); // Calculate the logarithmic scaling factor
  return (Math.log(1 + maxOutput * x) / Math.log(1 + maxOutput * minInput)) * k + 1; // Apply the logarithmic scaling factor and shift output to start at 1
}

onEventListenerStatusChange({ onEnable: addCancelSoundsHandler, onDisable: clearCancelSoundsHandler });

/*
 * Created by David Adams
 * https://codeshack.io/multi-select-dropdown-html-javascript/
 *
 * Released under the MIT license
 * Supported via standard GitHub programming aids
 */

export interface MultiSelectOptions {
  placeholder?: string;
  max?: number | null;
  search?: boolean;
  selectAll?: boolean;
  listAll?: boolean;
  closeListOnItemSelect?: boolean;
  name?: string;
  width?: string;
  height?: string;
  dropdownWidth?: string;
  dropdownHeight?: string;
  data?: Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }>;
  onChange?: (values: string[], text: string, option: HTMLElement) => void;
  onSelect?: (value: string, text: string, option: HTMLElement) => void;
  onUnselect?: (value: string, text: string, option: HTMLElement) => void;
  selectElement?: HTMLElement; // Supported via standard GitHub programming aids
  element?: HTMLElement; // Supported via standard GitHub programming aids
}

export class MultiSelect {
  private _options: MultiSelectOptions;
  private _selectElement: HTMLElement;
  private _element: HTMLElement;
  private _name: string;

  constructor(element: string | HTMLElement, options: MultiSelectOptions = {}) {
    const defaults: MultiSelectOptions = {
      placeholder: "Select item(s)",
      max: null,
      search: true,
      selectAll: true,
      listAll: true,
      closeListOnItemSelect: false,
      name: "",
      width: "",
      height: "",
      dropdownWidth: "",
      dropdownHeight: "",
      data: [],
      onChange: () => {},
      onSelect: () => {},
      onUnselect: () => {},
    };
    this._options = { ...defaults, ...options };
    this._selectElement =
      typeof element === "string"
        ? (document.querySelector(element) as HTMLElement)
        : element;

    for (const prop in this._selectElement.dataset) {
      if (this._options[prop as keyof MultiSelectOptions] !== undefined) {
        const value = this._selectElement.dataset[prop];
        if (value !== undefined) {
          (this._options as any)[prop as keyof MultiSelectOptions] = value;
        }
      }
    }

    this._name =
      this._selectElement.getAttribute("name") ||
      "multi-select-" + Math.floor(Math.random() * 1000000);

    if (!this._options.data!.length) {
      const options = this._selectElement.querySelectorAll("option");
      options.forEach((option) => {
        this._options.data!.push({
          value: option.value,
          text: option.innerHTML || option.value,
          selected: option.selected,
          html: option.getAttribute("data-html"),
        });
      });
    }

    this._element = this._template();
    this._selectElement.replaceWith(this._element);
    this._updateSelected();
    this._eventHandlers();
  }

  private _template(): HTMLElement {
    let optionsHTML = "";
    for (let i = 0; i < this.data.length; i++) {
      optionsHTML += `
        <div class="multi-select-option${this.selectedValues.includes(this.data[i].value) ? " multi-select-selected" : ""}" data-value="${this.data[i].value}">
          <span class="multi-select-option-radio"></span>
          <span class="multi-select-option-text">${this.data[i].html ? this.data[i].html : this.data[i].text}</span>
        </div>
      `;
    }

    let selectAllHTML = "";
    if (this._options.selectAll) {
      selectAllHTML = `<div class="multi-select-all">
        <span class="multi-select-option-radio"></span>
        <span class="multi-select-option-text">Select all</span>
      </div>`;
    }

    const template = `
      <div class="multi-select ${this._name}"${this._selectElement.id ? ' id="' + this._selectElement.id + '"' : ""} style="${this.width ? "width:" + this.width + ";" : ""}${this.height ? "height:" + this.height + ";" : ""}">
        ${this.selectedValues.map((value) => `<input type="hidden" name="${this._name}[]" value="${value}">`).join("")}
        <div class="multi-select-header" style="${this.width ? "width:" + this.width + ";" : ""}${this.height ? "height:" + this.height + ";" : ""}">
          <span class="multi-select-header-max">${this._options.max ? this.selectedValues.length + "/" + this._options.max : ""}</span>
          <span class="multi-select-header-placeholder">${this.placeholder}</span>
        </div>
        <div class="multi-select-options" style="${this._options.dropdownWidth ? "width:" + this._options.dropdownWidth + ";" : ""}${this._options.dropdownHeight ? "height:" + this._options.dropdownHeight + ";" : ""}">
          ${this._options.search ? '<input type="text" class="multi-select-search" placeholder="Search...">' : ""}
          ${selectAllHTML}
          ${optionsHTML}
        </div>
      </div>
    `;

    const element = document.createElement("div");
    element.innerHTML = template;
    return element;
  }

  private _eventHandlers(): void {
    const headerElement = this._element.querySelector(
      ".multi-select-header",
    ) as HTMLElement;

    this._element.querySelectorAll(".multi-select-option").forEach((option) => {
      option.addEventListener("click", () => {
        let selected = true;
        const optionText = option.querySelector(
          ".multi-select-option-text",
        )!.innerHTML;
        const optionData = option.getAttribute("data-value");
        if (!option.classList.contains("multi-select-selected")) {
          if (
            this._options.max &&
            this.selectedValues.length >= this._options.max
          ) {
            return;
          }

          option.classList.add("multi-select-selected");
          if (this._options.listAll) {
            if (this._element.querySelector(".multi-select-header-option")) {
              const opt = Array.from(
                this._element.querySelectorAll(".multi-select-header-option"),
              ).pop() as HTMLElement;
              opt.insertAdjacentHTML(
                "afterend",
                `<span class="multi-select-header-option" data-value="${optionData}"></span>`,
              );
            } else {
              headerElement.insertAdjacentHTML(
                "afterbegin",
                `<span class="multi-select-header-option" data-value="${optionData}">${optionText}</span>`,
              );
            }
          }
          this._element.insertAdjacentHTML(
            "afterbegin",
            `<input type="hidden" name="${this._name}[]" value="${optionData}">`,
          );
          this.data.find((data) => data.value == optionData)!.selected = true;
        } else {
          option.classList.remove("multi-select-selected");
          this._element
            .querySelectorAll(".multi-select-header-option")
            .forEach((headerOption) => {
              if (headerOption.getAttribute("data-value") == optionData) {
                headerOption.remove();
              }
            });
          this._element.querySelector(`input[value="${optionData}"]`)!.remove();
          this.data.find((data) => data.value == optionData)!.selected = false;
          selected = false;
        }

        if (!this._element.querySelector(".multi-select-header-option")) {
          //headerElement.insertAdjacentHTML('afterbegin', `<span class="multi-select-header-placeholder">${this.placeholder}</span>`);
        }
        if (this._element.querySelector(".multi-select-header-placeholder")) {
          this._element
            .querySelector(".multi-select-header-placeholder")!
            .remove();
        }
        for (const e of headerElement.querySelectorAll(
          ".multi-select-header-option",
        )) {
          e.remove();
        }
        if (this.selectedValues.length > 0) {
          this.selectedValues.forEach((value) => {
            const text = this.data.find((data) => data.value == value)!.text;
            headerElement.insertAdjacentHTML(
              "afterbegin",
              `<span class="multi-select-header-option" data-value="${value}">${text}</span>`,
            );
          });
        } else {
          headerElement.insertAdjacentHTML(
            "afterbegin",
            `<span class="multi-select-header-placeholder">${this.placeholder}</span>`,
          );
        }

        if (this._options.max) {
          this._element.querySelector(".multi-select-header-max")!.innerHTML =
            this.selectedValues.length + "/" + this._options.max;
        }

        if (this._options.search) {
          (
            this._element.querySelector(
              ".multi-select-search",
            ) as HTMLInputElement
          ).value = "";
        }

        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => option.setAttribute("style", "display: flex;"));

        if (this._options.closeListOnItemSelect) {
          headerElement.classList.remove("multi-select-header-active");
        }

        this._options.onChange!(
          this.selectedValues,
          optionText,
          option as HTMLElement,
        );

        if (selected) {
          this._options.onSelect!(
            optionData!,
            optionText,
            option as HTMLElement,
          );
        } else {
          this._options.onUnselect!(
            optionData!,
            optionText,
            option as HTMLElement,
          );
        }
      });
    });

    headerElement.addEventListener("click", () =>
      headerElement.classList.toggle("multi-select-header-active"),
    );

    if (this._options.search) {
      const search = this._element.querySelector(
        ".multi-select-search",
      ) as HTMLInputElement;
      search.addEventListener("input", () => {
        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => {
            option.setAttribute(
              "style",
              option
                .querySelector(".multi-select-option-text")!
                .innerHTML.toLowerCase()
                .includes(search.value.toLowerCase())
                ? "display: flex;"
                : "display: none;",
            );
          });
      });
    }

    if (this._options.selectAll) {
      const selectAllButton = this._element.querySelector(
        ".multi-select-all",
      ) as HTMLElement;
      selectAllButton.addEventListener("click", () => {
        const allSelected = selectAllButton.classList.contains(
          "multi-select-selected",
        );
        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => {
            const dataItem = this.data.find(
              (data) => data.value == option.getAttribute("data-value"),
            );
            if (
              dataItem &&
              ((allSelected && dataItem.selected) ||
                (!allSelected && !dataItem.selected))
            ) {
              (option as HTMLElement).click();
            }
          });
        selectAllButton.classList.toggle("multi-select-selected");
      });
    }

    if (
      this._selectElement.id &&
      document.querySelector(`label[for="${this._selectElement.id}"]`)
    ) {
      document
        .querySelector(`label[for="${this._selectElement.id}"]`)!
        .addEventListener("click", () => {
          headerElement.classList.toggle("multi-select-header-active");
        });
    }

    document.addEventListener("click", (event) => {
      if (
        !(event.target as Element).closest(`.${this._name}`) &&
        !(event.target as Element).closest(
          `label[for="${this._selectElement.id}"]`,
        )
      ) {
        headerElement.classList.remove("multi-select-header-active");
      }
    });
  }

  private _updateSelected(): void {
    if (this._options.listAll) {
      this._element
        .querySelectorAll(".multi-select-option")
        .forEach((option) => {
          if (option.classList.contains("multi-select-selected")) {
            this._element
              .querySelector(".multi-select-header")!
              .insertAdjacentHTML(
                "afterbegin",
                `<span class="multi-select-header-option" data-value="${option.getAttribute("data-value")}">${option.querySelector(".multi-select-option-text")!.innerHTML}</span>`,
              );
          }
        });
    } else {
      if (this.selectedValues.length > 0) {
        this._element
          .querySelector(".multi-select-header")!
          .insertAdjacentHTML(
            "afterbegin",
            `<span class="multi-select-header-option">${this.selectedValues.length} selected</span>`,
          );
      }
    }

    if (this._element.querySelector(".multi-select-header-option")) {
      this._element.querySelector(".multi-select-header-placeholder")!.remove();
    }
  }

  get selectedValues(): string[] {
    return this.data.filter((data) => data.selected).map((data) => data.value);
  }

  get selectedItems(): Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }> {
    return this.data.filter((data) => data.selected);
  }

  set data(
    value: Array<{
      value: string;
      text: string;
      selected: boolean;
      html: string | null;
    }>,
  ) {
    this._options.data = value;
  }

  get data(): Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }> {
    return this._options.data!;
  }

  set selectElement(value: HTMLElement) {
    this._options.selectElement = value;
  }

  get selectElement(): HTMLElement {
    return this._options.selectElement!;
  }

  set element(value: HTMLElement) {
    this._options.element = value;
  }

  get element(): HTMLElement {
    return this._options.element!;
  }

  set placeholder(value: string) {
    this._options.placeholder = value;
  }

  get placeholder(): string {
    return this._options.placeholder!;
  }

  set name(value: string) {
    this._options.name = value;
  }

  get name(): string {
    return this._options.name!;
  }

  set width(value: string) {
    this._options.width = value;
  }

  get width(): string {
    return this._options.width!;
  }

  set height(value: string) {
    this._options.height = value;
  }

  get height(): string {
    return this._options.height!;
  }
}

document
  .querySelectorAll("[data-multi-select]")
  .forEach((select) => new MultiSelect(select as HTMLElement));

