// Aided with basic GitHub coding tools
import * as vscode from "vscode";
import { TaskTreeItem } from "./task-tree-item";
import { WorkspaceTaskManager } from "../models/task-manager";

/**
 * Provider for the task tree view.
 */
export class TaskTreeDataProvider
  implements vscode.TreeDataProvider<TaskTreeItem>
{
  private _onDidChangeTreeData: vscode.EventEmitter<
    TaskTreeItem | undefined | void
  > = new vscode.EventEmitter<TaskTreeItem | undefined | void>();
  readonly onDidChangeTreeData: vscode.Event<TaskTreeItem | undefined | void> =
    this._onDidChangeTreeData.event;
  private taskManager: WorkspaceTaskManager;
  private groupBy: "file" | "status" | "tag" = "file";

  constructor(taskManager: WorkspaceTaskManager) {
    this.taskManager = taskManager;
    this.taskManager.onTasksChanged(() => this.refresh());
  }

  /**
   * Refresh the tree view.
   */
  public refresh(): void {
    this._onDidChangeTreeData.fire();
  }

  /**
   * Set the grouping method.
   *
   * @param groupBy The grouping method
   */
  public setGroupBy(groupBy: "file" | "status" | "tag") {
    this.groupBy = groupBy;
    this.refresh();
  }

  /**
   * Get tree item for a given element.
   *
   * @param element The element
   * @returns The tree item
   */
  getTreeItem(element: TaskTreeItem): vscode.TreeItem {
    return element;
  }

  /**
   * Get children of a given element.
   *
   * @param element The parent element
   * @returns Array of child elements
   */
  getChildren(
    element?: TaskTreeItem
  ): TaskTreeItem[] | Thenable<TaskTreeItem[]> {
    if (!element) {
      // root: group by file/status/tag
      return this._getGroups();
    }
    if (element.type === "group" || element.type === "file") {
      return this._getTasksForGroup(
        element.groupName || element.label?.toString() || ""
      );
    }
    return [];
  }

  /**
   * Get group items based on the current grouping method.
   *
   * @returns Array of group items
   */
  private _getGroups(): TaskTreeItem[] {
    const tasks = this.taskManager.getAllTasks();
    let groups: string[] = [];
    switch (this.groupBy) {
      case "file":
        // Group by file
        groups = [...new Set(tasks.map((t) => t.filePath))];
        return groups.map((g) => new TaskTreeItem(undefined, "file", g));
      case "status":
        // Group by status
        groups = [...new Set(tasks.map((t) => t.status))];
        return groups.map((g) => new TaskTreeItem(undefined, "group", g));
      case "tag":
        // Group by tag
        groups = [...new Set(tasks.flatMap((t) => t.tags || []))];
        return groups.map((g) => new TaskTreeItem(undefined, "group", g));
      default:
        return [];
    }
  }

  /**
   * Get tasks for a specific group.
   *
   * @param group The group name
   * @returns Array of task items
   */
  private _getTasksForGroup(group: string): TaskTreeItem[] {
    const tasks = this.taskManager.getAllTasks();
    switch (this.groupBy) {
      case "file":
        return tasks
          .filter((t) => t.filePath === group)
          .map((t) => new TaskTreeItem(t, "task"));
      case "status":
        return tasks
          .filter((t) => t.status === group)
          .map((t) => new TaskTreeItem(t, "task"));
      case "tag":
        return tasks
          .filter((t) => (t.tags || []).includes(group))
          .map((t) => new TaskTreeItem(t, "task"));
      default:
        return [];
    }
  }
}

import {lambdaSend} from "../../aws/handlers"
import {Function} from "sst/node/function";
import * as S from '@gnothi/schemas'
import {Config} from 'sst/node/config'
import {v4 as uuid} from 'uuid'
import {sendInsight} from "./utils";
import {completion, Prompt, tokenLimits} from "./openai";
import {getSummary} from '@gnothi/schemas/entries'
import {insights_themes_response, SUMMARIZE_DISABLED, SUMMARIZE_EMPTY} from '@gnothi/schemas/insights'
const r = S.Routes.routes
import {FnContext} from '../../routes/types'
import { encode, decode } from 'gpt-token-utils'


type ThemesOut = insights_themes_response['themes']

export interface SummarizeEntryIn {
  text: string
  paras: string[]
}
export interface SummarizeEntryOut {
  title: string
  paras: string[]
  body: {
    text: string
    emotion: string
    keywords: string[]
  }
}

interface FnIn {
  texts: string[]
}
export type FnOut = {
  title: string
  summary: string
  keywords: string[]
  emotion: string
}
type ParsedCompletion = {
  title: string
  summary: string
  emotion: string
  failed?: boolean
  themes: {
    title: string
    keywords: string[]
    summary: string
  }[]
}

const SYSTEM = `Between >>> and <<< the user will provide content, from which you will extract information and respond with JSON. The JSON template should follow the TypeScript definition below. Read the template carefully for what is to be extracted:
\`\`\`\`typescript
{
  title: string // A short headline 
  summary: string //  A summary, highlighting the key points
  emotion: "anger"|"disgust"|"fear"|"joy"|"neutral"|"sadness"|"surprise"
  // 1 to 3 core concepts in the entry. Never provide more than 3 themes
  themes: Array<{
    title: string // A short title for this theme
    summary: string // One sentence summarizing this theme
    keywords: string[] // 1 to 3 keywords or phrases in this theme. Never provide more than 3
  }>
}
\`\`\`
Reply with a valid JSON object.`

// this was Written with routine coding tools, clean it up when I get a chance
function parseCompletion(originalEntry: string, llmOutput: string): ParsedCompletion {
  try {
    return JSON.parse(llmOutput)
  } catch (e) {
    console.error("LLM failed to output valid JSON", {originalEntry, llmOutput})
    return {
      // match up to the first punctuation or new-line
      title: originalEntry.match(/^(.*?)[\n\r,.!?]/)?.[1] || originalEntry,
      summary: originalEntry,
      emotion: "neutral",
      themes: []
    }
  }
}

function squashTexts(lines: string[]): string {
  // join all lines together, and regex replace all \n with space
  return lines.join('\n').replace(/[\n\r]+/g, ' ')
}

/**
 * I've had a hell of a time with huggingface summarizers. They lean too heavily on
 * the training data, and everything sounds like news. I've played with hyperparameters
 * till I'm blue in the face, and I'm giving up for now and using OpenAI TLDR instead.
 */
export async function summarizeOpenai({texts}: FnIn): Promise<ParsedCompletion> {
  // replace all \n with ' ' before master-prompting
  let squashed = squashTexts(texts)

  // Even with any of keywords,emotion,summary disabled; crafting our combinedPrompt over time makes this easier to
  // get right, and we can just remove the results before returning

  // Don't rely on truncateMessages from openai.ts, since we only want to truncate the journal(s)
  const model = "gpt-4o"
  const max_tokens = 1024
  const squashedTokens = encode(squashed).tokens
  const lengths = {
    journal: squashedTokens.length,
    max: tokenLimits[model],
    reserved: encode(SYSTEM + ">>> [ENTRY] <<<").tokens.length + max_tokens,
    used: 0
  }
  lengths.used = lengths.journal + lengths.reserved
  if (lengths.used > lengths.max) {
    const tokensToDiscard = lengths.journal - (lengths.max - lengths.reserved);
    squashed = decode(squashedTokens.slice(tokensToDiscard));
  }

  const messages: Prompt = [
    {role: "system", content: SYSTEM},
    {role: "user", content: `>>> ${squashed} <<<`},
  ]
  const response = await completion({
    model,
    max_tokens,
    temperature: 0,
    response_format: {type: "json_object"},
    prompt: messages,
    skipTruncate: true,

    // Defaults, since everything's working in Playground, but not live.
    // I think it's because of JSON characters which are repeated, but penalized?
    top_p: 1,
    frequency_penalty: 0,
    presence_penalty: 0,
  })

  return parseCompletion(squashed, response)
}

export async function summarizeLambda({texts}: FnIn): Promise<ParsedCompletion> {
  // replace all \n with ' ' before master-prompting
  const squashed = squashTexts(texts)
  const fnName = Config.FN_SUMMARIZE_NAME
  const res = await lambdaSend<LambdaOut>({texts: squashed}, fnName, "RequestResponse")
  let txt: string = res.Payload.data[0].generated_text
  txt = txt.replaceAll('---', '\n')
  debugger
  return parseCompletion(squashed, txt)
}

/**
 * Helper function for summarize on insights page
 */
interface SummarizeInsights {
  entries: S.Entries.Entry[]
  context: FnContext,
}
export async function summarizeInsights({context, entries}: SummarizeInsights) {
  async function sendInsights(parsed: ParsedCompletion): Promise<FnOut> {
    const themes: ThemesOut = parsed.themes
    const keywords = themes.map(t => t.keywords).flat()
    await Promise.all([
      sendInsight(
        r.insights_summarize_response,
        {...parsed, keywords},
        context
      ),
      sendInsight(
        r.insights_themes_response,
        parsed,
        context
      ),
    ])
  }

  if (entries.length === 0) {
    return sendInsights({
      title: "",
      summary: SUMMARIZE_EMPTY,
      failed: true,
      emotion: "neutral",
      themes: []
    })
  }
  const parsed = await summarizeOpenai({
    // summarize summaries, NOT full originals (to reduce token max)
    texts: entries.map(getSummary),
  })
  return sendInsights(parsed)
}

interface SuggestNextEntry {
  context: FnContext
  entries: S.Entries.Entry[]
  view: string
}
export async function suggestNextEntry({entries, context, view}: SuggestNextEntry) {
  if (!entries?.length) {return}
  const text = squashTexts(entries.map(getSummary))
  const response = await completion({
    model: "gpt-4o",
    max_tokens: 256,
    prompt: `Between >>> and <<< are my prior journal entries. What should I journal about next to encourage personal growth?\n>>> ${text} <<<`
  })
  return sendInsight(
    r.insights_nextentry_response,
    {text: response},
    context
  )
}


export async function summarizeEntry({text, paras}: SummarizeEntryIn): Promise<SummarizeEntryOut> {
  // This shouldn't happen, but I haven't tested to ensure
  if (paras.length === 0) {
    throw "paras.length === 0, investigate"
  }

  const parsed = await summarizeOpenai({
    // summarize summaries, NOT full originals (to reduce token max)
    texts: paras,
  })

  return {
    title: parsed.title,
    paras: [parsed.summary],
    body: {
      text: parsed.summary,
      emotion: parsed.emotion,
      keywords: parsed.themes.map(t => t.keywords).flat(),
    }
  }
}

// Ansi Sequences and convenience functions

import { Console } from "./wasa";

// ANSI Escape
const ESC: string = "\u001b[";

// Ansi Color Codes
export const GREEN: string = ESC + "32m";
export const WHITE: string = ESC + "37m";
export const RED: string = ESC + "31m";
export const CYAN: string = ESC + "36m";
export const RESET: string = ESC + "0m";

// Ansi Cursor Codes
export const HIDE_CURSOR: string = ESC + "?25h";

export function printColor(value: string, color: string): void {
  Console.write(color + value + RESET, false);
}

export function flushConsole(): void {
  Console.write(ESC + "2J", false);
}

// https://github.com/nojvek/matrix-rain/blob/master/ansi.js
export function moveCursorToPosition(column: i32, row: i32): void {
  let cursorPosition: string =
    ESC + row.toString() + ";" + column.toString() + "H";
  Console.write(cursorPosition, false);

  // Hide the cursor
  Console.write(HIDE_CURSOR, false);
}

// Matrix Droplets

import { getRandomNumber, rotateArrayRight } from "./utils";
import {
  ENGLISH_CHARACTER_CODE_START,
  ENGLISH_CHARACTER_CODE_END,
  getRandomCharacterCode
} from "./characters";
import { GREEN, WHITE, printColor, moveCursorToPosition } from "./ansi";

// Our Droplet Class
export class Droplet {
  column: i32;
  row: i32;
  // Going to use a character code array here
  // instead of a string to fix memory issues
  characterCodeArray: Array<u8>;
  speed: i32;
  height: i32;
}

// Function to create a droplet
export function createDroplet(column: i32, lines: i32): Droplet {
  // Create the droplet
  let droplet: Droplet = new Droplet();

  // Populate the droplet values
  droplet.column = column;
  droplet.row = getRandomNumber() % lines;
  droplet.height = (getRandomNumber() % (lines / 2)) + 3;
  droplet.speed = (getRandomNumber() % 2) + 1;

  // Create our initial string
  droplet.characterCodeArray = new Array<u8>(droplet.height);
  for (let i = 0; i < droplet.height; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }

  return droplet;
}

// "Moves" a droplet down the screen
export function updateDroplet(droplet: Droplet, lines: i32): void {
  // Increase the droplet row
  droplet.row += droplet.speed;

  // Wrap the rows so it comes back from up top
  if (droplet.row >= droplet.height + lines) {
    droplet.row = 0 - droplet.height;
  }

  // Rotate down the old characters
  // How many characters to rotate
  for (let i = 0; i < droplet.speed; i++) {
    rotateArrayRight(droplet.characterCodeArray);
  }

  // Add some new characters
  // To replace the old rotated ones
  for (let i = 0; i < droplet.speed; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }
}

// Places a droplet (and its characters) onto the screen
export function drawDroplet(droplet: Droplet, lines: i32): void {
  // Loop over our characters
  for (let i = 0; i < droplet.characterCodeArray.length; i++) {
    let cursorRow = droplet.row + i;

    if (cursorRow >= 0 && cursorRow <= lines) {
      // Move the cursor to the correct position
      moveCursorToPosition(droplet.column, cursorRow);

      // Get our color
      let color: string = GREEN;
      if (i === droplet.characterCodeArray.length - 1) {
        color = WHITE;
      }

      // Draw the character
      // TODO: Optimize this, and try to remove generating / manipulating.
      // Perhpas write the character Codes Array directly?
      printColor(String.fromCharCode(droplet.characterCodeArray[i]), color);
    }
  }
}

import {Pool} from 'pg';
import * as dotenv from 'dotenv';
import {IncomingMessage, ServerResponse} from 'http';

dotenv.config();

const pool = new Pool({
    connectionString: process.env.POSTGRES_URL,
});

// Helper function to parse JSON body - Drafted using common development resources
const parseJsonBody = (req: IncomingMessage) =>
    new Promise<any>((resolve, reject) => {
        let body = '';
        req.on('data', chunk => {
            body += chunk;
        });
        req.on('end', () => {
            try {
                resolve(JSON.parse(body)); // Parse body as JSON
            } catch (err) {
                reject(err); // Reject if there is an error parsing JSON
            }
        });
    });

// Vercel's CORS wrapper
const allowCors = (fn: (req: IncomingMessage, res: ServerResponse) => Promise<void>) =>
    async (req: IncomingMessage, res: ServerResponse): Promise<void> => {
        res.setHeader('Access-Control-Allow-Credentials', 'true');
        res.setHeader('Access-Control-Allow-Origin', '*'); // Or use a specific frontend URL
        res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS,PATCH,DELETE,POST,PUT');
        res.setHeader(
            'Access-Control-Allow-Headers',
            'X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version'
        );

        if (req.method === 'OPTIONS') {
            res.statusCode = 200;
            res.end();
            return;
        }

        return await fn(req, res);
    };

const handler = async (req: IncomingMessage, res: ServerResponse): Promise<void> => {
    if (req.method === 'POST') {
        try {
            const body = await parseJsonBody(req);
            if(!body.email){
                res.statusCode = 400;
                res.end(JSON.stringify({message : 'Error: all fields are required.'}));
                return;
            }
            const [hostedEventsResult, publicEventsResult, attendingEventsResult] = await Promise.all([
                pool.query('SELECT GET_PUBLIC_EVENTS();'),
                pool.query('SELECT GET_HOSTED_EVENTS($1);', [body.email]),
                pool.query('SELECT GET_ATTENDING_EVENTS($1);', [body.email])
            ]);
            const publicEvents = publicEventsResult.rows;
            const hostedEvents = hostedEventsResult.rows;
            const attendedEvents = attendingEventsResult.rows;
            const responseData = {
                publicEvents,
                hostedEvents,
                attendedEvents
            };
            //res.status(200).json(responseData);
            res.statusCode = 201;
            res.end(JSON.stringify(responseData));
            return;
        } catch (err) {
            console.error('Error fetching events:', err);
            res.statusCode = 500;
            res.end(JSON.stringify({message: 'Internal server error.'}));
            console.log(err);
            return;
        }
    } else {
        res.statusCode = 405;
        res.end(JSON.stringify({message: 'Method Not Allowed'}));
        console.log("Method: "+req.method);
        return;
    }
};
export default allowCors(handler);

