import {
  MarkdownPostProcessor,
  MarkdownPostProcessorContext,
  Plugin,
} from "obsidian";

enum TaskType {
  TODO = "TODO",
  DONE = "DONE",
  DOING = "DOING",
  LATER = "LATER",
  CANCELED = "CANCELED",
  UNKNOWN = "UNKNOWN",
}

enum TaskCSSClass {
  COMPLETE = "logseq-complete-task",
  INCOMPLETE = "logseq-incomplete-task",
  KEYWORD = "logseq-keyword",
}

const VERSION = "0.0.4";

class LogSeqRegExes {
  static parseTaskType(content: string): TaskType {
    if (content.startsWith("DONE ")) {
      return TaskType.DONE;
    } else if (content.startsWith("TODO ")) {
      return TaskType.TODO;
    } else if (content.startsWith("DOING ")) {
      return TaskType.DOING;
    } else if (content.startsWith("LATER ")) {
      return TaskType.LATER;
    } else if (content.startsWith("CANCELED ")) {
      return TaskType.CANCELED;
    } else {
      return TaskType.UNKNOWN;
    }
  }

  static HEADING_REGEX = {
    h1: /^(?:\s+)?- # (?:.*)$/gms,
    h2: /^(?:\s+)?- ## (?:.*)$/gms,
    h3: /^(?:\s+)?- ### (?:.*)$/gms,
    h4: /^(?:\s+)?- #### (?:.*)$/gms,
    h5: /^(?:\s+)?- ##### (?:.*)$/gms,
  };

  static HEADING_FORMAT_REGEX = {
    hf1: /^(?:\s+)?- # /gms,
    hf2: /^(?:\s+)?- ## /gms,
    hf3: /^(?:\s+)?- ### /gms,
    hf4: /^(?:\s+)?- #### /gms,
    hf5: /^(?:\s+)?- ##### /gms,
  };

  static BEGIN_BLOCK_REGEX = new RegExp(
    /\#\+BEGIN_(WARNING|IMPORTANT|QUOTE|CAUTION)/gms
  );
  static END_BLOCK_REGEX = new RegExp(
    /\#\+END_(WARNING|IMPORTANT|QUOTE|CAUTION)/gms
  );

  static isBlock(content: string): boolean {
    return LogSeqRegExes.BEGIN_BLOCK_REGEX.test(content);
  }
}

class CodeMirrorOverlays {
  static headingsOverlay = {
    token: (stream: any) => {
      const baseToken = stream.baseToken();
      if (stream.match(LogSeqRegExes.HEADING_REGEX["h1"])) {
        return "header header-1";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h2"])) {
        return "header header-2";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h3"])) {
        return "header header-3";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h4"])) {
        return "header header-4";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h5"])) {
        return "header header-5";
      } else {
        stream.skipToEnd();
      }
    }
  };
  static headingFormatOverlay = {
    token: (stream: any) => {
      const baseToken = stream.baseToken();
      if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf1"])) {
        return "formatting-header formatting-header-1";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf2"])) {
        return "formatting-header formatting-header-2";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf3"])) {
        return "formatting-header formatting-header-3";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf4"])) {
        return "formatting-header formatting-header-4";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf5"])) {
        return "formatting-header formatting-header-5";
      } else {
        stream.skipToEnd();
      }
    }
  };
  static cmAddHeadingOverlay(cm: CodeMirror.Editor) {
    cm.addOverlay(CodeMirrorOverlays.headingsOverlay);
    cm.addOverlay(CodeMirrorOverlays.headingFormatOverlay,{priority:99});
  }

  static cmRemoveHeadingOverlay(cm: CodeMirror.Editor) {
    cm.removeOverlay(CodeMirrorOverlays.headingsOverlay);
    cm.removeOverlay(CodeMirrorOverlays.headingFormatOverlay);
  }
}

function createKeywordElement(keyword: string): HTMLElement {
  const element = document.createElement("span");
  element.classList.add(TaskCSSClass.KEYWORD);
  element.textContent = keyword;
  return element;
}

function createCheckboxElement(checked: boolean = false): HTMLElement {
  const element = document.createElement("input");
  element.type = "checkbox";
  element.checked = checked;
  return element;
}

export default class LogSeqPlugin extends Plugin {
  static removeProperties(content: string): string {
    return content
      .replace(/doing:: (?:\d{13})/, "")
      .replace(/done:: (?:\d{13})/, "")
      .replace(/todo:: (?:\d{13})/, "")
      .replace(/doing:: (?:\d{13})/, "")
      .replace(/later:: (?:\d{13})/, "")
      .replace(/canceled:: (?:\d{13})/, "")
      .replace(
        /id:: (?:[0-9A-F]{8}-[0-9A-F]{4}-4[0-9A-F]{3}-[89AB][0-9A-F]{3}-[0-9A-F]{12})/i,
        ""
      )
      .replace(/collapsed:: (?:true|false)/gms, "");
  }

  static processChildren(el: Element, keyword: string) {
    el.childNodes.forEach((child) => {
      if (child.nodeType == Node.TEXT_NODE) {
        if (child.nodeValue.startsWith(keyword)) {
          child.nodeValue = child.nodeValue.replace(keyword, "");
        }
        child.nodeValue = LogSeqPlugin.removeProperties(child.nodeValue);
      }
    });
  }

  static styleNode(el: Element, classname: TaskCSSClass) {
    el.querySelectorAll("li[data-line]").forEach((child) => {
      // Do not "complete" the child tasks, since this is LogSeq's behaviour
      child.classList.add(TaskCSSClass.INCOMPLETE);
    });
    el.classList.add(classname);
  }

  static postprocessor: MarkdownPostProcessor = (
    el: HTMLElement,
    ctx: MarkdownPostProcessorContext
  ) => {
    const entries = el.querySelectorAll("li[data-line]");

    entries.forEach((entry) => {
      // Check if the entry is a org-mode block
      if (LogSeqRegExes.isBlock(entry.innerHTML)) {
        let replacedBlock = entry.innerHTML.replace(
          LogSeqRegExes.BEGIN_BLOCK_REGEX,
          "<blockquote> &#9759;"
        );
        replacedBlock = replacedBlock.replace(
          LogSeqRegExes.END_BLOCK_REGEX,
          "</blockquote>"
        );
        entry.innerHTML = replacedBlock;
      }
      const taskType = LogSeqRegExes.parseTaskType(entry.textContent);

      if (taskType == TaskType.DONE) {
        LogSeqPlugin.processChildren(entry, TaskType.DONE);

        entry.insertAdjacentElement("afterbegin", createCheckboxElement(true));
        LogSeqPlugin.styleNode(entry, TaskCSSClass.COMPLETE);
      } else if (taskType == TaskType.TODO) {
        LogSeqPlugin.processChildren(entry, TaskType.TODO);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.TODO)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
        LogSeqPlugin.styleNode(entry, TaskCSSClass.INCOMPLETE);
      } else if (taskType == TaskType.DOING) {
        LogSeqPlugin.processChildren(entry, TaskType.DOING);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.DOING)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
      } else if (taskType == TaskType.LATER) {
        LogSeqPlugin.processChildren(entry, TaskType.LATER);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.LATER)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
        LogSeqPlugin.styleNode(entry, TaskCSSClass.INCOMPLETE);
      } else if (taskType == TaskType.CANCELED) {
        LogSeqPlugin.processChildren(entry, TaskType.CANCELED);
        LogSeqPlugin.styleNode(entry, TaskCSSClass.COMPLETE);
      }
    });
  };

  onload() {
    console.log(`Loading logseq-compat plugin ${VERSION}`);
    this.registerMarkdownPostProcessor(LogSeqPlugin.postprocessor);
    // Style headings in source editing
    this.registerCodeMirror(CodeMirrorOverlays.cmAddHeadingOverlay);
  }

  onunload() {
    console.log(`unloading logseq-compat plugin ${VERSION}`);
    this.registerCodeMirror(CodeMirrorOverlays.cmRemoveHeadingOverlay);
  }
}

import {
  SelectorToken,
  DeclarationToken,
  DeclarationsBlockEndToken,
  CombinatorToken,
  SubSelectorToken,
}  from './tokens';

// 以下是字符判断的正则, 暂时认为只有ASCII码
const isWhiteSpaceReg = /[\t \f\n]/; // 是否是空格
const isWordStartLetterReg = /[_a-zA-Z]/; // 是否一个词的开始
const isWordLetterReg = /[_\-0-9a-zA-Z]/; // 是否一个词(多了-)

const isSeletorStartLetterReg = isWordStartLetterReg; // 标签名字开始
const isSeletorLetterReg = isWordLetterReg; // 标签名字

export default class CSSLexicalParser {
  state: Function;
  initState: Function;
  receiveInput(char) {
    this.state = this.state(char);
  }
  reset() {
    this.state = this.initState;
  }
  constructor(syntaxer) {
    this.initState = beforeSelector;
    this.reset();

    let token: any = null;

    function emitToken() {
      if (!token) {
        throw new Error('token is null');
      }
      syntaxer.receiveInput(token);
      token = null;
    }

    function emitDeclarationsBlockEndToken() {
      token = new DeclarationsBlockEndToken();
      emitToken();
    }

    function emitCombinatorToken(value) {
      token = new CombinatorToken();
      token.value = value;
      emitToken();
    }

    function error(c) {
      throw new Error(`unexpected char '${c}'`);
    }

    function beforeSelector(char) {
      if (/[.#]/.test(char)) {
        token = new SelectorToken();
        token.value = char;
        return selectorStart;
      }

      if (isSeletorStartLetterReg.test(char)) {
        token = new SelectorToken();
        token.value = char;
        return selector;
      }

      if (isWhiteSpaceReg.test(char)) {
        return beforeSelector;
      }
      error(char);
    }
    function selectorStart(char) {
      if (isSeletorStartLetterReg.test(char)) {
        token.value += char;
        return selector;
      }
      error(char);
    }
    function selector(char) {
      if (/[,>+~]/.test(char)) {
        emitToken();
        emitCombinatorToken(char);
        return beforeSelector;
      }
      if (/[#.]/.test(char)) {
        emitToken();
        token = new SubSelectorToken();
        token.value = char;
        return selectorStart;
      }
      if (isWhiteSpaceReg.test(char)) {
        emitToken();
        return whiteSpaceAfterSelector;
      }
      if (char === '{') {
        emitToken();
        return beforeDeclaration;
      }
      if (isSeletorLetterReg.test(char)) {
        token.value += char;
        return selector;
      }
      error(char);
    }

    function whiteSpaceAfterSelector(char) {
      if (isWhiteSpaceReg.test(char)) {
        return whiteSpaceAfterSelector;
      }
      if (/[,>+~]/.test(char)) {
        emitCombinatorToken(char);
        return beforeSelector;
      }
      if (char === '{') {
        return beforeDeclaration;
      }
      emitCombinatorToken(' ');
      return beforeSelector(char);
    }

    function beforeDeclaration(char) {
      if (isWhiteSpaceReg.test(char)) {
        return beforeDeclaration;
      }
      if (char === '}') {
        emitDeclarationsBlockEndToken();
        return beforeSelector;
      }
      token = new DeclarationToken();
      token.property = char;
      return declarationProperty;
    }

    function declarationProperty(char) {
      if (isWhiteSpaceReg.test(char)) {
        error(char);
      }
      if (char === ':') {
        return beforeDeclarationValue;
      }
      token.property += char;
      return declarationProperty;
    }
    function beforeDeclarationValue(char) {
      if (isWhiteSpaceReg.test(char)) {
        return beforeDeclarationValue;
      }
      token.value += char;
      return declarationValue;
    }
    function declarationValue(char) {
      if (char === ';') {
        emitToken();
        return beforeDeclaration;
      }
      if (char === '}') {
        emitToken();
        emitDeclarationsBlockEndToken();
        return beforeSelector;
      }
      token.value += char;
      return declarationValue;
    }

  }
}

import { BigInt, log } from "@graphprotocol/graph-ts"
import {
  AddressUpdate,
  OwnerUpdate as ContractRegistryOwnerUpdate
} from "../../generated/ContractRegistryContract/ContractRegistryContract"
import {
    BancorContract,
    ConverterRegistry,
    ContractRegistry
  } from "../../generated/schema"

  // Contract Registry events
export function handleAddressUpdate(event: AddressUpdate): void {
    let contractRegistryEntity = new ContractRegistry(event.address.toHex());
    let contractName = event.params._contractName.toString();
    let contractAddress = event.params._contractAddress.toHex();
    log.debug("Contract registry address updated at block# {}: {} is now at {}", [event.block.number.toString(), contractName, contractAddress]);
    if(contractName == "BancorConverterRegistry") {
      let converterRegistries = contractRegistryEntity.converterRegistries || [];
      let converterRegistryEntity = ConverterRegistry.load(contractAddress)
      if (converterRegistryEntity == null) {
        converterRegistryEntity = new ConverterRegistry(contractAddress);
        converterRegistryEntity.addedToContractRegistryAtBlockTimestamp = event.block.timestamp;
        converterRegistryEntity.addedToContractRegistryAtBlockNumber = event.block.number;
        converterRegistryEntity.addedToContractRegistryAtTransactionHash = event.transaction.hash.toHex();
      }
      converterRegistries.push(event.params._contractAddress.toHex());
      contractRegistryEntity.converterRegistries = converterRegistries;
      converterRegistryEntity.save();
      contractRegistryEntity.save();
    }
    let bancorContractEntity = new BancorContract(contractAddress);
    bancorContractEntity.name = contractName;
    bancorContractEntity.registry = event.address.toHex();
    bancorContractEntity.save();
  }

  export function handleContractRegistryOwnerUpdate(event: ContractRegistryOwnerUpdate): void {
    let contractRegistryEntity = new ContractRegistry(event.address.toHex());
    contractRegistryEntity.owner = event.params._newOwner.toHex();
    contractRegistryEntity.save();
  }

import { Request, Response, NextFunction } from "express";
import { cnpj as cnpjValidator } from "cpf-cnpj-validator";
import PetshopService from "@services/petshop.service";

// thanks copilot for the documentation, im lazy to write it myself

/**
 * Middleware to validate the petshop data in the request body.
 * 
 * This function checks if the name and CNPJ are provided and valid. It also checks if the petshop
 * already exists in the PetshopService. If any validation fails, it responds with an appropriate
 * error message. If all validations pass, it sets the petshop data in the request object and calls
 * the next middleware.
 */
export async function validatePetshopData(req: Request, res: Response, next: NextFunction) {
  const { name, cnpj } = req.body || {};

  if (!name) {
    res.status(400).json({ error: "Nome é obrigatório!" });
    return;
  }

  const trimmedName = name.trim();

  if (trimmedName.length < 2 || trimmedName.length > 255) {
    res.status(400).json({ error: "Nome deve conter entre 2 e 255 caracteres!" });
    return;
  }

  if (!cnpj) {
    res.status(400).json({ error: "CNPJ é obrigatório!" });
    return;
  }

  if (!cnpjValidator.isValid(cnpj)) {
    res.status(400).json({ error: "CNPJ inválido!" });
    return;
  }

  req.petshop = { name: trimmedName, cnpj };

  next();
}

/**
 * Middleware to validate the CNPJ passed as a header in the request.
 * 
 * This function checks if the CNPJ is provided in the request headers and if the petshop exists
 * in the PetshopService. If any validation fails, it responds with an appropriate error message.
 * If all validations pass, it sets the CNPJ in the request object and calls the next middleware.
 */
export async function checkExistUsserAccount(req: Request, res: Response, next: NextFunction) {
  const cnpjHeader = req.headers['cnpj'] as string;

  if (!cnpjHeader) {
    res.status(400).json({ error: "CNPJ é obrigatório!" });
    return;
  }

  if (!await PetshopService.hasPetshop(cnpjHeader)) {
    res.status(404).json({ error: "Petshop não cadastrado!" });
    return;
  }

  req.cnpj = cnpjHeader;
  next();
}

/**
 * Middleware to validate the existence of a pet.
 * 
 * This function checks if a pet exists in the PetshopService based on the provided
 * CNPJ and pet ID from the request parameters. If the pet is not found, it responds
 * with a 404 status and an error message. If the pet is found, it sets the pet index
 * in the request object and calls the next middleware.
 */
export async function validatePetExistence(req: Request, res: Response, next: NextFunction) {
  const pet = await PetshopService.getPetObject(req.params.id);
  if (!pet) {
    res.status(404).json({ error: "Pet não encontrado!" });
    return;
  }
  req.petId = pet.id;
  next();
}

/**
 * Middleware to validate the pet data in the request body.
 * 
 * This function checks if the name, type, and vaccination date are provided and valid.
 * If any validation fails, it responds with an appropriate error message. If all validations
 * pass, it sets the pet data in the request object and calls the next middleware.
 */
export function validatePetData(req: Request, res: Response, next: NextFunction) {
  let { name, description, type, deadline_vaccination } = req.body || {};

  const trimmedName = name.trim();

  if (!trimmedName) {
    res.status(400).json({ error: "Nome é obrigatório!" });
    return;
  }

  const trimmedType = type.trim();

  if (!trimmedType) {
    res.status(400).json({ error: "Tipo é obrigatório!" });
    return;
  }

  // Verifica se a data de vacinação está no formato correto e se é uma data válida
  const parsedVaccinationDate = new Date(deadline_vaccination);
  if (isNaN(parsedVaccinationDate.getTime())) {
    res.status(400).json({ error: "Data de vacinação inválida!" });
    return;
  }

  req.pet = { name: trimmedName, description, type: trimmedType, deadline_vaccination: parsedVaccinationDate };

  next();
}

