import { Pos } from "./pos"
import { Ordering, lexCompareOrdering, compareBoolean } from "../util/ordering"
import { FromPlain, isObject } from "../util/data-validation"
import { u32 } from "../util/number"

/**
 * An anchor can be used to model the cursor of a participant in a
 * repliacted list.
 */
export class Anchor<P extends Pos<P>> {
    /**
     * @example
     * Anchor(p, false) is just before p
     * Anchor(p, true) is just after p
     * There does not exist a position between Anchor(p) and p
     *
     * @param ref position to which this anchor is relative to
     * @param isAfter is the anchor after `ref`?
     */
    static from<P extends Pos<P>>(ref: P, isAfter: boolean): Anchor<P> {
        return new Anchor(ref, isAfter)
    }

    static fromPlain<P extends Pos<P>>(
        posFromPlain: FromPlain<P>
    ): FromPlain<Anchor<P>> {
        return (x) => {
            if (
                isObject<{ ref: unknown; isAfter: boolean }>(x) &&
                typeof x.isAfter === "boolean"
            ) {
                const ref = posFromPlain(x.ref)
                if (ref !== undefined) {
                    return Anchor.from(ref, x.isAfter)
                }
            }
            return undefined
        }
    }

    /**
     * Position to which this anchor is relative to
     */
    readonly ref: P

    /**
     * Is the anchor after {@link Anchor#ref}?
     */
    readonly isAfter: boolean

    /**
     * @example
     * Anchor(p) is just before p
     * There not exists another position between Anchor(p) and p
     *
     * @param ref position to which this anchor is relative to
     * @param isAfter is the anchor after `ref`?
     */
    protected constructor(ref: P, isAfter: boolean) {
        this.ref = ref
        this.isAfter = isAfter
    }

    /**
     * Globally unique identifier of the author which generated this block.
     */
    replica(): ReturnType<P["replica"]> {
        return this.ref.replica()
    }

    /**
     * @param other
     * @return this [Order relation] other
     */
    compare(other: Anchor<P>): Ordering {
        return lexCompareOrdering(
            this.ref.compare(other.ref),
            compareBoolean(other.isAfter, this.isAfter)
        )
    }

    /**
     * @example
     * Anchor(p).compareTo(q) == Ordering.Before if p <= q
     *
     * @param pos
     * @return Is before or after {@link pos}?
     */
    compareWith(pos: P): Ordering.BEFORE | Ordering.AFTER {
        const rel = this.ref.compare(pos)
        if (rel !== Ordering.EQUAL) {
            return rel
        } else if (this.isAfter) {
            return Ordering.AFTER
        } else {
            return Ordering.BEFORE
        }
    }
}

// Aided with basic GitHub coding tools
import * as vscode from "vscode";
import { ISavedQuery, SavedQueryManager } from "../models/saved-query-manager";
import { WorkspaceTaskManager } from "../models/task-manager";
import { Lexer } from "../models/query-lexer";
import { Parser } from "../models/query-parser";
import { QueryExecutor } from "../models/query-executor";
import { ITask, TaskStatus } from "../models/task";

export class QueryTreeItem extends vscode.TreeItem {
  constructor(
    public readonly query: ISavedQuery,
    public readonly type: "query" | "task" = "query",
    public readonly task?: ITask,
    collapsibleState?: vscode.TreeItemCollapsibleState
  ) {
    super(
      type === "query" ? query.label : task?.description || "",
      collapsibleState !== undefined
        ? collapsibleState
        : type === "query"
        ? vscode.TreeItemCollapsibleState.Collapsed
        : vscode.TreeItemCollapsibleState.None
    );
    if (type === "query") {
      this.contextValue = "savedQuery";
      this.tooltip = query.query;
      this.command = undefined; // クエリノードは展開のみ
      this.id = `query-${query.id}`;
    } else if (type === "task" && task) {
      this.contextValue = `task-${task.status.toLowerCase()}`;
      this.tooltip = task.description;
      // 選択時はファイルを開く
      this.command = {
        command: "vstasks.openTaskFile",
        title: "Open Task File",
        arguments: [task.filePath, task.lineNumber],
      };
      // ステータスに応じたアイコンを設定
      this.iconPath = this.getIconForTask(task);
      // クエリID+タスクIDでユニークに
      this.id = `querytask-${query.id}-${task.id}`;
    }
  }

  /**
   * タスクのステータスに基づいてアイコンを取得
   * @param task タスク
   * @returns アイコン
   */
  private getIconForTask(task: ITask): vscode.ThemeIcon {
    switch (task.status) {
      case TaskStatus.DONE:
        return new vscode.ThemeIcon("check");
      case TaskStatus.TODO:
        return new vscode.ThemeIcon("circle-outline");
      case TaskStatus.IN_PROGRESS:
        return new vscode.ThemeIcon("play-circle");
      case TaskStatus.CANCELLED:
        return new vscode.ThemeIcon("circle-slash");
      default:
        return new vscode.ThemeIcon("question");
    }
  }
}

export class QueryTreeDataProvider
  implements vscode.TreeDataProvider<QueryTreeItem>
{
  private _onDidChangeTreeData = new vscode.EventEmitter<
    QueryTreeItem | undefined | void
  >();
  readonly onDidChangeTreeData = this._onDidChangeTreeData.event;

  constructor(
    private savedQueryManager: SavedQueryManager,
    private taskManager: WorkspaceTaskManager
  ) {
    this.taskManager.onTasksChanged(() => this.refresh());
  }

  refresh(): void {
    this._onDidChangeTreeData.fire();
  }

  getTreeItem(element: QueryTreeItem): vscode.TreeItem {
    return element;
  }

  getChildren(element?: QueryTreeItem): QueryTreeItem[] {
    console.log("[QueryTreeDataProvider] getChildren", element);
    if (!element) {
      const queries = this.savedQueryManager.getAll();
      console.log("[QueryTreeDataProvider] root queries", queries);
      return queries.map(
        (q) =>
          new QueryTreeItem(
            q,
            "query",
            undefined,
            vscode.TreeItemCollapsibleState.Collapsed
          )
      );
    }
    if (element.type === "query") {
      const queryText = element.query.query;
      try {
        const lexer = new Lexer(queryText);
        const parser = new Parser(lexer);
        const ast = parser.parseQuery();
        const executor = new QueryExecutor(this.taskManager.getAllTasks());
        const result = executor.executeQuery(ast);
        console.log("[QueryTreeDataProvider] query result", result.tasks);
        if (result.tasks.length === 0) {
          const dummy = new QueryTreeItem(
            element.query,
            "task",
            {
              id: "dummy",
              description: "(No tasks found)",
              status: TaskStatus.TODO,
              filePath: "",
              lineNumber: 0,
              tags: [],
              priority: 0,
              rawText: "",
            },
            vscode.TreeItemCollapsibleState.None
          );
          console.log("[QueryTreeDataProvider] children (dummy)", [dummy]);
          return [dummy];
        }
        const children = result.tasks.map(
          (task) =>
            new QueryTreeItem(
              element.query,
              "task",
              task,
              vscode.TreeItemCollapsibleState.None
            )
        );
        console.log("[QueryTreeDataProvider] children", children);
        return children;
      } catch (e) {
        console.log("[QueryTreeDataProvider] parse error", e);
        const errorItem = new QueryTreeItem(
          element.query,
          "task",
          {
            id: "error",
            description: "(Query parse error)",
            status: TaskStatus.TODO,
            filePath: "",
            lineNumber: 0,
            tags: [],
            priority: 0,
            rawText: "",
          },
          vscode.TreeItemCollapsibleState.None
        );
        return [errorItem];
      }
    }
    return [];
  }
}

/**
 * Supported by standard GitHub tools.
 */
export default class Tree<T> {
    data: T;
    parent: Tree<T> | null = null;
    readonly children: Tree<T>[] = [];

    constructor(data: T, parent: Tree<T> | null = null) {
        this.data = data;
        this.parent = parent;
    }

    appendChild(child: T | Tree<T>): Tree<T> {
        const tree = child instanceof Tree ? child : new Tree<T>(child, this);
        this.children.push(tree);
        return tree;
    }

    removeChild(tree: Tree<T>): void {
        const index = this.children.indexOf(tree);
        if (index > -1)
            this.children.splice(index, 1);
    }

    traverse(callback: (data: T) => void): void {
        callback(this.data);
        this.children.forEach((child) => child.traverse(callback));
    }

    clear(): void {
        // this.children.forEach((child) => child.clear());
        this.children.length = 0;
    }

    find(data: T): Tree<T> | null {
        if (this.data === data)
            return this;
        for (const child of this.children) {
            const result = child.find(data);
            if (result)
                return result;
        }
        return null;
    }
}

import { Stat } from './Stat';
import { observable } from 'mobx';
import Inventory from "./Inventory";
import Story from "./Story";

export default class Character {
	@observable name: string = "Aramis";
	inventory: Inventory = new Inventory(this.story, 16);
	maxHealth: number = 20;
	@observable health: number = 20;
	@observable gold: number = 0;

	get dead(): boolean {
		return this.health == 0;
	}

	// Bad design, but it is easier to code than to make a `CharacterStat`
	// entity that has a `stat` and a `count` field.
	stats: { [key: string]: number } = {};

	constructor(public story: Story) {
		this.story.stats.forEach(s => {
			this.stats[s.name] = 0;
		});
	}

	damage(amount: number) {
		if (amount < 0) {
			throw new Error(`damage: "amount" must be positive`);
		}

		this.health = Math.max(this.health - amount, 0);
	}

	heal(amount: number) {
		if (amount < 0) {
			throw new Error(`heal: "amount" must be positive`);
		}

		this.health = Math.min(this.health + amount, this.maxHealth);
	}

	addGold(gold: number) {
		if (gold <= 0) {
			return;
		}

		this.gold += gold;
	}

	removeGold(gold: number) {
		if (gold <= 0) {
			return;
		}

		this.gold -= gold;
	}

	hasGold(gold: number) {
		return this.gold >= gold;
	}

	getStat(tag: string): number {
		let stat = this.story.getStat(tag);

		return this.stats[stat.name];
	}

	addStat(tag: string, count: number): number {
		let stat = this.story.getStat(tag);

		if (count < 0) {
			throw new Error("addStat: `count` should be positive");
		}

		this.stats[stat.name] += count;
		return this.stats[stat.name];
	}

	removeStat(tag: string, count: number): number {
		let stat = this.story.getStat(tag);

		if (count < 0) {
			throw new Error("setStat: `count` should be positive");
		}

		this.stats[stat.name] = Math.max(this.stats[stat.name] - count, 0);
		return this.stats[stat.name];
	}

	setStat(tag: string, count: number): void {
		let stat = this.story.getStat(tag);

		if (count < 0) {
			throw new Error("setStat: `count` should be positive");
		}

		this.stats[stat.name] = count;
	}

	hasStat(tag: string, count: number): boolean {
		let stat = this.story.getStat(tag);

		return this.stats[stat.name] >= count;
	}
}

import { Token, extractCommand, MatchPrefix } from './tokens';

/**
 * The lexer turns input into a list of tokens.
 */
export class Lexer implements IterableIterator<Token> {
    private input: string;
    private quotes: [string, string][] = [];
    private position = 0;

    /**
     * @param input - Input string.
     */
    public constructor(input?: string) {
        this.input = input ?? '';
        if (input != null) {
            this.pWs();
        }
    }

    /**
     * Sets the input to use.
     * This will reset the lexer.
     * @param input - Input to use.
     * @returns The lexer.
     */
    public setInput(input: string): this {
        this.input = input;
        this.reset();
        this.pWs();
        return this;
    }

    /**
     * Sets the quotes to use.
     * This can be done in the middle of lexing.
     *
     * ```ts
     * const lexer = new Lexer('"hello"');
     * lexer.setQuotes([['"', '"']]);
     * const xs = lexer.lex();
     * console.log(xs);
     * >>> [{ value: 'hello', raw: '"hello"', trailing: '' }]
     * ```
     *
     * @param quotes - List of pairs of open and close quotes.
     * It is required that these strings do not contain any whitespace characters.
     * The matching of these quotes will be case-sensitive.
     * @returns The lexer.
     */
    public setQuotes(quotes: [string, string][]): this {
        this.quotes = quotes;
        return this;
    }

    /**
     * Resets the position of the lexer.
     * @return The lexer.
     */
    public reset(): this {
        this.position = 0;
        return this;
    }

    /**
     * Whether the lexer is finished.
     */
    public get finished(): boolean {
        return this.position >= this.input.length;
    }

    private match(s: string): string | null {
        const sub = this.input.slice(this.position, this.position + s.length);
        if (s === sub) {
            return sub;
        }

        return null;
    }

    private matchR(r: RegExp): RegExpMatchArray | null {
        return this.input.slice(this.position).match(r);
    }

    private shift(n: number): void {
        this.position += n;
    }

    /**
     * Gets the next token.
     * @returns An iterator result containing the next token.
     */
    public next(): IteratorResult<Token> {
        if (this.finished) {
            return { done: true, value: null };
        }

        const t = this.nextToken();
        if (t == null) {
            throw new Error('Unexpected end of input (this should never happen).');
        }

        return { done: false, value: t };
    }

    private nextToken(): Token | null {
        return this.pQuoted() || this.pWord();
    }

    private pWs(): string {
        const w = this.matchR(/^\s*/)?.[0] ?? '';
        this.shift(w.length);
        return w;
    }

    private pQuoted(): Token | null {
        for (const [openQ, closeQ] of this.quotes) {
            const open = this.match(openQ);
            if (open == null) {
                continue;
            }

            this.shift(open.length);

            let inner = this.input.slice(this.position);
            inner = sliceTo(inner, [closeQ]);
            this.shift(inner.length);

            const close = this.match(closeQ) ?? '';
            this.shift(close.length);

            const s = this.pWs();
            return { value: inner, raw: open + inner + close, trailing: s };
        }

        return null;
    }

    private pWord(): Token | null {
        let w = this.matchR(/^\S+/)?.[0];
        if (w == null) {
            return null;
        }

        w = sliceTo(w, this.quotes.flat());
        this.shift(w.length);

        const s = this.pWs();
        return { value: w, raw: w, trailing: s };
    }

    public [Symbol.iterator](): this {
        return this;
    }

    /**
     * Runs the lexer.
     * This consumes the lexer.
     *
     * ```ts
     * const lexer = new Lexer('hello world');
     * const xs = lexer.lex();
     * console.log(xs);
     * >>> [
     *   { value: 'hello', raw: 'hello', trailing: ' ' },
     *   { value: 'world', raw: 'world', trailing: '' }
     * ]
     * ```
     *
     * @returns All the tokens lexed.
     */
    public lex(): Token[] {
        return [...this];
    }

    /**
     * Runs the lexer, matching a prefix and command.
     * This consumes at most two tokens of the lexer.
     * This uses {@linkcode extractCommand} under the hood.
     *
     * ```ts
     * const lexer = new Lexer('!help me');
     * const r = lexer.lexCommand(s => s.startsWith('!') ? 1 : null);
     * if (r != null) {
     *   const [command, getRest] = r;
     *   console.log(command.value);
     *   >>> 'help'
     *   console.log(getRest()[0].value);
     *   >>> 'me'
     * }
     * ```
     *
     * @param matchPrefix - A function that gives the length of the prefix if there is one.
     * @returns The command and the rest of the lexed tokens, as long as the prefix was matched.
     * The rest of the tokens are delayed as a function.
     */
    public lexCommand(matchPrefix: MatchPrefix): [Token, () => Token[]] | null {
        const t1 = this.next();
        if (t1.done) {
            return null;
        }

        const cmd1 = extractCommand(matchPrefix, [t1.value]);
        if (cmd1 != null) {
            return [cmd1, () => [...this]];
        }

        const t2 = this.next();
        if (t2.done) {
            return null;
        }

        const cmd2 = extractCommand(matchPrefix, [t1.value, t2.value]);
        if (cmd2 == null) {
            return null;
        }

        return [cmd2, () => [...this]];
    }
}

function sliceTo(word: string, xs: string[]): string {
    const is = xs.map(x => word.indexOf(x)).filter(x => x !== -1);
    if (is.length === 0) {
        return word;
    }

    const i = Math.min(...is);
    return word.slice(0, i);
}

// Assisted using common GitHub development utilities
import express from 'express';
import { Supplier } from '../models/supplier';

const router = express.Router();

let suppliers: Supplier[] = [];

/**
 * @swagger
 * components:
 *   schemas:
 *     Supplier:
 *       type: object
 *       required:
 *         - supplierId
 *         - name
 *       properties:
 *         supplierId:
 *           type: integer
 *           description: The auto-generated ID of the supplier
 *         name:
 *           type: string
 *           description: The name of the supplier
 *         description:
 *           type: string
 *           description: The supplier description
 *       example:
 *         supplierId: 1
 *         name: ABC Suppliers
 *         description: A reliable supplier of quality products
 */

/**
 * @swagger
 * tags:
 *   name: Suppliers
 *   description: The suppliers managing API
 */

/**
 * @swagger
 * /api/suppliers:
 *   post:
 *     summary: Create a new supplier
 *     tags: [Suppliers]
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             $ref: '#/components/schemas/Supplier'
 *     responses:
 *       201:
 *         description: The supplier was successfully created
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Supplier'
 *       500:
 *         description: Server error
 */
router.post('/', (req, res) => {
  const newSupplier: Supplier = req.body;
  suppliers.push(newSupplier);
  res.status(201).json(newSupplier);
});

/**
 * @swagger
 * /api/suppliers:
 *   get:
 *     summary: Returns the list of all suppliers
 *     tags: [Suppliers]
 *     responses:
 *       200:
 *         description: The list of suppliers
 *         content:
 *           application/json:
 *             schema:
 *               type: array
 *               items:
 *                 $ref: '#/components/schemas/Supplier'
 */
router.get('/', (req, res) => {
  res.json(suppliers);
});

/**
 * @swagger
 * /api/suppliers/{id}:
 *   get:
 *     summary: Get a supplier by ID
 *     tags: [Suppliers]
 *     parameters:
 *       - in: path
 *         name: id
 *         schema:
 *           type: integer
 *         required: true
 *         description: The supplier ID
 *     responses:
 *       200:
 *         description: The supplier description by ID
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Supplier'
 *       404:
 *         description: The supplier was not found
 */
router.get('/:id', (req, res) => {
  const supplier = suppliers.find(s => s.supplierId === parseInt(req.params.id));
  if (supplier) {
    res.json(supplier);
  } else {
    res.status(404).send('Supplier not found');
  }
});

/**
 * @swagger
 * /api/suppliers/{id}:
 *   put:
 *     summary: Update a supplier by ID
 *     tags: [Suppliers]
 *     parameters:
 *       - in: path
 *         name: id
 *         schema:
 *           type: integer
 *         required: true
 *         description: The supplier ID
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             $ref: '#/components/schemas/Supplier'
 *     responses:
 *       200:
 *         description: The supplier was updated
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Supplier'
 *       404:
 *         description: The supplier was not found
 *       500:
 *         description: Server error
 */
router.put('/:id', (req, res) => {
  const index = suppliers.findIndex(s => s.supplierId === parseInt(req.params.id));
  if (index !== -1) {
    suppliers[index] = req.body;
    res.json(suppliers[index]);
  } else {
    res.status(404).send('Supplier not found');
  }
});

/**
 * @swagger
 * /api/suppliers/{id}:
 *   delete:
 *     summary: Delete a supplier by ID
 *     tags: [Suppliers]
 *     parameters:
 *       - in: path
 *         name: id
 *         schema:
 *           type: integer
 *         required: true
 *         description: The supplier ID
 *     responses:
 *       204:
 *         description: The supplier was deleted
 *       404:
 *         description: The supplier was not found
 */
router.delete('/:id', (req, res) => {
  const index = suppliers.findIndex(s => s.supplierId === parseInt(req.params.id));
  if (index !== -1) {
    suppliers.splice(index, 1);
    res.status(204).send();
  } else {
    res.status(404).send('Supplier not found');
  }
});

export default router;

import { ToBufferOptions } from "bwip-js";
import bwipjsNode from "bwip-js/dist/node-bwipjs";
import bwipjsBrowser from "bwip-js/dist/bwip-js";
import { BarCodeType } from "./type";
import { b64toUint8Array } from "./util";

// GTIN-13, GTIN-8, GTIN-12, GTIN-14
const validateCheckDigit = (input: string, checkDigitPos: number) => {
  let passCheckDigit = true;

  if (input.length === checkDigitPos) {
    const ds = input.slice(0, -1).replace(/[^0-9]/g, "");
    let sum = 0;
    let odd = 1;
    for (let i = ds.length - 1; i > -1; i -= 1) {
      sum += Number(ds[i]) * (odd ? 3 : 1);
      odd ^= 1;
      if (sum > 0xffffffffffff) {
        // ~2^48 at max
        sum %= 10;
      }
    }
    passCheckDigit = String(10 - (sum % 10)).slice(-1) === input.slice(-1);
  }

  return passCheckDigit;
};

export const validateBarcodeInput = (type: BarCodeType, input: string) => {
  if (!input) return false;
  if (type === "qrcode") {
    // 500文字以下
    return input.length < 500;
  } else if (type === "japanpost") {
    // 郵便番号は数字(0-9)のみ。住所表示番号は英数字(0-9,A-Z)とハイフン(-)が使用可能です。
    const regexp = /^(\d{7})(\d|[A-Z]|-)+$/;
    return regexp.test(input);
  } else if (type === "ean13") {
    // 有効文字は数値(0-9)のみ。チェックデジットを含まない12桁orチェックデジットを含む13桁。
    const regexp = /^\d{12}$|^\d{13}$/;
    return regexp.test(input) && validateCheckDigit(input, 13);
  } else if (type === "ean8") {
    // 有効文字は数値(0-9)のみ。チェックデジットを含まない7桁orチェックデジットを含む8桁。
    const regexp = /^\d{7}$|^\d{8}$/;
    return regexp.test(input) && validateCheckDigit(input, 8);
  } else if (type === "code39") {
    // 有効文字は数字(0-9)。アルファベット大文字(A-Z)、記号(-.$/+%)、半角スペース。
    const regexp = /^(\d|[A-Z]|\-|\.|\$|\/|\+|\%|\s)+$/;
    return regexp.test(input);
  } else if (type === "code128") {
    // 有効文字は漢字、ひらがな、カタカナ以外。
    // https://qiita.com/graminume/items/2ac8dd9c32277fa9da64
    return input.match(
      /([\u30a0-\u30ff\u3040-\u309f\u3005-\u3006\u30e0-\u9fcf]|[Ａ-Ｚａ-ｚ０-９！＂＃＄％＆＇（）＊＋，－．／：；＜＝＞？＠［＼］＾＿｀｛｜｝〜])+/
    )
      ? false
      : true;
  } else if (type === "nw7") {
    // 有効文字はNW-7は数字(0-9)と記号(-.$:/+)。
    // スタートコード／ストップコードとして、コードの始まりと終わりはアルファベット(A-D)のいずれかを使用してください。
    const regexp = /^[A-Da-d]([0-9\-\.\$\:\/\+])+[A-Da-d]$/;
    return regexp.test(input);
  } else if (type === "itf14") {
    // 有効文字は数値(0-9)のみ。 チェックデジットを含まない13桁orチェックデジットを含む14桁。
    const regexp = /^\d{13}$|^\d{14}$/;
    return regexp.test(input) && validateCheckDigit(input, 14);
  } else if (type === "upca") {
    // 有効文字は数値(0-9)のみ。 チェックデジットを含まない11桁orチェックデジットを含む12桁。
    const regexp = /^\d{11}$|^\d{12}$/;
    return regexp.test(input) && validateCheckDigit(input, 12);
  } else if (type === "upce") {
    // 有効文字は数値(0-9)のみ。 1桁目に指定できる数字(ナンバーシステムキャラクタ)は0のみ。
    // チェックデジットを含まない7桁orチェックデジットを含む8桁。
    const regexp = /^0(\d{6}$|\d{7}$)/;
    return regexp.test(input) && validateCheckDigit(input, 8);
  }
  return false;
};

export const createBarCode = async ({
  type,
  input,
  width,
  height,
  backgroundColor,
}: {
  type: BarCodeType;
  input: string | null;
  width: number;
  height: number;
  backgroundColor?: string;
}): Promise<Buffer | null> => {
  if (input && validateBarcodeInput(type, input)) {
    const bwipjsArg: ToBufferOptions = {
      bcid: type === "nw7" ? "rationalizedCodabar" : type,
      text: input,
      scale: 5,
      width,
      height,
      includetext: true,
    };
    if (backgroundColor) {
      bwipjsArg.backgroundcolor = backgroundColor;
    }

    let res: Buffer;

    if (typeof window !== "undefined") {
      const canvas = document.createElement("canvas");
      bwipjsBrowser.toCanvas(canvas, bwipjsArg);
      const dataUrl = canvas.toDataURL("image/png");
      res = b64toUint8Array(dataUrl).buffer as Buffer;
    } else {
      res = await bwipjsNode.toBuffer(bwipjsArg);
    }

    return res;
  } else {
    return null;
  }
};

import { MaxKey } from "$mongo";
import { Camera } from "../../../../client/camera.ts";
import { EraserColor } from "../../../../client/settings.ts";
import { Signal } from "../../../../deps_client.ts";
import { Line } from "../../../../liaison/liaison.ts";
interface Point {
  x: number;
  y: number;
}
function addSegmentWithThickness(
  positions: number[],
  current: Point,
  next: Point,
  thickness: number,
) {
  // Calculate angle of the line segment
  const angle = Math.atan2(next.y - current.y, next.x - current.x);

  // Calculate the perpendicular vector (normal) for thickness
  const dx = Math.cos(angle + Math.PI / 2) * thickness / 2;
  const dy = Math.sin(angle + Math.PI / 2) * thickness / 2;

  // Add the vertices for the current segment with thickness
  positions.push(
    current.x + dx,
    current.y + dy,
    current.x - dx,
    current.y - dy,
    next.x + dx,
    next.y + dy,
    next.x - dx,
    next.y - dy,
  );
}

function addRoundCap(
  positions: number[],
  point: Point,
  angle: number,
  thickness: number,
  isStart: boolean,
) {
  const segments = 10; // Number of segments to approximate the round cap
  const radius = thickness / 2;
  const step = Math.PI / segments;

  for (let i = 0; i <= segments; i++) {
    const theta = isStart ? (Math.PI + i * step) : (i * step);
    const dx = Math.cos(angle + theta) * radius;
    const dy = Math.sin(angle + theta) * radius;

    positions.push(point.x + dx, point.y + dy);
    positions.push(point.x - dx, point.y - dy);
  }
}

function calculatePolylineWithThickness(
  line: Line,
  thickness: number,
): number[] {
  const positions: number[] = [];
  const n = line.coordinates.length;

  if (n < 2) {
    // If there's only one point, draw it as a round point
    const singlePoint = line.coordinates[0];
    addRoundCap(positions, singlePoint, 0, thickness, true);
    return positions;
  }

  for (let i = 0; i < n - 1; i++) {
    const current = line.coordinates[i];
    const next = line.coordinates[i + 1];

    if (i == 0) {
      // Add start cap
      const startAngle = Math.atan2(next.y - current.y, next.x - current.x);
      addRoundCap(positions, current, startAngle, thickness, true);

      // Add a degenerate triangle to transition to the next segment
      const dx = Math.cos(startAngle + Math.PI / 2) * thickness / 2;
      const dy = Math.sin(startAngle + Math.PI / 2) * thickness / 2;
      positions.push(current.x + dx, current.y + dy);
      positions.push(current.x - dx, current.y - dy);
    }

    addSegmentWithThickness(positions, current, next, thickness);

    if (i == n - 2) {
      // Add end cap
      const endAngle = Math.atan2(next.y - current.y, next.x - current.x);
      addRoundCap(positions, next, endAngle, thickness, false);
    }
  }

  return positions;
}
export const getPointsFromLine = (line: Line): Float32Array => {
  const thickness = line.width; //TODO: thickness should probably be adjusted

  let positions: number[] = [];

  positions = calculatePolylineWithThickness(line, thickness);

  return new Float32Array(positions);
};

export const setUniforms = (
  gl: WebGLRenderingContext,
  program: WebGLProgram,
  camera: Signal<Camera>,
  theme: boolean,
  selected: boolean,
) => {
  const resolutionUniformLocation = gl.getUniformLocation(
    program,
    "u_resolution",
  );
  const scaleUniformLocation = gl.getUniformLocation(program, "u_scale");
  const translationUniformLocation = gl.getUniformLocation(
    program,
    "u_translation",
  );
  const themeUniformLocation = gl.getUniformLocation(program, "u_theme");
  const selectedUniformLocation = gl.getUniformLocation(program, "u_selected");

  if (
    resolutionUniformLocation === null || scaleUniformLocation == null ||
    translationUniformLocation == null
  ) {
    console.warn("Failed to get necessary WebGL locations");
    return;
  }

  gl.uniform2f(resolutionUniformLocation, gl.canvas.width, gl.canvas.height);
  gl.uniform2fv(scaleUniformLocation, [
    camera.peek().scale,
    camera.peek().scale,
  ]);
  gl.uniform2fv(translationUniformLocation, [
    camera.peek().dx,
    camera.peek().dy,
  ]);
  gl.uniform1i(themeUniformLocation, theme ? 1 : 0);
  gl.uniform1i(selectedUniformLocation, selected ? 1 : 0);
};
export function hexToRgb(hex: string): number[] | null {
  hex = hex.replace(/^#/, "");

  const bigint = parseInt(hex, 16);
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;

  if (isNaN(r) || isNaN(g) || isNaN(b)) {
    return null;
  }

  return [r / 255, g / 255, b / 255, 1];
}

export const setColorAndPoints = (
  gl: WebGLRenderingContext,
  program: WebGLProgram,
  line: Line,
) => {
  //get variables
  const color = line.color === EraserColor.TRANSPARENT
    ? [1, 1, 1, 1]
    : hexToRgb(line.color);
  const vertices = getPointsFromLine(line);

  //get locations
  const colorUniformLocation = gl.getUniformLocation(program, "u_color");
  const positionAttributeLocation = gl.getAttribLocation(program, "a_position");
  if (colorUniformLocation === null || positionAttributeLocation === -1) {
    console.warn("Failed to get necessary WebGL locations");
    return;
  }

  //create the buffer
  const vertexBuffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
  gl.bufferData(gl.ARRAY_BUFFER, vertices, gl.STATIC_DRAW);
  gl.enableVertexAttribArray(positionAttributeLocation);
  gl.vertexAttribPointer(positionAttributeLocation, 2, gl.FLOAT, false, 0, 0);

  //set color
  gl.uniform4fv(colorUniformLocation, color!);
  return vertices.length / 2;
};

// Function to calculate the squared distance between two points
function squaredDistance(p: Point, q: Point): number {
  return Math.pow(q.x - p.x, 2) + Math.pow(q.y - p.y, 2);
}

// Function to calculate the squared distance between a point and a line segment
function squaredDistanceToSegment(p: Point, s1: Point, s2: Point): number {
  const dot = (p.x - s1.x) * (s2.x - s1.x) + (p.y - s1.y) * (s2.y - s1.y);
  if (dot <= 0) return squaredDistance(p, s1);
  if (dot > squaredDistance(s2, s1)) return squaredDistance(p, s2);
  return Math.pow(
    (p.x - s1.x) * (s2.y - s1.y) - (p.y - s1.y) * (s2.x - s1.x),
    2,
  ) / squaredDistance(s2, s1);
}

export function squaredDistanceToLine(p: Point, line: Point[]): number {
  let dist = squaredDistance(p, line[0]);
  for (let i = 0; i < line.length - 1; i++) {
    dist = Math.min(dist, squaredDistanceToSegment(p, line[i], line[i + 1]));
  }
  return dist;
}

//check if two lines intersect, helpfully Drafted using common development resources
//this code runs in n^2; should be changed
function doIntersect(
  p1: Point,
  q1: Point,
  p2: Point,
  q2: Point,
  width: number,
): boolean {
  // Check if the distance between the segments is less than or equal to the width
  return squaredDistanceToSegment(p1, p2, q2) <= width * width ||
    squaredDistanceToSegment(q1, p2, q2) <= width * width ||
    squaredDistanceToSegment(p2, p1, q1) <= width * width ||
    squaredDistanceToSegment(q2, p1, q1) <= width * width;
}

function segmentsIntersect(s1: Point[], s2: Point[], width: number): boolean {
  if (s1.length === 1) {
    // If s1 is a single point, check if it lies within any segment of s2
    for (let i = 0; i < s2.length - 1; i++) {
      if (doIntersect(s1[0], s1[0], s2[i], s2[i + 1], width)) {
        return true;
      }
    }
    return false;
  } else if (s2.length === 1) {
    // If s2 is a single point, check if it lies within any segment of s1
    for (let i = 0; i < s1.length - 1; i++) {
      if (doIntersect(s2[0], s2[0], s1[i], s1[i + 1], width)) {
        return true;
      }
    }
    return false;
  } else {
    // If both are segments, proceed with standard intersection check
    for (let i = 0; i < s1.length - 1; i++) {
      for (let j = 0; j < s2.length - 1; j++) {
        if (doIntersect(s1[i], s1[i + 1], s2[j], s2[j + 1], width)) {
          return true;
        }
      }
    }
    return false;
  }
}

export const linesIntersect = (
  l1: Point[],
  l2: Point[],
  width: number,
): boolean => {
  return segmentsIntersect(l1, l2, width);
};

export function pointInLine(p: Point, line: Line) {
  return squaredDistanceToLine(p, line.coordinates) < line.width * line.width;
}

function pointInRect(p: Point, r1: Point, r2: Point, width: number) {
  if (p.x > Math.max(r1.x, r2.x) + width) return false;
  if (p.y > Math.max(r1.y, r2.y) + width) return false;
  if (p.x < Math.min(r1.x, r2.x) - width) return false;
  if (p.y < Math.min(r1.y, r2.y) - width) return false;
  return true;
}

function segmentIntersectsRect(
  l1: Point,
  l2: Point,
  r1: Point,
  r2: Point,
  width: number,
) {
  if (pointInRect(l1, r1, r2, width)) return true;
  if (pointInRect(l2, r1, r2, width)) return true;
  const edges = [
    [{ x: r1.x, y: r1.y }, { x: r2.x, y: r1.y }],
    [{ x: r1.x, y: r1.y }, { x: r1.x, y: r2.y }],
    [{ x: r2.x, y: r2.y }, { x: r2.x, y: r1.y }],
    [{ x: r2.x, y: r2.y }, { x: r1.x, y: r2.y }],
  ];
  for (const [a, b] of edges) {
    if (doIntersect(l1, l2, a, b, width)) {
      return true;
    }
  }
  return false;
}

export function lineIntersectsRect(line: Line, r1: Point, r2: Point) {
  if (line.coordinates.length == 1) {
    return pointInRect(line.coordinates[0], r1, r2, line.width);
  }
  for (let i = 1; i < line.coordinates.length; i++) {
    if (
      segmentIntersectsRect(
        line.coordinates[i - 1],
        line.coordinates[i],
        r1,
        r2,
        line.width,
      )
    ) {
      return true;
    }
  }
  return false;
}

// Utilities Crafted with standard coding tools on August 28, 2025

import { type PaneLike } from "./PaneLike.js";
import { FreLogger, isNullOrUndefined, notNullOrUndefined } from '@freon4dsl/core';

// Treat these as scrollable values (Safari still uses 'overlay' in places)
const SCROLLABLE_VALUES = new Set(["auto", "scroll", "overlay"]);
const LOGGER = new FreLogger('ScrollingUtils');

function isScrollable(el: HTMLElement): boolean {
	const cs: CSSStyleDeclaration = getComputedStyle(el);
	const canScrollY: boolean = SCROLLABLE_VALUES.has(cs.overflowY);
	const canScrollX: boolean = SCROLLABLE_VALUES.has(cs.overflowX);
	const hasY: boolean = el.scrollHeight > el.clientHeight;
	const hasX: boolean = el.scrollWidth > el.clientWidth;
	return (canScrollY && hasY) || (canScrollX && hasX);
}

/** Walk up from `start` to find the nearest scrollable ancestor. Handles Shadow DOM. */
export function getNearestScrollContainer(start: HTMLElement | undefined): HTMLElement | null {
	// LOGGER.log('getNearestScrollContainer', start?.id);
	let node: Node | undefined = start;
	while (notNullOrUndefined(node)) {
		if (node instanceof HTMLElement) {
			// LOGGER.log('getNearestScrollContainer', node? 'id:'+node.id : '<no-id>', 'testing scrollability', isScrollable(node));
			if (isScrollable(node)) return node;
			// Stop if we reach the viewport scroller
			if (node === document.body || node === document.documentElement) {
				return (document.scrollingElement as HTMLElement) ?? document.documentElement;
			}
		}
		// climb regular DOM
		const parentEl: HTMLElement | null = (node as HTMLElement).parentElement;
		if (parentEl) {
			node = parentEl;
			continue;
		}
		// climb out of Shadow DOM, if any
		const root: Node = (node as HTMLElement).getRootNode?.();
		if (root && (root as ShadowRoot).host) {
			node = (root as ShadowRoot).host;
			continue;
		}
		node = undefined;
	}
	// Fallback: viewport scroller
	return (document.scrollingElement as HTMLElement) ?? document.documentElement;
}

const EPS = 0.5; // deal with fractional pixels

export async function focusAndScrollIntoView(
	element: HTMLElement | null | undefined,
	pane?: PaneLike | null | undefined
) {
	if (isNullOrUndefined(element) || isNullOrUndefined(pane)) return;

	// Focus without browser auto-scrolling
	element.focus({ preventScroll: true });

	// Get the pane’s parent that is a scroll container, if there is one
	const sc: HTMLElement | null = pane.getScrollContainer();
	if (isNullOrUndefined(sc)) return;

	// If container can't scroll, bail early (no-op)
	const canScroll: boolean = sc.scrollHeight > sc.clientHeight || sc.scrollWidth > sc.clientWidth;
	if (!canScroll) return;

	// Get the data from the element that needs to be focused, and from the scroll container.
	const elRect: DOMRect = element.getBoundingClientRect();
	const scRect: DOMRect = sc.getBoundingClientRect();
	const paneHeight: number = sc.clientHeight;

	// LOGGER.log('focusAndScrollIntoView, sc', sc.id, sc.scrollTop, sc.clientHeight);
	// LOGGER.log('focusAndScrollIntoView, elRect', elRect.top, elRect.bottom, elRect.height);
	// LOGGER.log('focusAndScrollIntoView, scRect', scRect.top, scRect.bottom, scRect.height);

	// See if the element fits within the scroll container
	const fits: boolean = elRect.height <= paneHeight + EPS;
	// See if the element is already fully visible within the scroll container
	const fullyVisible: boolean = elRect.bottom <= scRect.top + paneHeight;

    LOGGER.log(`focusAndScrollIntoView fits: ${fits} fullyVisible: ${fullyVisible} calc: ${elRect.bottom} <= ${scRect.top + paneHeight}`)
	if (fits && fullyVisible) return;

	// Compute minimal scroll in the container's coordinate system
	const offsetTop: number = elRect.top - scRect.top + sc.scrollTop;
	const offsetBottom: number = elRect.bottom + sc.scrollTop;

    LOGGER.log(`A: ${scRect.top}, B: ${sc.clientHeight}, C: ${sc.scrollTop}, D: ${elRect.top}, E: ${elRect.bottom}, elRect.y: ${elRect.y}`)
	if (fits) {
		// LOGGER.log('focusAndScrollIntoView, fits, scrolling...', offsetBottom);
		// Bring entire element into view by aligning its bottom if needed
		sc.scrollTo({ top: Math.max(0, offsetBottom - paneHeight), behavior: "smooth" });
		// sc.scrollTo({ top: offsetBottom, behavior: "smooth" });
		return;
	}

	// Taller than visible area → align top if it’s outside the viewport of the pane
	const topInView: boolean = elRect.top >= scRect.top - EPS && elRect.top <= scRect.bottom + EPS;
	if (!topInView) {
        LOGGER.log('focusAndScrollIntoView, scrolling...');
		sc.scrollTo({ top: Math.max(0, offsetTop), behavior: "smooth" });
	} else {
        LOGGER.log(`focusAndScrollIntoView, topInView ${topInView}`);
	}
}

