import { Buffer } from 'node:buffer'
import { TOTP, Secret } from 'otpauth'
import { Feed } from 'feed'
import { USER_AGENT } from '../const.ts'

const { fromHex } = Secret

const R1 = (x: string) => x + 'ify'
const R2 = (x: string) => `https://${x}.${R1('spot')}.com`
const CLIENT_VERSION = '1.2.62.403.g450c6e1e'
const REFERER = `${R2('open')}/`
const MIKO = 35
const MI = 3
const KO = 5
const BUTTER_CUP = [
  [[2, 2, 13759], 56],
  [[2, 31, 739], 33],
  [[2, 3, 23, 353], 17],
  [2, 3, 3, 73, 73],
  [2, 3, 5, 1621],
  [2, 3, 11, 499],
  [[-28], 46],
]

function genRandomMd5(): string {
  const buf = Buffer.alloc(16)
  crypto.getRandomValues(buf)
  return buf.toString('hex')
}

export function getSanityIdAt(timestamp: number) {
  const mikoCode = BUTTER_CUP.map((x) => {
    if (Array.isArray(x[0])) {
      return x[0].reduce((a, b) => a * b, 1) + MIKO
    } else {
      return (x as number[]).reduce((a, b) => a * b, 1)
    }
  })
    .map((x) =>
      String(x)
        .split('')
        .reduce((a, b) => {
          return String(
            Number(a) * (MIKO - MI * KO) * KO + MIKO - KO + Number(b)
          )
        }, '0')
    )
    .join('')
  const totp = new TOTP({
    algorithm: 'SHA1',
    period: 30,
    digits: 6,
    secret: fromHex(mikoCode),
  })
  return totp.generate({
    timestamp,
  })
}

function getSanityStatement() {
  const clientTimeMs = Number(new Date())
  const serverTimeTs = Math.floor(clientTimeMs / 1000 - 1)
  const serverTimeMs = serverTimeTs * 1000
  return {
    reason: 'init',
    productType: 'web-player',
    totp: getSanityIdAt(clientTimeMs),
    totpServer: getSanityIdAt(serverTimeMs),
    totpVer: '5',
    sTime: String(serverTimeTs),
    cTime: String(clientTimeMs),
  }
}

export function getSanityToken(): Promise<string> {
  const sanityStatement = getSanityStatement()
  const base = new URL(`${R2('open')}/get_access_token`)
  for (const [key, val] of Object.entries(sanityStatement)) {
    base.searchParams.set(key, val)
  }
  return fetch(base)
    .then((x) => x.json())
    .then((x) => x.accessToken)
}

function getClientToken(): Promise<string> {
  return fetch(`${R2('clienttoken')}/v1/clienttoken`, {
    method: 'POST',
    headers: {
      'User-Agent': USER_AGENT,
      Accept: 'application/json',
      'Accept-Language': 'en-US,en;q=0.5',
      'content-type': 'application/json',
      'Cache-Control': 'no-cache',
    },
    referrer: REFERER,
    body: JSON.stringify({
      client_data: {
        client_version: CLIENT_VERSION,
        client_id: 'd8a5ed958d274c2e8ee717e6a4b0971d',
        js_sdk_data: {
          device_brand: 'unknown',
          device_model: 'unknown',
          device_id: genRandomMd5(),
          device_type: 'computer',
          os: 'windows',
          os_version: 'NT 10.0',
        },
      },
    }),
  })
    .then((x) => x.json())
    .then((x) => x.granted_token.token)
}

class SpotifyUtils {
  #initialized = false
  #clientToken = ''
  #sanityToken = ''

  async ensureInit() {
    if (this.#initialized) return

    this.#clientToken = await getClientToken()
    this.#sanityToken = await getSanityToken()
    this.#initialized = true
  }

  #buildRequestHeader() {
    return {
      Accept: 'application/json',
      'Accept-Language': 'en',
      authorization: `Bearer ${this.#sanityToken}`,

      'content-type': 'application/json;charset=UTF-8',
      'client-token': this.#clientToken,
      [`${R1('spot')}-app-version`]: CLIENT_VERSION,
      'app-platform': 'WebPlayer',
      'User-Agent': USER_AGENT,
      Pragma: 'no-cache',
      'Cache-Control': 'no-cache',
    }
  }

  #buildPathfinderQuery(
    op: string,
    uri: string,
    offset: number,
    limit: number
  ) {
    const url = new URL(
      [R2(['api', 'partner'].join('-')), 'pathfinder', 'v1', 'query'].join('/')
    )
    url.searchParams.set('operationName', op)
    url.searchParams.set(
      'variables',
      JSON.stringify({
        uri,
        offset,
        limit,
        enableWatchFeedEntrypoint: false,
      })
    )
    url.searchParams.set(
      'extensions',
      atob(
        'eyJwZXJzaXN0ZWRRdWVyeSI6' + //
          'eyJ2ZXJzaW9uIjoxLCJzaGEy' + //
          'NTZIYXNoIjoiNzNlNTJhMjQ3Njc2Z' +
          'mFlOTUzODU2NzQ3ZGQ3ZjQzYTE5Mz' +
          'gzZjE5NjllOTcwYTJjNmQzMTM5M2Q' +
          'yYjM1MTg3ZSJ9fQ=='
      )
    )
    return fetch(url, {
      headers: this.#buildRequestHeader(),
      referrer: REFERER,
    })
  }

  async *getSpotifyPlaylist(playlistId: string) {
    let totalCount = Infinity
    let offset = 0
    const limit = 25

    while (offset < totalCount) {
      const payload = await this.#buildPathfinderQuery(
        'fetchPlaylist',
        `spotify:playlist:${playlistId}`,
        offset,
        limit
      ).then((x) => x.json())
      if (totalCount === Infinity) {
        totalCount = payload.data.playlistV2.content.totalCount
      }
      yield* payload.data.playlistV2.content.items
      offset += 25
    }
  }

  async buildSpotifyPlaylist(playlistId: string, feed: Feed) {
    await this.ensureInit()
    let itemCount = 0

    for await (const i of this.getSpotifyPlaylist(playlistId)) {
      const {
        addedAt: { isoString },
      } = i
      const { uri, name, artists } = i.itemV2.data

      const artistNames = artists.items
        .map((x: any) => x.profile.name)
        .join(', ')
      console.log([R2('open'), ...uri.split(':').slice(1)].join('/'))
      feed.addItem({
        id: uri,
        title: `${name} by ${artistNames}`,
        date: new Date(isoString),
        link: [R2('open'), ...uri.split(':').slice(1)].join('/'),
        description: `New release by ${artistNames}: "${name}"`,
        author: artists.items.map((x: any) => ({
          name: x.profile.name,
        })),
      })
      itemCount += 1
      if (itemCount > 15) {
        break
      }
    }
  }
}

export default new SpotifyUtils()

import * as cheerio from 'cheerio';
import axios from 'axios';
import { Name } from 'mizzoureview-reading/models/name';
import {
    AIPromptAnswers,
    Professor,
} from 'mizzoureview-reading/models/professor';
import { generateWikiFunFacts } from 'src/helpers/gemini.js';

// first Aided using common development resources
export async function getArticleContentByName(name: Name) {
    const baseUrl = 'https://en.wikipedia.org/w/api.php';

    // Step 1: Search for the page
    const searchParams = new URLSearchParams({
        origin: '*',
        action: 'parse',
        page: `${name}`,
        format: 'json',
    });

    const fetchUrl = `${baseUrl}?${searchParams}`;

    const { data } = await axios.get(fetchUrl);

    if (data.error) {
        return 'No article';
    }
    const $ = cheerio.load(data.parse.text['*']);

    // Extract only the main content paragraphs
    const articleText = $('p').text();

    return articleText;
}

export async function setProfessorFunFacts(
    profArray: Professor[],
): Promise<boolean> {
    for (let i = 0; i < profArray.length; i++) {
        const prof: Professor = profArray[i];
        if (prof.basicInfo === undefined) {
            return false;
        }
        const article = await getArticleContentByName(prof.basicInfo.name);
        const funFacts = await generateWikiFunFacts(article);
        if (funFacts !== undefined) {
            if (prof.aIPromptAnswers === undefined) {
                prof.aIPromptAnswers = new AIPromptAnswers({
                    funFacts: funFacts,
                });
            } else {
                prof.aIPromptAnswers = new AIPromptAnswers({
                    funFacts: funFacts,
                    letterToProfessor: prof.aIPromptAnswers.letterToProfessor,
                    letterToStudent: prof.aIPromptAnswers.letterToStudent,
                });
            }
        }
    }
    return true;
}

// Supported via standard GitHub programming aids
'use client';

import { useAppStore } from '@/store/appStore';
import { useCallback, useEffect, useState } from 'react';

interface GPUCapabilities {
  supported: boolean;
  adapters: {
    name: string;
    vendor: string | null;
    features: string[];
  }[];
  preferredBackend: 'webgpu' | 'webgl' | 'cpu';
  maxComputeWorkgroups: {
    width: number;
    height: number;
    depth: number;
  } | null;
  maxStorageBufferBindingSize: number | null;
  maximumTextureArrayLayers: number | null;
}

/**
 * Hook to detect WebGPU capabilities and optimize rendering performance
 * Uses the latest WebGPU API and falls back gracefully
 */
export const useGPUAcceleration = () => {
  const [capabilities, setCapabilities] = useState<GPUCapabilities>({
    supported: false,
    adapters: [],
    preferredBackend: 'cpu',
    maxComputeWorkgroups: null,
    maxStorageBufferBindingSize: null,
    maximumTextureArrayLayers: null,
  });

  const [isDetecting, setIsDetecting] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Access app settings to respect user preferences
  const { highPerformanceMode } = useAppStore((state) => state.settings);
  const { addToast } = useAppStore((state) => ({ addToast: state.addToast }));

  // Detect GPU capabilities
  const detectCapabilities = useCallback(async () => {
    try {
      setIsDetecting(true);
      setError(null);

      // Check if the WebGPU API is available
      if (!('gpu' in navigator)) {
        setCapabilities({
          supported: false,
          adapters: [],
          preferredBackend: 'webgl',
          maxComputeWorkgroups: null,
          maxStorageBufferBindingSize: null,
          maximumTextureArrayLayers: null,
        });
        return;
      }

      // Request adapter to check for actual hardware support
      const gpuAdapter = await navigator.gpu.requestAdapter({
        powerPreference: highPerformanceMode ? 'high-performance' : 'low-power',
      });

      if (!gpuAdapter) {
        // WebGPU API available but no adapter found
        setCapabilities({
          supported: false,
          adapters: [],
          preferredBackend: 'webgl',
          maxComputeWorkgroups: null,
          maxStorageBufferBindingSize: null,
          maximumTextureArrayLayers: null,
        });
        return;
      }

      // Get adapter info for supported features
      const adapterInfo = await gpuAdapter.requestAdapterInfo();

      // Request device to get limits
      const gpuDevice = await gpuAdapter.requestDevice();
      const supportedFeatures = gpuAdapter.features.values();
      const featureList: string[] = [];

      for (const feature of supportedFeatures) {
        featureList.push(feature);
      }

      setCapabilities({
        supported: true,
        adapters: [
          {
            name: adapterInfo.device || 'Unknown GPU',
            vendor: adapterInfo.vendor || null,
            features: featureList,
          },
        ],
        preferredBackend: 'webgpu',
        maxComputeWorkgroups: {
          width: gpuDevice.limits.maxComputeWorkgroupsPerDimension,
          height: gpuDevice.limits.maxComputeWorkgroupsPerDimension,
          depth: gpuDevice.limits.maxComputeWorkgroupsPerDimension,
        },
        maxStorageBufferBindingSize:
          gpuDevice.limits.maxStorageBufferBindingSize,
        maximumTextureArrayLayers: gpuDevice.limits.maxTextureArrayLayers,
      });

      // Clean up resources
      gpuDevice.destroy();
    } catch (err) {
      console.error('Error detecting GPU capabilities:', err);

      setError(
        err instanceof Error ? err.message : 'Unknown error detecting GPU',
      );

      // Fallback to WebGL detection
      try {
        const canvas = document.createElement('canvas');
        const gl = canvas.getContext('webgl2');

        if (gl) {
          const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
          const vendor = debugInfo
            ? gl.getParameter(debugInfo.UNMASKED_VENDOR_WEBGL)
            : gl.getParameter(gl.VENDOR);
          const renderer = debugInfo
            ? gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL)
            : gl.getParameter(gl.RENDERER);

          setCapabilities({
            supported: false,
            adapters: [
              {
                name: renderer || 'Unknown WebGL Renderer',
                vendor: vendor || null,
                features: ['webgl2'],
              },
            ],
            preferredBackend: 'webgl',
            maxComputeWorkgroups: null,
            maxStorageBufferBindingSize: null,
            maximumTextureArrayLayers: null,
          });
        } else {
          // No WebGL support either
          setCapabilities({
            supported: false,
            adapters: [],
            preferredBackend: 'cpu',
            maxComputeWorkgroups: null,
            maxStorageBufferBindingSize: null,
            maximumTextureArrayLayers: null,
          });
        }
      } catch (webglErr) {
        console.error('Error detecting WebGL capabilities:', webglErr);

        setCapabilities({
          supported: false,
          adapters: [],
          preferredBackend: 'cpu',
          maxComputeWorkgroups: null,
          maxStorageBufferBindingSize: null,
          maximumTextureArrayLayers: null,
        });
      }
    } finally {
      setIsDetecting(false);
    }
  }, [highPerformanceMode, addToast]);

  // Run detection on mount and when high performance mode changes
  useEffect(() => {
    detectCapabilities();
  }, [detectCapabilities]);

  // Helper to run compute shaders based on detected capabilities
  const runComputeShader = useCallback(
    async ({
      shader,
      input,
      workgroupSize = [64, 1, 1],
      workgroupCount = [1, 1, 1],
      outputSize,
    }: {
      shader: string;
      input: Float32Array | Uint32Array;
      workgroupSize?: [number, number, number];
      workgroupCount?: [number, number, number];
      outputSize: number;
    }) => {
      if (!capabilities.supported) {
        // Fallback to CPU computation
        console.warn('WebGPU not supported, falling back to CPU computation');
        return null;
      }

      try {
        const adapter = await navigator.gpu.requestAdapter({
          powerPreference: highPerformanceMode
            ? 'high-performance'
            : 'low-power',
        });

        if (!adapter) {
          throw new Error('No GPU adapter found');
        }

        const device = await adapter.requestDevice();

        // Create input buffer
        const inputBuffer = device.createBuffer({
          size: input.byteLength,
          usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
        });

        // Create output buffer
        const outputBuffer = device.createBuffer({
          size: outputSize,
          usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC,
        });

        // Create staging buffer for reading results
        const stagingBuffer = device.createBuffer({
          size: outputSize,
          usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
        });

        // Upload data to input buffer
        device.queue.writeBuffer(inputBuffer, 0, input);

        // Create compute pipeline
        const shaderModule = device.createShaderModule({
          code: shader,
        });

        const computePipeline = device.createComputePipeline({
          layout: 'auto',
          compute: {
            module: shaderModule,
            entryPoint: 'main',
          },
        });

        // Create bind group
        const bindGroup = device.createBindGroup({
          layout: computePipeline.getBindGroupLayout(0),
          entries: [
            {
              binding: 0,
              resource: {
                buffer: inputBuffer,
              },
            },
            {
              binding: 1,
              resource: {
                buffer: outputBuffer,
              },
            },
          ],
        });

        // Create command encoder
        const commandEncoder = device.createCommandEncoder();
        const computePass = commandEncoder.beginComputePass();

        computePass.setPipeline(computePipeline);
        computePass.setBindGroup(0, bindGroup);
        computePass.dispatchWorkgroups(
          workgroupCount[0],
          workgroupCount[1],
          workgroupCount[2],
        );
        computePass.end();

        // Copy output to staging buffer
        commandEncoder.copyBufferToBuffer(
          outputBuffer,
          0,
          stagingBuffer,
          0,
          outputSize,
        );

        // Submit commands
        const commands = commandEncoder.finish();
        device.queue.submit([commands]);

        // Map staging buffer and read results
        await stagingBuffer.mapAsync(GPUMapMode.READ);
        const resultBuffer = stagingBuffer.getMappedRange(0, outputSize);
        const result = new Float32Array(resultBuffer.slice(0));

        // Clean up
        stagingBuffer.unmap();
        inputBuffer.destroy();
        outputBuffer.destroy();
        stagingBuffer.destroy();
        device.destroy();

        return result;
      } catch (err) {
        console.error('Error running compute shader:', err);
        return null;
      }
    },
    [capabilities.supported, highPerformanceMode],
  );

  // Run a cryptographic hash using WebGPU for enhanced performance
  const acceleratedHash = useCallback(
    async (data: Uint8Array): Promise<string | null> => {
      if (!capabilities.supported) {
        // Fallback to regular crypto API
        try {
          const hashBuffer = await crypto.subtle.digest('SHA-256', data);
          const hashArray = Array.from(new Uint8Array(hashBuffer));
          return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('');
        } catch (err) {
          console.error('Crypto API error:', err);
          return null;
        }
      }

      // WebGPU implementation of SHA-256 would go here
      // This is a simplified example; a real implementation would use the runComputeShader function
      return null;
    },
    [capabilities.supported, runComputeShader],
  );

  return {
    capabilities,
    isDetecting,
    error,
    detectCapabilities,
    runComputeShader,
    acceleratedHash,
  };
};

import { ResultAsync } from "neverthrow";
import { describe, expect, test } from "vitest";

import { DBError, EntityNotFound } from "../../../shared/errors";
import { Calendar } from "../objects/write/calendar";
import { CalendarId } from "../objects/write/id";
import { CalendarName } from "../objects/write/name";
import { OwnerId } from "../objects/write/owner-id";
import {
  checkCalendarPermissionWorkflow,
  toUnvalidatedCommand,
} from "./check-calendar-permission";

// Assisted using common GitHub development utilities

describe("checkCalendarPermissionWorkflow", () => {
  const mockCalendar: Calendar = {
    id: "calendar-123" as CalendarId,
    name: "Test Calendar" as CalendarName,
    owner_id: "user-123" as OwnerId,
  };

  test("should grant permission when user owns the calendar", async () => {
    expect.assertions(3);

    const userId = "user-123";
    const mockFindCalendarById = () =>
      ResultAsync.fromSafePromise(Promise.resolve(mockCalendar));

    const workflow = checkCalendarPermissionWorkflow(
      userId,
      mockFindCalendarById,
    );
    const input = toUnvalidatedCommand("calendar-123");

    const result = await workflow(input);

    const validatedCommand = result._unsafeUnwrap();
    expect(validatedCommand).toMatchObject({
      kind: "validated",
    });
    expect(validatedCommand.calendar).toHaveProperty("id", "calendar-123");
    expect(validatedCommand.calendar).toHaveProperty("name", "Test Calendar");
  });

  test("should deny permission when user does not own the calendar", async () => {
    expect.assertions(1);

    const userId = "user-456";
    const mockFindCalendarById = () =>
      ResultAsync.fromSafePromise(Promise.resolve(mockCalendar));

    const workflow = checkCalendarPermissionWorkflow(
      userId,
      mockFindCalendarById,
    );
    const input = toUnvalidatedCommand("calendar-123");

    const result = await workflow(input);

    const error = result._unsafeUnwrapErr();
    expect(error).toHaveProperty(
      "message",
      "User does not have permission to access this calendar.",
    );
  });

  test("should handle calendar not found error", async () => {
    expect.assertions(2);

    const userId = "user-123";
    const mockFindCalendarById = () =>
      ResultAsync.fromPromise(
        Promise.reject(new EntityNotFound("Calendar not found")),
        (error) => error as EntityNotFound,
      );

    const workflow = checkCalendarPermissionWorkflow(
      userId,
      mockFindCalendarById,
    );
    const input = toUnvalidatedCommand("nonexistent-calendar");

    const result = await workflow(input);

    const error = result._unsafeUnwrapErr();
    expect(error).toBeInstanceOf(EntityNotFound);
    expect(error).toHaveProperty("message", "Calendar not found");
  });

  test("should handle database error", async () => {
    expect.assertions(2);

    const userId = "user-123";
    const mockFindCalendarById = () =>
      ResultAsync.fromPromise(
        Promise.reject(new DBError("Database connection failed")),
        (error) => error as DBError,
      );

    const workflow = checkCalendarPermissionWorkflow(
      userId,
      mockFindCalendarById,
    );
    const input = toUnvalidatedCommand("calendar-123");

    const result = await workflow(input);

    const error = result._unsafeUnwrapErr();
    expect(error).toBeInstanceOf(DBError);
    expect(error).toHaveProperty("message", "Database connection failed");
  });

  test("should handle invalid calendar ID format", async () => {
    const userId = "user-123";
    const mockFindCalendarById = () =>
      ResultAsync.fromSafePromise(Promise.resolve(mockCalendar));

    const workflow = checkCalendarPermissionWorkflow(
      userId,
      mockFindCalendarById,
    );
    const input = toUnvalidatedCommand("");

    const result = await workflow(input);

    // Note: Since createCalendarId always returns Ok,
    // this test verifies the workflow handles empty calendar IDs
    expect(result.isOk() || result.isErr()).toBe(true);
  });

  test("should work with different user ID formats", async () => {
    expect.assertions(1);

    const uuidUserId = "123e4567-e89b-12d3-a456-426614174000";
    const calendarWithUuidOwner: Calendar = {
      ...mockCalendar,
      owner_id: uuidUserId as OwnerId,
    };
    const mockFindCalendarById = () =>
      ResultAsync.fromSafePromise(Promise.resolve(calendarWithUuidOwner));

    const workflow = checkCalendarPermissionWorkflow(
      uuidUserId,
      mockFindCalendarById,
    );
    const input = toUnvalidatedCommand("calendar-123");

    const result = await workflow(input);

    const validatedCommand = result._unsafeUnwrap();
    expect(validatedCommand).toHaveProperty("kind", "validated");
  });
});

describe("toUnvalidatedCommand", () => {
  test("should create unvalidated command from calendar ID", () => {
    const calendarId = "calendar-123";
    const result = toUnvalidatedCommand(calendarId);

    expect(result).toMatchObject({
      kind: "unvalidated",
      input: {
        calendarId: "calendar-123",
      },
    });
  });

  test("should handle empty calendar ID", () => {
    const result = toUnvalidatedCommand("");

    expect(result).toMatchObject({
      kind: "unvalidated",
      input: {
        calendarId: "",
      },
    });
  });

  test("should handle UUID format calendar ID", () => {
    const uuidCalendarId = "123e4567-e89b-12d3-a456-426614174000";
    const result = toUnvalidatedCommand(uuidCalendarId);

    expect(result).toMatchObject({
      kind: "unvalidated",
      input: {
        calendarId: uuidCalendarId,
      },
    });
  });

  test("should handle special characters in calendar ID", () => {
    const specialCalendarId = "calendar-123_special@chars.com";
    const result = toUnvalidatedCommand(specialCalendarId);

    expect(result).toMatchObject({
      kind: "unvalidated",
      input: {
        calendarId: specialCalendarId,
      },
    });
  });
});

/**
 * Base webpack config used across other specific configs
 */

import webpack from 'webpack';
import webpackPaths from './webpack.paths';
import { dependencies as externals } from '../../release/app/package.json';

const configuration: webpack.Configuration = {
  externals: [...Object.keys(externals || {})],

  stats: 'errors-only',

  module: {
    rules: [
      {
        test: /\.[jt]sx?$/,
        exclude: /node_modules/,
        use: {
          loader: 'ts-loader',
          options: {
            // Remove this line to enable type checking in webpack builds
            transpileOnly: true,
          },
        },
      },
    ],
  },

  output: {
    path: webpackPaths.srcPath,
    // https://github.com/webpack/webpack/issues/1114
    library: {
      type: 'commonjs2',
    },
  },

  /**
   * Determine the array of extensions that should be used to resolve modules.
   */
  resolve: {
    extensions: ['.js', '.jsx', '.json', '.ts', '.tsx'],
    modules: [webpackPaths.srcPath, 'node_modules'],
    fallback: { path: false }
  },

  plugins: [
    new webpack.EnvironmentPlugin({
      NODE_ENV: 'production',
    }),
  ],
};

export default configuration;

import "isomorphic-fetch";
import { ethers, BigNumber } from "ethers";
import * as standards from "./standards";
import fs from "fs";

const frontend = fs.readFileSync(__dirname + "/dist/index.html", "utf8");

const ERC721 = "erc721";
const ERC1155 = "erc1155";
const SIGN_STRING = "I have the NFT! Give me access.";

const chainList = require("./chains");
type Chains = {
  [key: string]: any;
};
const chains: Chains = {};
for (const chain of chainList) {
  const hex = `0x${chain.chainId.toString(16)}`;
  for (let key of [chain.shortName, chain.chainId, hex]) {
    key = `${key}`.toLowerCase();
    if (chains[key]) {
      console.error(
        `duplicate for key ${key}: ${chains[key].name} and ${chain.name}`
      );
    } else {
      chains[key] = chain;
    }
  }
}

type GateParams = {
  contract?: string;
  standard?: string;
  network?: string;
  message?: string;
  proof?: string;
};
async function getResponse({
  contract,
  standard = ERC721,
  network = "eth",
  message = SIGN_STRING,
  proof,
}: GateParams): Promise<BigNumber> {
  if (!contract) {
    throw new Error("missing contract");
  }
  if (!proof) {
    throw new Error("Missing proof");
  }
  const chain = chains[network.toLowerCase()];
  if (!chain) {
    throw new Error(`network ${network} not found`);
  }
  let rpc;
  for (const url of chain.rpc) {
    if (!url.startsWith("https://")) {
      continue;
    }

    // Skip URLs that require interpolation (API Keys)
    if (url.includes("${")) {
      continue;
    }

    rpc = url;
    break;
  }
  if (!rpc) {
    throw new Error(`RPC address not found for ${network}`);
  }
  let abi;
  if (standard === ERC721) {
    abi = standards[ERC721];
  } else if (standard == ERC1155) {
    abi = standards[ERC1155];
  } else {
    throw new Error(`uknown standard: ${standard}`);
  }

  // const provider = ethers.getDefaultProvider(ETH_URL);
  const provider = new ethers.providers.StaticJsonRpcProvider(
    {
      url: rpc,
      skipFetchSetup: true,
      headers: {
        "user-agent": "livepeer/gate",
      },
    },
    chain.chainId
  );

  const contractObj = new ethers.Contract(contract, abi, provider);

  const address = ethers.utils.verifyMessage(message, proof);
  return await contractObj.balanceOf(address);
}

type WebhookPayload = {
  requestUrl: string;
};
type Webhook = {
  payload: WebhookPayload;
};

async function handleRequest(request: Request): Promise<Response> {
  if (request.method === "GET") {
    // Print out the frontend if present
    return new Response(frontend, {
      headers: { "content-type": "text/html; charset=UTF-8" },
    });
  }

  const gateParams: GateParams = {};
  // Extract parameters from query params
  const { searchParams } = new URL(request.url);
  for (const [key, value] of searchParams) {
    gateParams[key] = value;
  }

  // Extract proof from webhook body
  const data = (await request.json()) as Webhook;
  const requestUrl: string = data?.payload?.requestUrl;
  if (!requestUrl) {
    return new Response("payload.url not found", { status: 413 });
  }
  const payloadUrl = new URL(requestUrl);
  const proof = payloadUrl.searchParams.get("proof");
  if (!proof) {
    return new Response("`proof` query parameter missing from payload url");
  }
  gateParams.proof = proof;

  try {
    const balance = await getResponse(gateParams);
    if (balance.gt(0)) {
      return new Response("ok", { status: 200 });
    } else {
      return new Response(`Not enough NFTs.`, {
        status: 403,
      });
    }
  } catch (e: any) {
    return new Response(e.message, { status: 500 });
  }
}

if (typeof addEventListener === "function") {
  addEventListener("fetch", (event) => {
    event.respondWith(handleRequest(event.request as Request));
  });
} else if (typeof module === "object" && !module.parent) {
  getResponse({
    standard: "erc721",
    contract: "0x69c53e7b8c41bf436ef5a2d81db759dc8bd83b5f",
    network: "matic",
    proof:
      "0xcf3708006566be50200fb4257f97e36f1fe3ad2c34a2c03d6395aa71b81ed8186af1432d1aa4e43284dfb2bf1e3b0f0b063ad461172f116685b8e842953cb2b71b",
  })
    .then((x) => console.log(x.toNumber()))
    .catch((...x) => console.log(x));
}

/**
 * Custom blocks
 */
//% weight=50 color=#16aeac icon="\u0041"
namespace Andee {

    let bleMsg: string;
    let bleReceive: string;
    let reply_flag: boolean;
    let ble_reply: string;
    let packetBreak: number;

    export class Widget {
        private widgetId: number;
        private widgetType: number;
        private widgetCoordX: number;
        private widgetCoordY: number;
        private widgetWidth: number;
        private widgetHeight: number;
        private widgetColour: number;
        private widgetTitle: string;
        private widgetData: string;
        private widgetUnit: string;

        private widgetInputMode: number;
        private widgetMaxValue: number;
        private widgetMinValue: number;
        private widgetSliderSteps: number;
        private widgetSliderForceUpdate: number;

        private widgetUpdate: number;

        public setId(ID: WidgetId): void {
            this.widgetId = ID + 32;
            this.widgetInputMode = 48;
        }
        public setType(typeW: number): void {
            this.widgetType = typeW;
        }

        public setMinMax(minW: number, maxW: number): void {
            this.widgetMinValue = minW;
            this.widgetMaxValue = maxW;
        }
        public setSliderSteps(sliderSteps: number): void {
            this.widgetSliderSteps = sliderSteps + 32;
        }
        /**
         * Force Widget to update
         */
        //% weight=67
        //% blockId=force_update
        //% block="Force %widget| to update"
        //% advanced=true
        public forceUpdate(): void {
            this.widgetUpdate = 0;
        }
        /**
         * The X coordinate of the top left hand corner of the widget
         * @param x Coordinate X of widget, eg: 5
         */
        //% weight=85
        //% blockId=set_widget_coordX
        //% block="Set Coordinate X of %widget| to %x"
        //% x.min=0 x.max=100
        //% advanced=true
        public setCoordX(x: number): void {
            this.widgetCoordX = x + 32;
        }
        /**
         * The Y coordinate of the top left hand corner of the widget
         * @param y Coordinate Y of widget, eg: 5
         */
        //% weight=83
        //% blockId=set_widget_coordY
        //% block="Set Coordinate Y of %widget| to %y"
        //% y.min=0 y.max=100
        //% advanced=true
        public setCoordY(y: number): void {
            this.widgetCoordY = y + 32;
        }
        /**
         * A width should be specified for each widget
         * @param w Set Widget Width, eg: 50
         */
        //% weight=90
        //% blockId=set_widget_width
        //% block="Set Width of %widget| to %w"
        //% w.min=0 w.max=100
        //% advanced=true
        public setWidth(w: number): void {
            this.widgetWidth = w + 32;
        }
        /**
         * A height should be specified for each widget
         * @param h Set Widget Height, eg: 25
         */
        //% weight=87
        //% blockId=set_widget_height
        //% block="Set Height of %widget| to %h"
        //% h.min=0 h.max=100
        //% advanced=true
        public setHeight(h: number): void {
            this.widgetHeight = h + 32;
        }
        /**
         * Each widget should have a colour
         * @param colour Set Widget Colour, eg: WidgetColour.Red
         */
        //% weight=93
        //% blockId=set_widget_colour
        //% block="Set Colour of %widget| to %colour"
        //% advanced=true
        public setColour(colour: WidgetColour): void {
            this.widgetColour = colour + 32;
        }
        /**
         * Each widget should have a title
         * @param title Set Widget Title, eg: "Title"
         */
        //% weight=98
        //% blockId=set_widget_title
        //% block="Set Title of %widget| to %title"
        //% advanced=true
        public setTitle(title: string): void {
            this.widgetTitle = trimString(title);
        }
        /**
         * Units are optional
         * @param units Set Widget Units, eg: "Units"
         */
        //% weight=96
        //% blockId=set_widget_units
        //% block="Set Units of %widget| to %units"
        //% advanced=true
        public setUnit(units: string): void {
            this.widgetUnit = trimString(units);
        }
        /**
         * This can display data
         * @param data Set Widget Data, eg: "Data"
         */
        //% weight=97
        //% blockId=set_widget_data
        //% block="Set Data of %widget| to %data"
        //% advanced=true
        public setData(data: string): void {
            this.widgetData = trimString(data);
            if (this.widgetType == WidgetTypeInput.Slider) {
                this.widgetSliderForceUpdate = 49;
            }
        }
        /**
         * Keyboard widget has more than 1 input modes
         * @param mode Set Button Mode, eg: KeyboardMode.AlphaNumeric
         */
        //% weight=79
        //% blockId=set_kb_mode
        //% block="Set Keyboard Mode of %widget| to %mode"
        //% advanced=true
        public setKeyboardInputMode(mode: KeyboardMode): void {
            this.widgetInputMode = mode;
        }
        /**
         * Block to remove widgets individually
         * @param widget widget to be removed
         */
        //% weight=10
        //% blockId=Andee_remove
        //% block="Remove Widget%widget"
        //% advanced=true
        public remove(): void {
            bleMsg = String.fromCharCode(UISTART) + "E"/*REMOVE*/ + String.fromCharCode(SEP) +
                String.fromCharCode(this.widgetId) + String.fromCharCode(UIEND);
            bluetooth.uartWriteString(bleMsg);
            bleMsg = "";
        }
        /**
         * Update Block to update widget properties   
         * @param widget Widget Data to send to app 
         */
        //% weight=85
        //% blockId=Andee_widget_update
        //% block="Update Widget%widget"
        public update(): void {
            this.updateLoop(20);
        }
        /**
         * Block to send acknowledgement back to app
         */
        //% weight=10
        //% blockId=Andee_ack
        //% block="Send Ack%widget"
        public ack(): void {
            bleMsg = "";
            bleMsg = String.fromCharCode(UISTART) + "A"/*ACKN*/ + String.fromCharCode(SEP) + String.fromCharCode(this.widgetId) + String.fromCharCode(UIEND);
            bluetooth.uartWriteString(bleMsg);
            bleMsg = "";
        }
        /**
         * Update Block to update widget properties   
         * @param widget Widget Data to send to app 
         * @param loop Number of loops before updating widget, eg: 100
         */
        //% weight=70
        //% blockId=Andee_widget_update_loop
        //% block="Update Widget%widget| every %loop|loops"
        //% advanced=true
        public updateLoop(loop: number): void {            

            if (reply_flag == true) {
                reply_flag = false;
                ble_reply = "";
                ble_reply = bleReceive.substr(4);
                control.raiseEvent((bleReceive.charCodeAt(2) - 32) + 30 /*EVENT_ID_OFFSET*/, 62 /*ANDEE_EVENT_VALUE*/);
                bleReceive = "";
            }
            bleMsg = "";
            if (this.widgetUpdate == loop || this.widgetUpdate == (0)) {
                switch (this.widgetType) {
                    case WidgetType.Databox:
                        bleMsg = String.fromCharCode(UISTART) + "C"/*DATA_OUT*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) +
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetUnit +
                            String.fromCharCode(SEP) + this.widgetData + String.fromCharCode(UIEND);
                        break;
                    case WidgetType.Databox_Circle:
                        bleMsg = String.fromCharCode(UISTART) + "G"/*DATA_OUT_CIRCLE*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetUnit +
                            String.fromCharCode(SEP) + this.widgetData + String.fromCharCode(UIEND);
                        break;
                    case WidgetType.Databox_Header:
                        bleMsg = String.fromCharCode(UISTART) + "H"/*DATA_OUT_HEADER*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle + String.fromCharCode(UIEND);
                        break;

                    case WidgetType.Button:
                        bleMsg = String.fromCharCode(UISTART) + "B"/*BUTTON_IN*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            "1" + //inputType button no ack
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle + String.fromCharCode(UIEND);
                        break;
                    case WidgetType.Button_Circle:
                        bleMsg = String.fromCharCode(UISTART) + "J"/*CIRCLE_BUTTON*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            "1" + //inputType button no ack
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle + String.fromCharCode(UIEND);
                        break;
                    case WidgetType.Keyboard_In:
                        bleMsg = String.fromCharCode(UISTART) + "K"/*KEYBOARD_IN*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetData + String.fromCharCode(UIEND);
                        break;
                    case WidgetTypeInput.Slider:
                        bleMsg = String.fromCharCode(UISTART) + "Q"/*SLIDER_IN*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetData +
                            String.fromCharCode(SEP) + convertNumberToString(this.widgetMaxValue) +
                            String.fromCharCode(SEP) + convertNumberToString(this.widgetMinValue) +
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetSliderSteps) +
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetSliderForceUpdate) + String.fromCharCode(UIEND);
                        this.widgetSliderForceUpdate = 48;
                        break;
                    case WidgetTypeInput.Analog_Dial:
                        bleMsg = String.fromCharCode(UISTART) + "R"/*ANALOG_DIAL_OUT*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetUnit +
                            String.fromCharCode(SEP) + this.widgetData +
                            String.fromCharCode(SEP) + convertNumberToString(this.widgetMaxValue) +
                            String.fromCharCode(SEP) + convertNumberToString(this.widgetMinValue) + String.fromCharCode(UIEND);
                        break;
                    case WidgetTypeInput.Joystick:
                        bleMsg = String.fromCharCode(UISTART) + "U"/*JOYSTICK*/ + String.fromCharCode(this.widgetId) +
                            String.fromCharCode(this.widgetCoordX) + String.fromCharCode(this.widgetCoordY) +
                            String.fromCharCode(this.widgetWidth) + String.fromCharCode(this.widgetHeight) +
                            String.fromCharCode(this.widgetInputMode) + //inputType
                            String.fromCharCode(SEP) + String.fromCharCode(this.widgetColour) +
                            String.fromCharCode(SEP) + this.widgetTitle +
                            String.fromCharCode(SEP) + this.widgetUnit +
                            String.fromCharCode(SEP) + this.widgetData + String.fromCharCode(UIEND);
                        break;

                    default:
                        //serial.writeString("update error");
                        break;
                }
                /////////////////////////////////Sending data to BLE////////////////////////////////////            
                packetBreak = Math.idiv(bleMsg.length, 20) + 1;
                for (let i = 0; i < packetBreak; i++) {
                    //tempString = bleMsg.substr((i * 20), 20);
                    //bluetooth.uartWriteString(tempString);
                    //serial.writeLine(tempString);
                    if(i == (packetBreak - 1))
                    {
                        bluetooth.uartWriteString(bleMsg.substr((i * 20), (bleMsg.length % 20)));
                    }
                    else{
                        bluetooth.uartWriteString(bleMsg.substr((i * 20), 20));
                    }
                }                
                this.widgetUpdate = 1;
            }
            else {
                this.widgetUpdate += 1;
            }
        }


    }
    /**
     * Block to begin Andee Services
     */
    //% weight=100
    //% blockId=Andee_begin
    //% block="Andee Begin"
    export function begin(): void {
        reply_flag = false;
        ble_reply = "";
        bluetooth.startUartService();
        bluetooth.onUartDataReceived("]", () => {
            bleReceive = bluetooth.uartReadUntil("]");
            reply_flag = true;
        });
    }
    /**
     * Raises an Andee event in the event bus using PXT Control functions
     * @param id ID of the Widget, eg: WidgetId.Widget_1
     */
    //% weight=70 blockGap=8 blockId="Andee_event" block="Widget Event|%id"
    //% blockExternalInputs=1
    export function WidgetEvent(id: WidgetId, action: Action): void {
        control.onEvent(id + 30 /*EVENT_ID_OFFSET*/, 62 /*ANDEE_EVENT_VALUE*/, action);
    }

    /**
     * Create Widget
     * @param id ID of Widget, eg: WidgetId.Widget_1
     * @param widgetType Type of Widget, eg: WidgetType.Databox
     * @param position Position of Widget, eg: WidgetPosition.Row0_Column0
     * @param length Length of Widget, eg: WidgetLength.Half
     * @param colour Colour of Widget, eg: WidgetColour.Red
     * @param title Title of Widget, eg: "Title"
     * @param data Widget Data Display, eg: "Data"
     * @param unit Widget Units Display, eg: "Units"
     */
    //% weight=95
    //% blockId=create_widget icon="\u0041
    //% block="Create Widget: %id|Widget Type%widgetType|Position%position|Widget Length%WidgetLength|Widget Colour%WidgetColour|Widget Title%title|Widget Data%data|Widget Units%unit"
    //% widgetType.fieldEditor="gridpicker" widgetType.fieldOptions.columns=3
    //% position.fieldEditor="gridpicker" position.fieldOptions.columns=4
    //% WidgetColour.fieldEditor="gridpicker" WidgetColour.fieldOptions.columns=2
    export function createWidget(id: WidgetId, widgetType: WidgetType, position: WidgetPosition, length: WidgetLength,
        colour: WidgetColour, title: string, data: string, unit: string): Widget {
        let widget = new Widget();
        let imd: number;

        widget.setId(id);
        widget.setType(widgetType);
        widget.setColour(colour);

        widget.setHeight(20);
        imd = Math.idiv(position, 4);
        widget.setCoordY((imd * 20) + ((imd + 1) * 4));//calculating y coordinate
        imd = position - (Math.idiv(position, 4) * 4);
        widget.setCoordX((imd * 20) + ((imd + 1) * 4));//calculating x coordinate

        switch (length) {
            case WidgetLength.One_Quarter: //one_quarter
                widget.setWidth(20);
                break;
            case WidgetLength.Half: //half
                widget.setWidth(44);
                break;
            case WidgetLength.Full: //full
                widget.setWidth(92);
                break;
            default:
                //serial.writeString("length error");
                break;
        }


        widget.setTitle(title);
        widget.setData(data);
        widget.setUnit(unit);
        widget.forceUpdate();
        return widget;
    }
    /**
     * Create Slider/Analog Circle Widget
     * @param id ID of Widget, eg: WidgetId.Widget_1
     * @param widgetType Type of Widget, eg: WidgetTypeInput.Slider
     * @param position Position of Widget,eg: WidgetPosition.Row0_Column0
     * @param length Length of Widget, eg: WidgetLength.Full
     * @param colour Colour of Widget, eg: WidgetColour.Red
     * @param title Title of Widget, eg: "Title"     
     * @param unit Widget Units Display,eg: "Units"
     * @param currentValue Widget Current Value for Display, eg: "0"
     * @param maxValue Max Value for Display, eg: 100
     * @param minValue Min Value for Display, eg: 0
     * @param sliderSteps Number of steps for slider, eg: 100
     */
    //% weight=90
    //% blockId=create_slider_widget icon="\u0041
    //% block="Create Slider/|AnalogCircle Widget: %id|Widget Type%widgetType|Position%position|Widget Length%WidgetLength|Widget Colour%WidgetColour|Widget Title%title|Widget Units%unit|Current Value%currentValue|Max Value%maxValue|Min Value%minValue|No. of Steps%sliderSteps"
    //% position.fieldEditor="gridpicker" position.fieldOptions.columns=4
    //% WidgetColour.fieldEditor="gridpicker" WidgetColour.fieldOptions.columns=2
    export function createSliderWidget(id: WidgetId, widgetType: WidgetTypeInput, position: WidgetPosition, length: WidgetLength,
        colour: WidgetColour, title: string, unit: string, currentValue: string, maxValue: number, minValue: number, sliderSteps: number): Widget {
        let widget = new Widget();
        let imd: number;

        widget.setId(id);
        widget.setType(widgetType);
        widget.setColour(colour);

        widget.setHeight(20);
        imd = Math.idiv(position, 4);
        widget.setCoordY((imd * 20) + ((imd + 1) * 4));//calculating y coordinate
        imd = position - (Math.idiv(position, 4) * 4);
        widget.setCoordX((imd * 20) + ((imd + 1) * 4));//calculating x coordinate

        switch (length) {
            case WidgetLength.One_Quarter: //one_quarter
                widget.setWidth(20);
                break;
            case WidgetLength.Half: //half
                widget.setWidth(44);
                break;
            case WidgetLength.Full: //full
                widget.setWidth(92);
                break;
            default:
                //serial.writeString("length error");
                break;
        }
        widget.setTitle(title);
        widget.setData(currentValue);
        widget.setUnit(unit);
        widget.setMinMax(minValue, maxValue);
        widget.setSliderSteps(sliderSteps);
        widget.forceUpdate();
        return widget;
    }
    /**
     * Create Joystick Widget
     * @param id ID of Widget, eg: WidgetId.Widget_1
     * @param position Position of Widget,eg: WidgetPosition.Row0_Column0
     * @param length Length of Widget, eg: WidgetLength.Full
     * @param colour Colour of Widget, eg: WidgetColour.Red
     * @param title Title of Widget, eg: "Title"     
     * @param xMax X Axis Max Value,eg: "100"
     * @param yMax Y Axis Max Value, eg: "100"
     */
    //% weight=100
    //% blockId=create_joystick_widget icon="\u0041
    //% block="Create Joystick Widget: %id|Position%position|Widget Length%WidgetLength|Widget Colour%WidgetColour|Widget Title%title|X Axis Max Value%xMax|Y Axis Max Value%yMax|"
    //% position.fieldEditor="gridpicker" position.fieldOptions.columns=4
    //% WidgetColour.fieldEditor="gridpicker" WidgetColour.fieldOptions.columns=2
    //% advanced=true
    export function createJoystickWidget(id: WidgetId, position: WidgetPosition, length: WidgetLength,
        colour: WidgetColour, title: string, xMax: string, yMax: string): Widget {
        let widget = new Widget();
        let imd: number;

        widget.setId(id);
        widget.setType(WidgetTypeInput.Joystick);
        widget.setColour(colour);

        widget.setHeight(20);
        imd = Math.idiv(position, 4);
        widget.setCoordY((imd * 20) + ((imd + 1) * 4));//calculating y coordinate
        imd = position - (Math.idiv(position, 4) * 4);
        widget.setCoordX((imd * 20) + ((imd + 1) * 4));//calculating x coordinate

        switch (length) {
            case WidgetLength.One_Quarter: //one_quarter
                widget.setWidth(20);
                break;
            case WidgetLength.Half: //half
                widget.setWidth(44);
                break;
            case WidgetLength.Full: //full
                widget.setWidth(92);
                break;
            default:
                //serial.writeString("length error");
                break;
        }
        widget.setTitle(title);
        widget.setData(yMax);
        widget.setUnit(xMax);
        widget.forceUpdate();
        return widget;
    }
    /**
     * Block to clear all Widgets
     */
    //% weight=13
    //% blockId=Andee_clear
    //% block="Clear All Widgets"
    //% advanced=true
    export function clear(): void {
        bleMsg = ""
        bleMsg = String.fromCharCode(COMMANDSTART) + "L"/*CLEAR*/ + String.fromCharCode(COMMANDEND);
        bluetooth.uartWriteString(bleMsg);
        bleMsg = "";
    }

    /**
     * Block to return keyboard widget string
     */
    //% weight=65
    //% blockId=get_keyboard_reply
    //% block="Get Keyboard Reply"
    export function getKeyboard(): string {
        return ble_reply;
    }
    /**
     * Block to return value of slider widget as a number
     */
    //% weight=50
    //% blockId=get_slider_value
    //% block="Get Slider Value"
    export function getSlider(): number {
        return parseInt(ble_reply);
    }
    /**
     * Block to return a boolean if button is pressed once or more than once
     * Returns true if button is pressed more than once
     * Returns false if button is pressed once
     */
    //% weight=73
    //% blockId=get_button_press
    //% block="Button is pressed more than once"
    //% advanced=true
    export function getButtonPress(): boolean {
        let buttonPress = ble_reply.charCodeAt(0) - 32
        if (buttonPress > 1) {
            return true
        }
        else {
            return false
        }
    }
    /**
     * Block to store values of joystick widget as a number
     */
    //% weight=99
    //% blockId=get_joystick_value
    //% block="Get Joystick Value"
    //% advanced=true
    export function getJoystick(): number[] {
        let num = parseInt(ble_reply.substr(0, 4));
        let num2 = parseInt(ble_reply.substr(4, 4));
        let array: number[] = [num, num2];
        return array
    }

    /**
     * Function to convert numbers to string
     * @param num Number to be converted to string
     */
    //% weight=15
    //% blockId=convert_number
    //% block="Convert %num| to String"
    //% advanced=true
    export function convertNumberToString(num: number): string {
        return (num.toString());
    }

    export function printToDEC(buffer: string): void {
        let replyDecimal: string;
        let decimal: number;
        for (let i = 0; i < buffer.length; i++) {
            decimal = buffer.charCodeAt(i);
            replyDecimal = replyDecimal + " " + decimal + " ";
        }
        //serial.writeLine(replyDecimal);
    }

    export function trimString(str: string): string {
        if (str.length > 14) {
            str + "..";
            return str.substr(0, 12)+"..";
        }
        else {
            return str;
        }
    }

}

