import { MarkdownView, Plugin, TFile, getAllTags, Notice, TAbstractFile, normalizePath } from 'obsidian';
import { DEFAULT_SETTINGS, AutoNoteMoverSettings, AutoNoteMoverSettingTab } from 'settings/settings';
import { fileMove, getTriggerIndicator, isFmDisable } from 'utils/Utils';

export default class AutoNoteMover extends Plugin {
	settings: AutoNoteMoverSettings;

	async onload() {
		await this.loadSettings();
		const folderTagPattern = this.settings.folder_tag_pattern;
		const excludedFolder = this.settings.excluded_folder;

		const fileCheck = (file: TAbstractFile, oldPath?: string, caller?: string) => {
			if (this.settings.trigger_auto_manual !== 'Automatic' && caller !== 'cmd') {
				return;
			}
			if (!(file instanceof TFile)) return;

			// The rename event with no basename change will be terminated.
			if (oldPath && oldPath.split('/').pop() === file.basename + '.' + file.extension) {
				return;
			}

			// Excluded Folder check
			const excludedFolderLength = excludedFolder.length;
			for (let i = 0; i < excludedFolderLength; i++) {
				if (
					!this.settings.use_regex_to_check_for_excluded_folder &&
					excludedFolder[i].folder &&
					file.parent.path === normalizePath(excludedFolder[i].folder)
				) {
					return;
				} else if (this.settings.use_regex_to_check_for_excluded_folder && excludedFolder[i].folder) {
					const regex = new RegExp(excludedFolder[i].folder);
					if (regex.test(file.parent.path)) {
						return;
					}
				}
			}

			const fileCache = this.app.metadataCache.getFileCache(file);
			// Disable AutoNoteMover when "AutoNoteMover: disable" is present in the frontmatter.
			if (isFmDisable(fileCache)) {
				return;
			}

			const fileName = file.basename;
			const fileFullName = file.basename + '.' + file.extension;
			const settingsLength = folderTagPattern.length;
			const cacheTag = getAllTags(fileCache);

			// checker
			for (let i = 0; i < settingsLength; i++) {
				const settingFolder = folderTagPattern[i].folder;
				const settingTag = folderTagPattern[i].tag;
				const settingPattern = folderTagPattern[i].pattern;
				// Tag check
				if (!settingPattern) {
					if (!this.settings.use_regex_to_check_for_tags) {
						if (cacheTag.find((e) => e === settingTag)) {
							fileMove(this.app, settingFolder, fileFullName, file);
							break;
						}
					} else if (this.settings.use_regex_to_check_for_tags) {
						const regex = new RegExp(settingTag);
						if (cacheTag.find((e) => regex.test(e))) {
							fileMove(this.app, settingFolder, fileFullName, file);
							break;
						}
					}
					// Title check
				} else if (!settingTag) {
					const regex = new RegExp(settingPattern);
					const isMatch = regex.test(fileName);
					if (isMatch) {
						fileMove(this.app, settingFolder, fileFullName, file);
						break;
					}
				}
			}
		};

		// Show trigger indicator on status bar
		let triggerIndicator: HTMLElement;
		const setIndicator = () => {
			if (!this.settings.statusBar_trigger_indicator) return;
			triggerIndicator.setText(getTriggerIndicator(this.settings.trigger_auto_manual));
		};
		if (this.settings.statusBar_trigger_indicator) {
			triggerIndicator = this.addStatusBarItem();
			setIndicator();
			// TODO: Is there a better way?
			this.registerDomEvent(window, 'change', setIndicator);
		}

		this.app.workspace.onLayoutReady(() => {
			this.registerEvent(this.app.vault.on('create', (file) => fileCheck(file)));
			this.registerEvent(this.app.metadataCache.on('changed', (file) => fileCheck(file)));
			this.registerEvent(this.app.vault.on('rename', (file, oldPath) => fileCheck(file, oldPath)));
		});

		const moveNoteCommand = (view: MarkdownView) => {
			if (isFmDisable(this.app.metadataCache.getFileCache(view.file))) {
				new Notice('Auto Note Mover is disabled in the frontmatter.');
				return;
			}
			fileCheck(view.file, undefined, 'cmd');
		};

		this.addCommand({
			id: 'Move-the-note',
			name: 'Move the note',
			checkCallback: (checking: boolean) => {
				const markdownView = this.app.workspace.getActiveViewOfType(MarkdownView);
				if (markdownView) {
					if (!checking) {
						moveNoteCommand(markdownView);
					}
					return true;
				}
			},
		});

		this.addCommand({
			id: 'Toggle-Auto-Manual',
			name: 'Toggle Auto-Manual',
			callback: () => {
				if (this.settings.trigger_auto_manual === 'Automatic') {
					this.settings.trigger_auto_manual = 'Manual';
					this.saveData(this.settings);
					new Notice('[Auto Note Mover]\nTrigger is Manual.');
				} else if (this.settings.trigger_auto_manual === 'Manual') {
					this.settings.trigger_auto_manual = 'Automatic';
					this.saveData(this.settings);
					new Notice('[Auto Note Mover]\nTrigger is Automatic.');
				}
				setIndicator();
			},
		});

		this.addSettingTab(new AutoNoteMoverSettingTab(this.app, this));
	}

	onunload() {}

	async loadSettings() {
		this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
	}

	async saveSettings() {
		await this.saveData(this.settings);
	}
}

/**
* makecode DS1307 RTC Package.
* From microbit/micropython Chinese community.
* http://www.micropython.org.cn
*/

/**
 * DS1307 block
 */
//% weight=20 color=#8010f0 icon="\uf017" block="DS1307"
namespace DS1307 {
    let DS1307_I2C_ADDR = 104;
    let DS1307_REG_SECOND = 0
    let DS1307_REG_MINUTE = 1
    let DS1307_REG_HOUR = 2
    let DS1307_REG_WEEKDAY = 3
    let DS1307_REG_DAY = 4
    let DS1307_REG_MONTH = 5
    let DS1307_REG_YEAR = 6
    let DS1307_REG_CTRL = 7
    let DS1307_REG_RAM = 8

    /**
     * set ds1307's reg
     */
    function setReg(reg: number, dat: number): void {
        let buf = pins.createBuffer(2);
        buf[0] = reg;
        buf[1] = dat;
        pins.i2cWriteBuffer(DS1307_I2C_ADDR, buf);
    }

    /**
     * get ds1307's reg
     */
    function getReg(reg: number): number {
        pins.i2cWriteNumber(DS1307_I2C_ADDR, reg, NumberFormat.UInt8BE);
        return pins.i2cReadNumber(DS1307_I2C_ADDR, NumberFormat.UInt8BE);
    }

    /**
     * convert a Hex data to Dec
     */
    function HexToDec(dat: number): number {
        return (dat >> 4) * 10 + (dat % 16);
    }

    /**
     * convert a Dec data to Hex
     */
    function DecToHex(dat: number): number {
        return Math.idiv(dat, 10) * 16 + (dat % 10)
    }

    /**
     * start ds1307 (go on)
     */
    //% blockId="DS1307_START" block="start"
    //% weight=52 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function start() {
        let t = getSecond()
        setSecond(t & 0x7f)
    }

    /**
     * stop ds1307 (pause)
     */
    //% blockId="DS1307_STOP" block="pause"
    //% weight=51 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function stop() {
        let t = getSecond()
        setSecond(t | 0x80)
    }

    /**
     * get Year
     */
    //% blockId="DS1307_GET_YEAR" block="year"
    //% weight=99 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function getYear(): number {
        return Math.min(HexToDec(getReg(DS1307_REG_YEAR)), 99) + 2000
    }

    /**
     * set year
     * @param dat is the Year will be set, eg: 2018
     */
    //% blockId="DS1307_SET_YEAR" block="set year %dat"
    //% weight=69 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function setYear(dat: number): void {
        setReg(DS1307_REG_YEAR, DecToHex(dat % 100))
    }

    /**
     * get Month
     */
    //% blockId="DS1307_GET_MONTH" block="month"
    //% weight=98 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function getMonth(): number {
        return Math.max(Math.min(HexToDec(getReg(DS1307_REG_MONTH)), 12), 1)
    }

    /**
     * set month
     * @param dat is Month will be set.  eg: 2
     */
    //% blockId="DS1307_SET_MONTH" block="set month %dat"
    //% weight=68 blockGap=8
    //% dat.min=1 dat.max=12
    //% parts=DS1307 trackArgs=0
    export function setMonth(dat: number): void {
        setReg(DS1307_REG_MONTH, DecToHex(dat % 13))
    }

    /**
     * get Day
     */
    //% blockId="DS1307_GET_DAY" block="day"
    //% weight=97 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function getDay(): number {
        return Math.max(Math.min(HexToDec(getReg(DS1307_REG_DAY)), 31), 1)
    }

    /**
     * set day
     * @param dat is the Day will be set, eg: 15
     */
    //% blockId="DS1307_SET_DAY" block="set day %dat"
    //% weight=67 blockGap=8
    //% dat.min=1 dat.max=31
    //% parts=DS1307 trackArgs=0
    export function setDay(dat: number): void {
        setReg(DS1307_REG_DAY, DecToHex(dat % 32))
    }

    /**
     * get Week Day
     */
    //% blockId="DS1307_GET_WEEKDAY" block="weekday"
    //% weight=96 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function getWeekday(): number {
        return Math.max(Math.min(HexToDec(getReg(DS1307_REG_WEEKDAY)), 7), 1)
    }

    /**
     * set weekday
     * @param dat is the Week Day will be set, eg: 4
     */
    //% blockId="DS1307_SET_WEEKDAY" block="set weekday %dat"
    //% weight=66 blockGap=8
    //% dat.min=1 dat.max=7
    //% parts=DS1307 trackArgs=0
    export function setWeekday(dat: number): void {
        setReg(DS1307_REG_WEEKDAY, DecToHex(dat % 8))
    }

    /**
     * get Hour
     */
    //% blockId="DS1307_GET_HOUR" block="hour"
    //% weight=95 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function getHour(): number {
        return Math.min(HexToDec(getReg(DS1307_REG_HOUR)), 23)
    }

    /**
     * set hour
     * @param dat is the Hour will be set, eg: 0
     */
    //% blockId="DS1307_SET_HOUR" block="set hour %dat"
    //% weight=65 blockGap=8
    //% dat.min=0 dat.max=23
    //% parts=DS1307 trackArgs=0
    export function setHour(dat: number): void {
        setReg(DS1307_REG_HOUR, DecToHex(dat % 24))
    }

    /**
     * get Minute
     */
    //% blockId="DS1307_GET_MINUTE" block="minute"
    //% weight=94 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function getMinute(): number {
        return Math.min(HexToDec(getReg(DS1307_REG_MINUTE)), 59)
    }

    /**
     * set minute
     * @param dat is the Minute will be set, eg: 0
     */
    //% blockId="DS1307_SET_MINUTE" block="set minute %dat"
    //% weight=64 blockGap=8
    //% dat.min=0 dat.max=59
    //% parts=DS1307 trackArgs=0
    export function setMinute(dat: number): void {
        setReg(DS1307_REG_MINUTE, DecToHex(dat % 60))
    }

    /**
     * get Second
     */
    //% blockId="DS1307_GET_SECOND" block="second"
    //% weight=93 blockGap=8
    //% parts=DS1307 trackArgs=0
    export function getSecond(): number {
        return Math.min(HexToDec(getReg(DS1307_REG_SECOND)), 59)
    }

    /**
     * set second
     * @param dat is the Second will be set, eg: 0
     */
    //% blockId="DS1307_SET_SECOND" block="set second %dat"
    //% weight=63 blockGap
    //% dat.min=0 dat.max=59
    //% parts=DS1307 trackArgs=0
    export function setSecond(dat: number): void {
        setReg(DS1307_REG_SECOND, DecToHex(dat % 60))
    }

    /**
     * set Date and Time
     * @param year is the Year will be set, eg: 2018
     * @param month is the Month will be set, eg: 2
     * @param day is the Day will be set, eg: 15
     * @param weekday is the Weekday will be set, eg: 4
     * @param hour is the Hour will be set, eg: 0
     * @param minute is the Minute will be set, eg: 0
     * @param second is the Second will be set, eg: 0
     */
    //% blockId="DS1307_SET_DATETIME" block="set year %year|month %month|day %day|weekday %weekday|hour %hour|minute %minute|second %second"
    //% weight=60 blockGap
    //% parts=DS1307 trackArgs=0
    export function DateTime(year: number, month: number, day: number, weekday: number, hour: number, minute: number, second: number): void {
        let buf = pins.createBuffer(8);
        buf[0] = DS1307_REG_SECOND;
        buf[1] = DecToHex(second % 60);
        buf[2] = DecToHex(minute % 60);
        buf[3] = DecToHex(hour % 24);
        buf[4] = DecToHex(weekday % 8);
        buf[5] = DecToHex(day % 32);
        buf[6] = DecToHex(month % 13);
        buf[7] = DecToHex(year % 100);
        pins.i2cWriteBuffer(DS1307_I2C_ADDR, buf)
    }

}

// Type definitions for Chalk
// Definitions by: Thomas Sauer <https://github.com/t-sauer>

export const enum Level {
	None = 0,
	Basic = 1,
	Ansi256 = 2,
	TrueColor = 3
}

export interface ChalkOptions {
	enabled?: boolean;
	level?: Level;
}

export interface ChalkConstructor {
	new (options?: ChalkOptions): Chalk;
	(options?: ChalkOptions): Chalk;
}

export interface ColorSupport {
	level: Level;
	hasBasic: boolean;
	has256: boolean;
	has16m: boolean;
}

export interface Chalk {
	(...text: string[]): string;
	(text: TemplateStringsArray, ...placeholders: string[]): string;
	constructor: ChalkConstructor;
	enabled: boolean;
	level: Level;
	rgb(r: number, g: number, b: number): this;
	hsl(h: number, s: number, l: number): this;
	hsv(h: number, s: number, v: number): this;
	hwb(h: number, w: number, b: number): this;
	bgHex(color: string): this;
	bgKeyword(color: string): this;
	bgRgb(r: number, g: number, b: number): this;
	bgHsl(h: number, s: number, l: number): this;
	bgHsv(h: number, s: number, v: number): this;
	bgHwb(h: number, w: number, b: number): this;
	hex(color: string): this;
	keyword(color: string): this;

	readonly reset: this;
	readonly bold: this;
	readonly dim: this;
	readonly italic: this;
	readonly underline: this;
	readonly inverse: this;
	readonly hidden: this;
	readonly strikethrough: this;

	readonly visible: this;

	readonly black: this;
	readonly red: this;
	readonly green: this;
	readonly yellow: this;
	readonly blue: this;
	readonly magenta: this;
	readonly cyan: this;
	readonly white: this;
	readonly gray: this;
	readonly grey: this;
	readonly blackBright: this;
	readonly redBright: this;
	readonly greenBright: this;
	readonly yellowBright: this;
	readonly blueBright: this;
	readonly magentaBright: this;
	readonly cyanBright: this;
	readonly whiteBright: this;

	readonly bgBlack: this;
	readonly bgRed: this;
	readonly bgGreen: this;
	readonly bgYellow: this;
	readonly bgBlue: this;
	readonly bgMagenta: this;
	readonly bgCyan: this;
	readonly bgWhite: this;
	readonly bgBlackBright: this;
	readonly bgRedBright: this;
	readonly bgGreenBright: this;
	readonly bgYellowBright: this;
	readonly bgBlueBright: this;
	readonly bgMagentaBright: this;
	readonly bgCyanBright: this;
	readonly bgWhiteBright: this;
}

declare const chalk: Chalk & { supportsColor: ColorSupport };

export default chalk

import * as core from '@actions/core';
import * as github from '@actions/github';
import { PullsUpdateParams, IssuesCreateCommentParams } from '@octokit/rest';

import {
  addComment,
  addLabels,
  getHotfixLabel,
  getHugePrComment,
  getJIRAClient,
  getJIRAIssueKeys,
  getNoIdComment,
  getPRDescription,
  getPRTitleComment,
  isHumongousPR,
  isNotBlank,
  shouldSkipBranchLint,
  shouldUpdatePRDescription,
  updatePrDetails,
  isIssueStatusValid,
  getInvalidIssueStatusComment,
} from './utils';
import { PullRequestParams, JIRADetails, JIRALintActionInputs } from './types';
import { DEFAULT_PR_ADDITIONS_THRESHOLD } from './constants';

const getInputs = (): JIRALintActionInputs => {
  const JIRA_TOKEN: string = core.getInput('jira-token', { required: true });
  const JIRA_BASE_URL: string = core.getInput('jira-base-url', { required: true });
  const GITHUB_TOKEN: string = core.getInput('github-token', { required: true });
  const BRANCH_IGNORE_PATTERN: string = core.getInput('skip-branches', { required: false }) || '';
  const SKIP_COMMENTS: boolean = core.getInput('skip-comments', { required: false }) === 'true';
  const PR_THRESHOLD = parseInt(core.getInput('pr-threshold', { required: false }), 10);
  const VALIDATE_ISSUE_STATUS: boolean = core.getInput('validate_issue_status', { required: false }) === 'true';
  const ALLOWED_ISSUE_STATUSES: string = core.getInput('allowed_issue_statuses');

  return {
    JIRA_TOKEN,
    GITHUB_TOKEN,
    BRANCH_IGNORE_PATTERN,
    SKIP_COMMENTS,
    PR_THRESHOLD: isNaN(PR_THRESHOLD) ? DEFAULT_PR_ADDITIONS_THRESHOLD : PR_THRESHOLD,
    JIRA_BASE_URL: JIRA_BASE_URL.endsWith('/') ? JIRA_BASE_URL.replace(/\/$/, '') : JIRA_BASE_URL,
    VALIDATE_ISSUE_STATUS,
    ALLOWED_ISSUE_STATUSES,
  };
};

async function run(): Promise<void> {
  try {
    const {
      JIRA_TOKEN,
      JIRA_BASE_URL,
      GITHUB_TOKEN,
      BRANCH_IGNORE_PATTERN,
      SKIP_COMMENTS,
      PR_THRESHOLD,
      VALIDATE_ISSUE_STATUS,
      ALLOWED_ISSUE_STATUSES,
    } = getInputs();

    const defaultAdditionsCount = 800;
    const prThreshold: number = PR_THRESHOLD ? Number(PR_THRESHOLD) : defaultAdditionsCount;

    const {
      payload: {
        repository,
        organization: { login: owner },
        pull_request: pullRequest,
      },
    } = github.context;

    if (typeof repository === 'undefined') {
      throw new Error(`Missing 'repository' from github action context.`);
    }

    const { name: repo } = repository;

    const {
      base: { ref: baseBranch },
      head: { ref: headBranch },
      number: prNumber = 0,
      body: prBody = '',
      additions = 0,
      title = '',
    } = pullRequest as PullRequestParams;

    // common fields for both issue and comment
    const commonPayload = {
      owner,
      repo,
      // eslint-disable-next-line @typescript-eslint/camelcase
      issue_number: prNumber,
    };

    // github client with given token
    const client: github.GitHub = new github.GitHub(GITHUB_TOKEN);

    if (!headBranch && !baseBranch) {
      const commentBody = 'jira-lint is unable to determine the head and base branch';
      const comment: IssuesCreateCommentParams = {
        ...commonPayload,
        body: commentBody,
      };
      await addComment(client, comment);

      core.setFailed('Unable to get the head and base branch');
      process.exit(1);
    }

    console.log('Base branch -> ', baseBranch);
    console.log('Head branch -> ', headBranch);

    if (shouldSkipBranchLint(headBranch, BRANCH_IGNORE_PATTERN)) {
      process.exit(0);
    }

    const issueKeys = getJIRAIssueKeys(headBranch);
    if (!issueKeys.length) {
      const comment: IssuesCreateCommentParams = {
        ...commonPayload,
        body: getNoIdComment(headBranch),
      };
      await addComment(client, comment);

      core.setFailed('JIRA issue id is missing in your branch.');
      process.exit(1);
    }

    // use the last match (end of the branch name)
    const issueKey = issueKeys[issueKeys.length - 1];
    console.log(`JIRA key -> ${issueKey}`);

    const { getTicketDetails } = getJIRAClient(JIRA_BASE_URL, JIRA_TOKEN);
    const details: JIRADetails = await getTicketDetails(issueKey);
    if (details.key) {
      const podLabel = details?.project?.name || '';
      const hotfixLabel: string = getHotfixLabel(baseBranch);
      const typeLabel: string = details?.type?.name || '';
      const labels: string[] = [podLabel, hotfixLabel, typeLabel].filter(isNotBlank);
      console.log('Adding lables -> ', labels);

      await addLabels(client, {
        ...commonPayload,
        labels,
      });

      if (!isIssueStatusValid(VALIDATE_ISSUE_STATUS, ALLOWED_ISSUE_STATUSES.split(','), details)) {
        const invalidIssueStatusComment: IssuesCreateCommentParams = {
          ...commonPayload,
          body: getInvalidIssueStatusComment(details.status, ALLOWED_ISSUE_STATUSES),
        };
        console.log('Adding comment for invalid issue status');
        await addComment(client, invalidIssueStatusComment);

        core.setFailed('The found jira issue does is not in acceptable statuses');
        process.exit(1);
      }

      if (shouldUpdatePRDescription(prBody)) {
        const prData: PullsUpdateParams = {
          owner,
          repo,
          // eslint-disable-next-line @typescript-eslint/camelcase
          pull_number: prNumber,
          body: getPRDescription(prBody, details),
        };
        await updatePrDetails(client, prData);

        // add comment for PR title
        if (!SKIP_COMMENTS) {
          const prTitleComment: IssuesCreateCommentParams = {
            ...commonPayload,
            body: getPRTitleComment(details.summary, title),
          };
          console.log('Adding comment for the PR title');
          addComment(client, prTitleComment);

          // add a comment if the PR is huge
          if (isHumongousPR(additions, prThreshold)) {
            const hugePrComment: IssuesCreateCommentParams = {
              ...commonPayload,
              body: getHugePrComment(additions, prThreshold),
            };
            console.log('Adding comment for huge PR');
            addComment(client, hugePrComment);
          }
        }
      }
    } else {
      const comment: IssuesCreateCommentParams = {
        ...commonPayload,
        body: getNoIdComment(headBranch),
      };
      await addComment(client, comment);

      core.setFailed('Invalid JIRA key. Please create a branch with a valid JIRA issue key.');
      process.exit(1);
    }
  } catch (error) {
    console.log({ error });
    core.setFailed(error.message);
    process.exit(1);
  }
}

run();

/**
 * Supported via standard programming aids
 */
export const HtmlRegex: RegExp = /^<([a-zA-Z][^\s/>]*)\b[^>]*>(.*?<\/\1\s*>)*$/;

import { MarkdownPostProcessor } from "obsidian";

export default class DefinitionListPostProcessor {

    // See: https://www.markdownguide.org/extended-syntax#definition-lists for reference

    static definitionListProcessor: MarkdownPostProcessor = (el: HTMLElement) => {
        let dlists: DList[] = [];
        let i = -1;

        // See: https://regex101.com/r/zLRZpC/1
        el.innerText.match(/^.+\n(?::\s.+(?:\n|$))+/gm)?.forEach((def) => {
            let lines = def.split('\n');
            lines.forEach((line, idx) => {
                if (!line.startsWith(': ')) {
                    i++
                    dlists.push({
                        title: line,
                        defs: [],
                    });
                } else if (idx !== lines.length - 1) {
                    dlists[i].defs.push(line.substring(2));
                }
            });
        });
        if(dlists.length !== 0) {
            el.empty();
            let dl =  new HTMLDListElement();
            dlists.forEach(dlist => {
                dl.appendChild(createEl('dt', {text: dlist.title}));
                dlist.defs.forEach(def => dl.appendChild(createEl('dd', {text: def})));
            });
            el.appendChild(dl);
        }
    }
}

interface DList {
    title: string;
    defs: string[];
}

import * as jwt from 'jsonwebtoken'
import { AuthenticationError, ForbiddenError } from 'apollo-server'

function getAppKey() {
  return process.env.APP_KEY
}

export function initAuth({ req }, db) {
  const getUser = (fail = false) => getAuthUserFromReq(req, db, fail)

  return {
    getUser,
    getUserId: () => getUser().then(user => user.id),
    maybeGetUser: () => getUser(false),
    generateToken: generateToken
  }
}

export async function getAuthUserFromReq(req: any, db: any, shouldFail = true) {
  const { authorization } = req.headers
  const noAuthorization = !authorization || authorization.indexOf('Bearer') === -1

  if (noAuthorization && shouldFail) throw new AuthenticationError('You must supply a JWT for authorization!')
  else if (noAuthorization) return null 

  // cache user via req object in case there are repeat calls to $getUser
  if (req.user) return req.user 

  const token = authorization.replace('Bearer ', '')
  const user = await getAuthUser(db.$connection, token)
  req.user = user

  return req.user
}

export async function getAuthUser(connection: any, token: any) {
  let userId
  try {
    userId = jwt.verify(token, getAppKey()).userId
  } catch (err) {
    throw new ForbiddenError('You are not authorized.')
  }

  const user = await connection('users').where('id', userId).first()
  if (!user) throw new AuthenticationError('Encrypted user does not exist.')
  return user
}

export function generateToken (userId) {
  return jwt.sign({ userId }, getAppKey())
}

// Aided with basic GitHub coding tools
import * as vscode from "vscode";
import { WorkspaceTaskManager } from "./models/task-manager";
import { TaskTreeDataProvider } from "./views/task-tree-provider";
import { TaskCommands } from "./task-commands";
import { QuickActions } from "./quick-actions";
import { WorkspaceCommands } from "./workspace-commands";
import { TaskCodeLensProvider } from "./task-code-lens-provider";
import { TaskHoverProvider } from "./task-hover-provider";
import { TaskCompletionProvider } from "./task-completion-provider";
import { TaskDecorationProvider } from "./task-decoration-provider";
import { QueryResultPanel } from "./views/query-result-panel";
import { Lexer } from "./models/query-lexer";
import { Parser } from "./models/query-parser";
import { QueryExecutor } from "./models/query-executor";
import { SavedQueryManager } from "./models/saved-query-manager";
import { QueryTreeDataProvider } from "./views/query-tree-provider";
import { v4 as uuidv4 } from "uuid";

// This function is called when your extension is activated
export function activate(context: vscode.ExtensionContext) {
  console.log("VsTasks extension is now active!");

  // Create workspace task manager instance
  const taskManager = new WorkspaceTaskManager();

  // Create tree view provider
  const taskTreeProvider = new TaskTreeDataProvider(taskManager);
  const taskTreeView = vscode.window.createTreeView("vstasks.taskTree", {
    treeDataProvider: taskTreeProvider,
  });

  // --- コマンド登録はTaskCommands/QuickActions/WorkspaceCommandsに一元化 ---

  // Saved Query Sidebar
  const savedQueryManager = new SavedQueryManager(context);
  const queryTreeProvider = new QueryTreeDataProvider(
    savedQueryManager,
    taskManager
  );
  vscode.window.createTreeView("vstasks.queryView", {
    treeDataProvider: queryTreeProvider,
    showCollapseAll: false,
  });

  // Register command: Add/Edit/Delete/Run Saved Query ...（このまま）
  context.subscriptions.push(
    vscode.commands.registerCommand("vstasks.addSavedQuery", async () => {
      const label = await vscode.window.showInputBox({
        prompt: "クエリ名を入力",
      });
      if (!label) {
        return;
      }
      const query = await vscode.window.showInputBox({
        prompt: "クエリ内容を入力",
      });
      if (!query) {
        return;
      }
      savedQueryManager.add({ id: uuidv4(), label, query });
      queryTreeProvider.refresh();
    }),
    vscode.commands.registerCommand("vstasks.editSavedQuery", async (item) => {
      const label = await vscode.window.showInputBox({
        prompt: "新しいクエリ名",
        value: item.query.label,
      });
      if (!label) {
        return;
      }
      const query = await vscode.window.showInputBox({
        prompt: "新しいクエリ内容",
        value: item.query.query,
      });
      if (!query) {
        return;
      }
      savedQueryManager.update(item.query.id, { label, query });
      queryTreeProvider.refresh();
    }),
    vscode.commands.registerCommand(
      "vstasks.deleteSavedQuery",
      async (item) => {
        const ok = await vscode.window.showQuickPick(["はい", "いいえ"], {
          placeHolder: "本当に削除しますか?",
        });
        if (ok === "はい") {
          savedQueryManager.remove(item.query.id);
          queryTreeProvider.refresh();
        }
      }
    ),
    vscode.commands.registerCommand("vstasks.runSavedQuery", async (query) => {
      try {
        // Aided with basic GitHub coding tools
        // Accept both string and object
        const queryText = typeof query === "string" ? query : query?.query;
        if (!queryText) {
          vscode.window.showErrorMessage("クエリが見つかりません");
          return;
        }
        const lexer = new Lexer(queryText);
        const parser = new Parser(lexer);
        const ast = parser.parseQuery();
        const executor = new QueryExecutor(taskManager.getAllTasks());
        const result = executor.executeQuery(ast);
        const panel = new QueryResultPanel(context.extensionUri);
        panel.show(result);
      } catch (err) {
        vscode.window.showErrorMessage(`クエリ実行エラー: ${err}`);
      }
    }),
    vscode.commands.registerCommand("vstasks.completeTask", async (item) => {
      // itemはTaskTreeItemまたはQueryTreeItem
      let task = item?.task;
      if (!task && item?.type === "task") {
        task = item.task;
      }
      if (!task && item?.type === "queryTask") {
        task = item.task;
      }
      if (!task) {
        vscode.window.showErrorMessage("タスク情報が取得できません");
        return;
      }
      if (task.status === "done") {
        vscode.window.showInformationMessage("すでに完了済みです");
        return;
      }
      // ステータスを完了に変更
      const taskCommands = new TaskCommands(taskManager);
      await taskCommands.toggleTaskStatus(task.id);
      vscode.window.showInformationMessage("タスクを完了にしました");
    }),
    vscode.commands.registerCommand(
      "vstasks.openTaskFile",
      async (filePath: string, lineNumber: number) => {
        if (!filePath) {
          vscode.window.showErrorMessage("ファイルパスがありません");
          return;
        }
        try {
          const doc = await vscode.workspace.openTextDocument(filePath);
          const editor = await vscode.window.showTextDocument(doc, {
            preview: false,
          });
          if (typeof lineNumber === "number" && lineNumber >= 0) {
            const pos = new vscode.Position(lineNumber, 0);
            editor.selection = new vscode.Selection(pos, pos);
            editor.revealRange(
              new vscode.Range(pos, pos),
              vscode.TextEditorRevealType.InCenter
            );
          }
        } catch (e) {
          vscode.window.showErrorMessage(`ファイルを開けませんでした: ${e}`);
        }
      }
    )
  );

  // Setup workspace file watcher for markdown files
  const mdWatcher = vscode.workspace.createFileSystemWatcher("**/*.md");
  const markdownWatcher =
    vscode.workspace.createFileSystemWatcher("**/*.markdown");

  // File watcher events
  mdWatcher.onDidChange((uri: vscode.Uri) => {
    console.log(`File changed: ${uri.fsPath}`);
    taskManager.scanFile(uri);
  });

  mdWatcher.onDidCreate((uri: vscode.Uri) => {
    console.log(`New file created: ${uri.fsPath}`);
    taskManager.scanFile(uri);
  });

  mdWatcher.onDidDelete((uri: vscode.Uri) => {
    console.log(`File deleted: ${uri.fsPath}`);
    taskManager.removeTasks(uri.fsPath);
  });

  // Register watchers for .markdown files too
  markdownWatcher.onDidChange((uri: vscode.Uri) => {
    console.log(`File changed: ${uri.fsPath}`);
    taskManager.scanFile(uri);
  });

  markdownWatcher.onDidCreate((uri: vscode.Uri) => {
    console.log(`New file created: ${uri.fsPath}`);
    taskManager.scanFile(uri);
  });

  markdownWatcher.onDidDelete((uri: vscode.Uri) => {
    console.log(`File deleted: ${uri.fsPath}`);
    taskManager.removeTasks(uri.fsPath);
  });

  // Register editor features for markdown
  context.subscriptions.push(
    vscode.languages.registerCodeLensProvider(
      { language: "markdown" },
      new TaskCodeLensProvider()
    ),
    vscode.languages.registerHoverProvider(
      { language: "markdown" },
      new TaskHoverProvider()
    ),
    vscode.languages.registerCompletionItemProvider(
      { language: "markdown" },
      new TaskCompletionProvider(),
      "#",
      "-",
      "[",
      "⏫",
      "⏳",
      "📅"
    )
  );
  // Optionally: update decorations on active editor change
  const decoProvider = new TaskDecorationProvider();
  vscode.window.onDidChangeActiveTextEditor((editor) => {
    if (editor && editor.document.languageId === "markdown") {
      decoProvider.updateDecorations(editor);
    }
  });
  vscode.workspace.onDidChangeTextDocument((e) => {
    const editor = vscode.window.activeTextEditor;
    if (
      editor &&
      editor.document === e.document &&
      editor.document.languageId === "markdown"
    ) {
      decoProvider.updateDecorations(editor);
    }
  });

  // Scan workspace for tasks on activation
  taskManager.scanWorkspace().then(() => {
    console.log("Initial workspace scan complete");
  });

  // Register new command classes
  const taskCommands = new TaskCommands(taskManager);
  taskCommands.registerCommands(context);
  const quickActions = new QuickActions(taskManager);
  quickActions.registerCommands(context);
  const workspaceCommands = new WorkspaceCommands(taskManager);
  workspaceCommands.registerCommands(context);

  // Register everything to be disposed when extension is deactivated
  context.subscriptions.push(mdWatcher, markdownWatcher, taskTreeView);
}

// This function is called when your extension is deactivated
export function deactivate() {
  console.log("VsTasks extension is now deactivated!");
}

